INSERT INTO "drinks" ("id", "name", "category", "alcoholic", "glass", "iba", "tags", "image", "video", "instructions_en", "instructions_es", "ingredients") VALUES
  ('11000', 'Mojito', 'Cocktail', true, 'Highball glass', 'Contemporary Classics', '{IBA,ContemporaryClassic,Alcoholic,USA,Asia,Vegan,Citrus,Brunch,Hangover,Mild}'::text[], 'https://www.thecocktaildb.com/images/media/drink/metwgh1606770327.jpg', NULL, 'Muddle mint leaves with sugar and lime juice. Add a splash of soda water and fill the glass with cracked ice. Pour the rum and top with soda water. Garnish and serve with straw.', 'Mezcle las hojas de menta con el azúcar y el zumo de lima. Añada un chorrito de soda y llene el vaso con hielo picado. Verter el ron y completar con soda. Decorar y servir con pajita.', '[{"name": "Light rum", "image": "https://www.thecocktaildb.com/images/ingredients/Light%20rum-small.png", "measure": "2-3 oz"}, {"name": "Lime", "image": "https://www.thecocktaildb.com/images/ingredients/Lime-small.png", "measure": "Juice of 1"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "2 tsp"}, {"name": "Mint", "image": "https://www.thecocktaildb.com/images/ingredients/Mint-small.png", "measure": "2-4"}, {"name": "Soda water", "image": "https://www.thecocktaildb.com/images/ingredients/Soda%20water-small.png", "measure": null}]'::jsonb),
  ('11001', 'Old Fashioned', 'Cocktail', true, 'Old-fashioned glass', 'Unforgettables', '{IBA,Classic,Alcoholic,Expensive,Savory}'::text[], 'https://www.thecocktaildb.com/images/media/drink/vrwquq1478252802.jpg', 'https://www.youtube.com/watch?v=YsE_igrPXZs', 'Place sugar cube in old fashioned glass and saturate with bitters, add a dash of plain water. Muddle until dissolved.
Fill the glass with ice cubes and add whiskey.

Garnish with orange twist, and a cocktail cherry.', 'Ponga el terrón de azúcar en un vaso old fashioned y úntelo con el amargo, añada un chorrito de agua. Mezcle hasta que se disuelva.
Llene el vaso con cubitos de hielo y añada whisky.

Decorar con un twist de naranja y una cereza de cóctel.', '[{"name": "Bourbon", "image": "https://www.thecocktaildb.com/images/ingredients/Bourbon-small.png", "measure": "4.5 cL"}, {"name": "Angostura bitters", "image": "https://www.thecocktaildb.com/images/ingredients/Angostura%20bitters-small.png", "measure": "2 dashes"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "1 cube"}, {"name": "Water", "image": "https://www.thecocktaildb.com/images/ingredients/Water-small.png", "measure": "dash"}]'::jsonb),
  ('11002', 'Long Island Tea', 'Ordinary Drink', true, 'Highball glass', NULL, '{Strong,Asia,StrongFlavor,Brunch,Vegetarian,Sour}'::text[], 'https://www.thecocktaildb.com/images/media/drink/nkwr4c1606770558.jpg', NULL, 'Combine all ingredients (except cola) and pour over ice in a highball glass. Add the splash of cola for color. Decorate with a slice of lemon and serve.', 'Mezcle todos los ingredientes (excepto el refresco de cola) y viértalos sobre hielo en un vaso highball. Añada el chorrito de cola para darle color. Decore con una rodaja de limón y sirva.', '[{"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "1/2 oz"}, {"name": "Light rum", "image": "https://www.thecocktaildb.com/images/ingredients/Light%20rum-small.png", "measure": "1/2 oz"}, {"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "1/2 oz"}, {"name": "Tequila", "image": "https://www.thecocktaildb.com/images/ingredients/Tequila-small.png", "measure": "1/2 oz"}, {"name": "Lemon", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon-small.png", "measure": "Juice of 1/2"}, {"name": "Coca-Cola", "image": "https://www.thecocktaildb.com/images/ingredients/Coca-Cola-small.png", "measure": "1 splash"}]'::jsonb),
  ('11003', 'Negroni', 'Ordinary Drink', true, 'Old-fashioned glass', 'Unforgettables', '{IBA,Classic}'::text[], 'https://www.thecocktaildb.com/images/media/drink/qgdu971561574065.jpg', 'https://www.youtube.com/watch?v=Y4LH0FQlU8Q', 'Stir into glass over ice, garnish and serve.', 'Remover en un vaso con hielo, decorar y servir.', '[{"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "1 oz"}, {"name": "Campari", "image": "https://www.thecocktaildb.com/images/ingredients/Campari-small.png", "measure": "1 oz"}, {"name": "Sweet Vermouth", "image": "https://www.thecocktaildb.com/images/ingredients/Sweet%20Vermouth-small.png", "measure": "1 oz"}]'::jsonb),
  ('11004', 'Whiskey Sour', 'Ordinary Drink', true, 'Old-fashioned glass', 'Unforgettables', '{IBA,Classic,Alcoholic,ContemporaryClassic}'::text[], 'https://www.thecocktaildb.com/images/media/drink/hbkfsh1589574990.jpg', 'https://www.youtube.com/watch?v=hFKZPzfngcU', 'Shake with ice. Strain into chilled glass, garnish and serve. If served ''On the rocks'', strain ingredients into old-fashioned glass filled with ice.', 'Agitar con hielo. Colar en un vaso frío, decorar y servir. Si se sirve con hielo, colar los ingredientes en un vaso old-fashioned lleno de hielo.', '[{"name": "Blended whiskey", "image": "https://www.thecocktaildb.com/images/ingredients/Blended%20whiskey-small.png", "measure": "2 oz"}, {"name": "Lemon", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon-small.png", "measure": "Juice of 1/2"}, {"name": "Powdered sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Powdered%20sugar-small.png", "measure": "1/2 tsp"}, {"name": "Cherry", "image": "https://www.thecocktaildb.com/images/ingredients/Cherry-small.png", "measure": "1"}, {"name": "Lemon", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon-small.png", "measure": "1/2 slice"}]'::jsonb),
  ('11005', 'Dry Martini', 'Cocktail', true, 'Cocktail glass', 'Unforgettables', '{IBA,Classic,Christmas,Alcoholic}'::text[], 'https://www.thecocktaildb.com/images/media/drink/6ck9yi1589574317.jpg', NULL, 'Straight: Pour all ingredients into mixing glass with ice cubes. Stir well. Strain in chilled martini cocktail glass. Squeeze oil from lemon peel onto the drink, or garnish with olive.', 'Derecho: Vierta todos los ingredientes en un vaso mezclador con cubitos de hielo. Remover bien. Colar en una copa de martini fría. Exprima el aceite de la cáscara de limón sobre la bebida, o decore con aceitunas.', '[{"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "1 2/3 oz"}, {"name": "Dry Vermouth", "image": "https://www.thecocktaildb.com/images/ingredients/Dry%20Vermouth-small.png", "measure": "1/3 oz"}, {"name": "Olive", "image": "https://www.thecocktaildb.com/images/ingredients/Olive-small.png", "measure": "1"}]'::jsonb),
  ('11006', 'Daiquiri', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{IBA,Classic,Beach}'::text[], 'https://www.thecocktaildb.com/images/media/drink/mrz9091589574515.jpg', NULL, 'Pour all ingredients into shaker with ice cubes. Shake well. Strain in chilled cocktail glass.', 'Vierta todos los ingredientes en una coctelera con cubitos de hielo. Agitar bien. Colar en una copa de cóctel fría.', '[{"name": "Light rum", "image": "https://www.thecocktaildb.com/images/ingredients/Light%20rum-small.png", "measure": "1 1/2 oz"}, {"name": "Lime", "image": "https://www.thecocktaildb.com/images/ingredients/Lime-small.png", "measure": "Juice of 1/2"}, {"name": "Powdered sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Powdered%20sugar-small.png", "measure": "1 tsp"}]'::jsonb),
  ('11007', 'Margarita', 'Ordinary Drink', true, 'Cocktail glass', 'Contemporary Classics', '{IBA,ContemporaryClassic}'::text[], 'https://www.thecocktaildb.com/images/media/drink/5noda61589575158.jpg', NULL, 'Rub the rim of the glass with the lime slice to make the salt stick to it. Take care to moisten only the outer rim and sprinkle the salt on it. The salt should present to the lips of the imbiber and never mix into the cocktail. Shake the other ingredients with ice, then carefully pour into the glass.', 'Frota el borde del vaso con la rodaja de lima para que la sal se adhiera a él. Procure humedecer sólo el borde exterior y espolvorear la sal sobre él. La sal debe presentarse en los labios del imbibidor y nunca mezclarse en el cóctel. Agite los demás ingredientes con hielo y viértalos con cuidado en el vaso.', '[{"name": "Tequila", "image": "https://www.thecocktaildb.com/images/ingredients/Tequila-small.png", "measure": "1 1/2 oz"}, {"name": "Triple sec", "image": "https://www.thecocktaildb.com/images/ingredients/Triple%20sec-small.png", "measure": "1/2 oz"}, {"name": "Lime juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lime%20juice-small.png", "measure": "1 oz"}, {"name": "Salt", "image": "https://www.thecocktaildb.com/images/ingredients/Salt-small.png", "measure": null}]'::jsonb),
  ('11008', 'Manhattan', 'Cocktail', true, 'Cocktail glass', 'Unforgettables', '{IBA,Classic,Alcoholic}'::text[], 'https://www.thecocktaildb.com/images/media/drink/yk70e31606771240.jpg', 'https://www.youtube.com/watch?v=TFWPtkNoF4Y', 'Stirred over ice, strained into a chilled glass, garnished, and served up.', 'Se remueve con hielo, se cuela en un vaso frío, se adorna y se sirve.', '[{"name": "Sweet Vermouth", "image": "https://www.thecocktaildb.com/images/ingredients/Sweet%20Vermouth-small.png", "measure": "3/4 oz"}, {"name": "Bourbon", "image": "https://www.thecocktaildb.com/images/ingredients/Bourbon-small.png", "measure": "2 1/2 oz Blended"}, {"name": "Angostura bitters", "image": "https://www.thecocktaildb.com/images/ingredients/Angostura%20bitters-small.png", "measure": "dash"}, {"name": "Ice", "image": "https://www.thecocktaildb.com/images/ingredients/Ice-small.png", "measure": "2 or 3"}, {"name": "Maraschino cherry", "image": "https://www.thecocktaildb.com/images/ingredients/Maraschino%20cherry-small.png", "measure": "1"}, {"name": "Orange peel", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20peel-small.png", "measure": "1 twist of"}]'::jsonb),
  ('11009', 'Moscow Mule', 'Punch / Party Drink', true, 'Copper Mug', 'Contemporary Classics', '{IBA,ContemporaryClassic}'::text[], 'https://www.thecocktaildb.com/images/media/drink/3pylqc1504370988.jpg', NULL, 'Combine vodka and ginger beer in a highball glass filled with ice. Add lime juice. Stir gently. Garnish.', 'Mezcle el vodka y la cerveza de jengibre en un vaso highball lleno de hielo. Añada el zumo de lima. Remover suavemente. Decorar.', '[{"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "2 oz"}, {"name": "Lime juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lime%20juice-small.png", "measure": "2 oz"}, {"name": "Ginger ale", "image": "https://www.thecocktaildb.com/images/ingredients/Ginger%20ale-small.png", "measure": "8 oz"}]'::jsonb),
  ('11014', 'Alexander', 'Ordinary Drink', true, 'Cocktail glass', 'Unforgettables', '{IBA,Classic,Dairy}'::text[], 'https://www.thecocktaildb.com/images/media/drink/0clus51606772388.jpg', 'https://www.youtube.com/watch?v=qEhRK_v2w2g', 'Shake all ingredients with ice and strain contents into a cocktail glass. Sprinkle nutmeg on top and serve.', 'Agite todos los ingredientes con hielo y cuele el contenido en una copa de cóctel. Espolvorear nuez moscada por encima y servir.', '[{"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "1/2 oz"}, {"name": "Creme de Cacao", "image": "https://www.thecocktaildb.com/images/ingredients/Creme%20de%20Cacao-small.png", "measure": "1/2 oz white"}, {"name": "Light cream", "image": "https://www.thecocktaildb.com/images/ingredients/Light%20cream-small.png", "measure": "2 oz"}, {"name": "Nutmeg", "image": "https://www.thecocktaildb.com/images/ingredients/Nutmeg-small.png", "measure": null}]'::jsonb),
  ('11020', 'Algonquin', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/uwryxx1483387873.jpg', NULL, 'Combine and shake all ingredients with ice, strain contents into a cocktail glass, and serve.', 'Mezclar y agitar todos los ingredientes con hielo, colar el contenido en una copa de cóctel y servir.', '[{"name": "Blended whiskey", "image": "https://www.thecocktaildb.com/images/ingredients/Blended%20whiskey-small.png", "measure": "1 1/2 oz"}, {"name": "Dry Vermouth", "image": "https://www.thecocktaildb.com/images/ingredients/Dry%20Vermouth-small.png", "measure": "1 oz"}, {"name": "Pineapple juice", "image": "https://www.thecocktaildb.com/images/ingredients/Pineapple%20juice-small.png", "measure": "1 oz"}]'::jsonb),
  ('11021', 'Allegheny', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/uwvyts1483387934.jpg', NULL, 'Shake all ingredients (except lemon peel) with ice and strain into a cocktail glass. Top with the twist of lemon peel and serve.', 'Agitar todos los ingredientes (excepto la piel de limón) con hielo y colar en una copa de cóctel. Añadir el twist de piel de limón y servir.', '[{"name": "Dry Vermouth", "image": "https://www.thecocktaildb.com/images/ingredients/Dry%20Vermouth-small.png", "measure": "1 oz"}, {"name": "Bourbon", "image": "https://www.thecocktaildb.com/images/ingredients/Bourbon-small.png", "measure": "1 oz"}, {"name": "Blackberry brandy", "image": "https://www.thecocktaildb.com/images/ingredients/Blackberry%20brandy-small.png", "measure": "1 1/2 tsp"}, {"name": "Lemon juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20juice-small.png", "measure": "1 1/2 tsp"}, {"name": "Lemon peel", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20peel-small.png", "measure": "1 twist of"}]'::jsonb),
  ('11023', 'Almeria', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/rwsyyu1483388181.jpg', NULL, 'In a shaker half-filled with ice cubes, combine all of the ingredients. Shake well. Strain into a cocktail glass.', 'En una coctelera llena hasta la mitad con cubitos de hielo, mezcle todos los ingredientes. Agitar bien. Colar en una copa de cóctel.', '[{"name": "Dark rum", "image": "https://www.thecocktaildb.com/images/ingredients/Dark%20rum-small.png", "measure": "2 oz"}, {"name": "Kahlua", "image": "https://www.thecocktaildb.com/images/ingredients/Kahlua-small.png", "measure": "1 oz"}, {"name": "Egg white", "image": "https://www.thecocktaildb.com/images/ingredients/Egg%20white-small.png", "measure": "1"}]'::jsonb),
  ('11046', 'Applecar', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/sbffau1504389764.jpg', NULL, 'Shake all ingredients with ice, strain into a cocktail glass, and serve.', 'Agitar todos los ingredientes con hielo, colar en una copa de cóctel y servir.', '[{"name": "Applejack", "image": "https://www.thecocktaildb.com/images/ingredients/Applejack-small.png", "measure": "1 oz"}, {"name": "Triple sec", "image": "https://www.thecocktaildb.com/images/ingredients/Triple%20sec-small.png", "measure": "1 oz"}, {"name": "Lemon juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20juice-small.png", "measure": "1 oz"}]'::jsonb),
  ('11055', 'Artillery', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/g1vnbe1493067747.jpg', NULL, 'Stir all ingredients with ice, strain into a cocktail glass, and serve.', 'Remover todos los ingredientes con hielo, colar en una copa de cóctel y servir.', '[{"name": "Sweet Vermouth", "image": "https://www.thecocktaildb.com/images/ingredients/Sweet%20Vermouth-small.png", "measure": "1 1/2 tsp"}, {"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "1 1/2 oz"}, {"name": "Bitters", "image": "https://www.thecocktaildb.com/images/ingredients/Bitters-small.png", "measure": "2 dashes"}]'::jsonb),
  ('11060', 'Balmoral', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/vysuyq1441206297.jpg', NULL, 'In a mixing glass half-filled with ice cubes, combine all of the ingredients. Stir well. Strain into a cocktail glass.', 'En un vaso mezclador lleno hasta la mitad con cubitos de hielo, mezcle todos los ingredientes. Remover bien. Colar en una copa de cóctel.', '[{"name": "Scotch", "image": "https://www.thecocktaildb.com/images/ingredients/Scotch-small.png", "measure": "1 1/2 oz"}, {"name": "Sweet Vermouth", "image": "https://www.thecocktaildb.com/images/ingredients/Sweet%20Vermouth-small.png", "measure": "1/2 oz"}, {"name": "Dry Vermouth", "image": "https://www.thecocktaildb.com/images/ingredients/Dry%20Vermouth-small.png", "measure": "1/2 oz"}, {"name": "Bitters", "image": "https://www.thecocktaildb.com/images/ingredients/Bitters-small.png", "measure": "2 dashes"}]'::jsonb),
  ('11106', 'Blackthorn', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/dgj92f1616098672.jpg', NULL, 'Stir sloe gin and vermouth with ice and strain into a cocktail glass. Add the twist of lemon peel and serve.', 'Remover la ginebra de endrinas y el vermut con hielo y colar en una copa de cóctel. Añadir el twist de piel de limón y servir.', '[{"name": "Sweet Vermouth", "image": "https://www.thecocktaildb.com/images/ingredients/Sweet%20Vermouth-small.png", "measure": "1 oz"}, {"name": "Sloe gin", "image": "https://www.thecocktaildb.com/images/ingredients/Sloe%20gin-small.png", "measure": "1 1/2 oz"}, {"name": "Lemon peel", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20peel-small.png", "measure": "1 twist of"}]'::jsonb),
  ('11113', 'Bloody Mary', 'Ordinary Drink', true, 'Old-fashioned glass', 'Contemporary Classics', '{IBA,ContemporaryClassic}'::text[], 'https://www.thecocktaildb.com/images/media/drink/t6caa21582485702.jpg', NULL, 'Stirring gently, pour all ingredients into highball glass. Garnish.', 'Remover suavemente y verter todos los ingredientes en un vaso highball. Decorar.', '[{"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "1 1/2 oz"}, {"name": "Tomato juice", "image": "https://www.thecocktaildb.com/images/ingredients/Tomato%20juice-small.png", "measure": "3 oz"}, {"name": "Lemon juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20juice-small.png", "measure": "1 dash"}, {"name": "Worcestershire sauce", "image": "https://www.thecocktaildb.com/images/ingredients/Worcestershire%20sauce-small.png", "measure": "1/2 tsp"}, {"name": "Tabasco sauce", "image": "https://www.thecocktaildb.com/images/ingredients/Tabasco%20sauce-small.png", "measure": "2-3 drops"}, {"name": "Lime", "image": "https://www.thecocktaildb.com/images/ingredients/Lime-small.png", "measure": "1 wedge"}]'::jsonb),
  ('11120', 'Bluebird', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/5jhyd01582579843.jpg', NULL, 'In a mixing glass half-filled with crushed ice, combine the gin, triple sec, Curacao, and bitters. Stir well. Strain into a cocktail glass and garnish with the lemon twist and the cherry.', 'En un vaso mezclador lleno hasta la mitad con hielo picado, mezcle la ginebra, el triple sec, el Curaçao y el amargo. Remover bien. Colar en una copa de cóctel y decorar con el twist de limón y la cereza.', '[{"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "1 1/2 oz"}, {"name": "Triple sec", "image": "https://www.thecocktaildb.com/images/ingredients/Triple%20sec-small.png", "measure": "1/2 oz"}, {"name": "Blue Curacao", "image": "https://www.thecocktaildb.com/images/ingredients/Blue%20Curacao-small.png", "measure": "1/2 oz"}, {"name": "Bitters", "image": "https://www.thecocktaildb.com/images/ingredients/Bitters-small.png", "measure": "2 dashes"}, {"name": "Maraschino cherry", "image": "https://www.thecocktaildb.com/images/ingredients/Maraschino%20cherry-small.png", "measure": "1"}, {"name": "Lemon peel", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20peel-small.png", "measure": "1 twist of"}]'::jsonb),
  ('11124', 'Boomerang', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/3m6yz81504389551.jpg', NULL, 'In a mixing glass half-filled with ice cubes, combine the gin, vermouth, bitters, and maraschino liqueur. Stir well. Strain into a cocktail glass and garnish with the cherry.', 'En un vaso mezclador lleno hasta la mitad con cubitos de hielo, mezcle la ginebra, el vermut, el amargo y el licor de marrasquino. Remover bien. Colar en una copa de cóctel y decorar con la cereza.', '[{"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "2 oz"}, {"name": "Dry Vermouth", "image": "https://www.thecocktaildb.com/images/ingredients/Dry%20Vermouth-small.png", "measure": "1/2 oz"}, {"name": "Bitters", "image": "https://www.thecocktaildb.com/images/ingredients/Bitters-small.png", "measure": "2 dashes"}, {"name": "Maraschino liqueur", "image": "https://www.thecocktaildb.com/images/ingredients/Maraschino%20liqueur-small.png", "measure": "1/2 tsp"}, {"name": "Maraschino cherry", "image": "https://www.thecocktaildb.com/images/ingredients/Maraschino%20cherry-small.png", "measure": "1"}]'::jsonb),
  ('11129', 'Boston Sour', 'Ordinary Drink', true, 'Whiskey sour glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/kxlgbi1504366100.jpg', NULL, 'Shake juice of lemon, powdered sugar, blended whiskey, and egg white with cracked ice and strain into a whiskey sour glass. Add the slice of lemon, top with the cherry, and serve.', 'Agitar el zumo de limón, el azúcar en polvo, el whisky mezclado y la clara de huevo con hielo picado y colar en un vaso de whisky sour. Añadir la rodaja de limón, coronar con la cereza y servir.', '[{"name": "Blended whiskey", "image": "https://www.thecocktaildb.com/images/ingredients/Blended%20whiskey-small.png", "measure": "2 oz"}, {"name": "Lemon", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon-small.png", "measure": "Juice of 1/2"}, {"name": "Powdered sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Powdered%20sugar-small.png", "measure": "1 tsp"}, {"name": "Egg white", "image": "https://www.thecocktaildb.com/images/ingredients/Egg%20white-small.png", "measure": "1"}, {"name": "Lemon", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon-small.png", "measure": "1 slice"}, {"name": "Cherry", "image": "https://www.thecocktaildb.com/images/ingredients/Cherry-small.png", "measure": "1"}]'::jsonb),
  ('11149', 'Boxcar', 'Ordinary Drink', true, 'Whiskey sour glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/pwgtpa1504366376.jpg', NULL, 'In a shaker half-filled with ice cubes, combine all of the ingredients. Shake well. Strain into a sour glass.', 'En una coctelera llena hasta la mitad con cubitos de hielo, mezcle todos los ingredientes. Agitar bien. Colar en un vaso sour.', '[{"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "1 1/2 oz"}, {"name": "Triple sec", "image": "https://www.thecocktaildb.com/images/ingredients/Triple%20sec-small.png", "measure": "1 oz"}, {"name": "Lemon juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20juice-small.png", "measure": "1 tsp"}, {"name": "Grenadine", "image": "https://www.thecocktaildb.com/images/ingredients/Grenadine-small.png", "measure": "1/2 tsp"}, {"name": "Egg white", "image": "https://www.thecocktaildb.com/images/ingredients/Egg%20white-small.png", "measure": "1"}]'::jsonb),
  ('11202', 'Caipirinha', 'Ordinary Drink', true, 'Old-fashioned glass', 'Contemporary Classics', '{ContemporaryClassic,IBA}'::text[], 'https://www.thecocktaildb.com/images/media/drink/jgvn7p1582484435.jpg', NULL, 'Place lime and sugar into old fashioned glass and muddle (mash the two ingredients together using a muddler or a wooden spoon). Fill the glass with ice and add the Cachaça.', 'Poner la lima y el azúcar en un vaso old fashioned y mezclar (triturar los dos ingredientes con un machacador o una cuchara de madera). Llene el vaso con hielo y añada la cachaça.', '[{"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "2 tsp"}, {"name": "Lime", "image": "https://www.thecocktaildb.com/images/ingredients/Lime-small.png", "measure": "1"}, {"name": "Cachaca", "image": "https://www.thecocktaildb.com/images/ingredients/Cachaca-small.png", "measure": "2 1/2 oz"}]'::jsonb),
  ('11222', 'Casa Blanca', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/usspxq1441553762.jpg', NULL, 'Shake all ingredients with ice, strain into a cocktail glass, and serve.', 'Agitar todos los ingredientes con hielo, colar en una copa de cóctel y servir.', '[{"name": "Light rum", "image": "https://www.thecocktaildb.com/images/ingredients/Light%20rum-small.png", "measure": "2 oz"}, {"name": "Triple sec", "image": "https://www.thecocktaildb.com/images/ingredients/Triple%20sec-small.png", "measure": "1 1/2 tsp"}, {"name": "Lime juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lime%20juice-small.png", "measure": "1 1/2 tsp"}, {"name": "Maraschino liqueur", "image": "https://www.thecocktaildb.com/images/ingredients/Maraschino%20liqueur-small.png", "measure": "1 1/2 tsp"}]'::jsonb),
  ('11224', 'Casino Royale', 'Ordinary Drink', true, 'Whiskey sour glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/3qpv121504366699.jpg', NULL, 'In a shaker half-filled with ice cubes, combine all of the ingredients. Shake well. Strain into a sour glass.', 'En una coctelera llena hasta la mitad con cubitos de hielo, mezcle todos los ingredientes. Agitar bien. Colar en un vaso sour.', '[{"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "2 oz"}, {"name": "Lemon juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20juice-small.png", "measure": "1/2 oz"}, {"name": "Maraschino liqueur", "image": "https://www.thecocktaildb.com/images/ingredients/Maraschino%20liqueur-small.png", "measure": "1 tsp"}, {"name": "Orange bitters", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20bitters-small.png", "measure": "1 dash"}, {"name": "Egg yolk", "image": "https://www.thecocktaildb.com/images/ingredients/Egg%20yolk-small.png", "measure": "1"}]'::jsonb),
  ('11239', 'Cherry Rum', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/twsuvr1441554424.jpg', NULL, 'Shake all ingredients with ice, strain into a cocktail glass, and serve.', 'Agitar todos los ingredientes con hielo, colar en una copa de cóctel y servir.', '[{"name": "Light rum", "image": "https://www.thecocktaildb.com/images/ingredients/Light%20rum-small.png", "measure": "1 1/4 oz"}, {"name": "Cherry brandy", "image": "https://www.thecocktaildb.com/images/ingredients/Cherry%20brandy-small.png", "measure": "1 1/2 tsp"}, {"name": "Light cream", "image": "https://www.thecocktaildb.com/images/ingredients/Light%20cream-small.png", "measure": "1 tblsp"}]'::jsonb),
  ('11242', 'Chicago Fizz', 'Ordinary Drink', true, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/qwvwqr1441207763.jpg', NULL, 'Shake all ingredients (except carbonated water) with ice and strain into a highball glass over two ice cubes. Fill with carbonated water, stir, and serve.', 'Agitar todos los ingredientes (excepto el agua carbonatada) con hielo y colar en un vaso highball sobre dos cubitos de hielo. Rellenar con agua carbonatada, remover y servir.', '[{"name": "Light rum", "image": "https://www.thecocktaildb.com/images/ingredients/Light%20rum-small.png", "measure": "1 oz"}, {"name": "Port", "image": "https://www.thecocktaildb.com/images/ingredients/Port-small.png", "measure": "1 oz"}, {"name": "Lemon", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon-small.png", "measure": "Juice of 1/2"}, {"name": "Powdered sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Powdered%20sugar-small.png", "measure": "1 tsp"}, {"name": "Egg white", "image": "https://www.thecocktaildb.com/images/ingredients/Egg%20white-small.png", "measure": "1"}, {"name": "Carbonated water", "image": "https://www.thecocktaildb.com/images/ingredients/Carbonated%20water-small.png", "measure": null}]'::jsonb),
  ('11251', 'City Slicker', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/dazdlg1504366949.jpg', NULL, 'In a shaker half-filled with ice cubes, combine all of the ingredients. Shake well. Strain into a cocktail glass.', 'En una coctelera llena hasta la mitad con cubitos de hielo, mezcle todos los ingredientes. Agitar bien. Colar en una copa de cóctel.', '[{"name": "Brandy", "image": "https://www.thecocktaildb.com/images/ingredients/Brandy-small.png", "measure": "2 oz"}, {"name": "Triple sec", "image": "https://www.thecocktaildb.com/images/ingredients/Triple%20sec-small.png", "measure": "1/2 oz"}, {"name": "Lemon juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20juice-small.png", "measure": "1 tblsp"}]'::jsonb),
  ('11255', 'Clove Cocktail', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/qxvtst1461867579.jpg', NULL, 'Stir all ingredients with ice, strain into a cocktail glass, and serve.', 'Remover todos los ingredientes con hielo, colar en una copa de cóctel y servir.', '[{"name": "Sweet Vermouth", "image": "https://www.thecocktaildb.com/images/ingredients/Sweet%20Vermouth-small.png", "measure": "1 oz"}, {"name": "Sloe gin", "image": "https://www.thecocktaildb.com/images/ingredients/Sloe%20gin-small.png", "measure": "1/2 oz"}, {"name": "Wine", "image": "https://www.thecocktaildb.com/images/ingredients/Wine-small.png", "measure": "1/2 oz Muscatel"}]'::jsonb),
  ('11288', 'Cuba Libre', 'Ordinary Drink', true, 'Highball glass', 'Contemporary Classics', '{IBA,ContemporaryClassic}'::text[], 'https://www.thecocktaildb.com/images/media/drink/wmkbfj1606853905.jpg', NULL, 'Build all ingredients in a Collins glass filled with ice. Garnish with lime wedge.', 'Poner todos los ingredientes en un vaso Collins lleno de hielo. Decorar con una rodaja de lima.', '[{"name": "Light rum", "image": "https://www.thecocktaildb.com/images/ingredients/Light%20rum-small.png", "measure": "2 oz"}, {"name": "Lime", "image": "https://www.thecocktaildb.com/images/ingredients/Lime-small.png", "measure": "Juice of 1/2"}, {"name": "Coca-Cola", "image": "https://www.thecocktaildb.com/images/ingredients/Coca-Cola-small.png", "measure": null}]'::jsonb),
  ('11320', 'Dragonfly', 'Ordinary Drink', true, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/uc63bh1582483589.jpg', NULL, 'In a highball glass almost filled with ice cubes, combine the gin and ginger ale. Stir well. Garnish with the lime wedge.', 'En un vaso highball casi lleno de cubitos de hielo, mezcle la ginebra y el ginger ale. Remover bien. Decorar con la rodaja de lima.', '[{"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "1 1/2 oz"}, {"name": "Ginger ale", "image": "https://www.thecocktaildb.com/images/ingredients/Ginger%20ale-small.png", "measure": "4 oz"}, {"name": "Lime", "image": "https://www.thecocktaildb.com/images/ingredients/Lime-small.png", "measure": "1"}]'::jsonb),
  ('11324', 'Dry Rob Roy', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/typuyq1439456976.jpg', NULL, 'In a mixing glass half-filled with ice cubes, combine the Scotch and vermouth. Stir well. Strain into a cocktail glass. Garnish with the lemon twist.', 'En un vaso mezclador lleno hasta la mitad con cubitos de hielo, mezcle el whisky y el vermut. Remover bien. Colar en una copa de cóctel. Decorar con el twist de limón.', '[{"name": "Scotch", "image": "https://www.thecocktaildb.com/images/ingredients/Scotch-small.png", "measure": "2 1/2 oz"}, {"name": "Dry Vermouth", "image": "https://www.thecocktaildb.com/images/ingredients/Dry%20Vermouth-small.png", "measure": "1 1/2 tsp"}, {"name": "Lemon peel", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20peel-small.png", "measure": "1 twist of"}]'::jsonb),
  ('11326', 'Dubonnet Cocktail', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/pfz3hz1582483111.jpg', NULL, 'Stir all ingredients (except lemon peel) with ice and strain into a cocktail glass. Add the twist of lemon peel and serve.', 'Remover todos los ingredientes (excepto la piel de limón) con hielo y colar en una copa de cóctel. Añadir el twist de piel de limón y servir.', '[{"name": "Dubonnet Rouge", "image": "https://www.thecocktaildb.com/images/ingredients/Dubonnet%20Rouge-small.png", "measure": "1 1/2 oz"}, {"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "3/4 oz"}, {"name": "Bitters", "image": "https://www.thecocktaildb.com/images/ingredients/Bitters-small.png", "measure": "1 dash"}, {"name": "Lemon peel", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20peel-small.png", "measure": "1 twist of"}]'::jsonb),
  ('11338', 'English Highball', 'Ordinary Drink', true, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/dhvr7d1504519752.jpg', NULL, 'Pour brandy, gin, and sweet vermouth into a highball glass over ice cubes. Fill with carbonated water. Add the twist of lemon peel, stir, and serve. (Ginger ale may be substituted for carbonated water, if preferred.)', 'Vierta el brandy, la ginebra y el vermut dulce en un vaso highball sobre cubitos de hielo. Rellenar con agua carbonatada. Añadir el twist de piel de limón, remover y servir. (Si se prefiere, se puede sustituir el agua con gas por ginger ale).', '[{"name": "Brandy", "image": "https://www.thecocktaildb.com/images/ingredients/Brandy-small.png", "measure": "3/4 oz"}, {"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "3/4 oz"}, {"name": "Sweet Vermouth", "image": "https://www.thecocktaildb.com/images/ingredients/Sweet%20Vermouth-small.png", "measure": "3/4 oz"}, {"name": "Carbonated water", "image": "https://www.thecocktaildb.com/images/ingredients/Carbonated%20water-small.png", "measure": null}, {"name": "Lemon peel", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20peel-small.png", "measure": null}]'::jsonb),
  ('11339', 'English Rose Cocktail', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/yxwrpp1441208697.jpg', NULL, 'Rub rim of cocktail glass with lemon juice and dip rim of glass in powdered sugar. Shake all ingredients (except cherry) with ice and strain into sugar-rimmed glass. Top with the cherry and serve.', 'Frotar el borde de la copa de cóctel con zumo de limón y mojar el borde de la copa en azúcar en polvo. Agitar todos los ingredientes (excepto la cereza) con hielo y colar en un vaso con borde de azúcar. Cubrir con la cereza y servir.', '[{"name": "Apricot brandy", "image": "https://www.thecocktaildb.com/images/ingredients/Apricot%20brandy-small.png", "measure": "3/4 oz"}, {"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "1 1/2 oz"}, {"name": "Dry Vermouth", "image": "https://www.thecocktaildb.com/images/ingredients/Dry%20Vermouth-small.png", "measure": "3/4 oz"}, {"name": "Grenadine", "image": "https://www.thecocktaildb.com/images/ingredients/Grenadine-small.png", "measure": "1 tsp"}, {"name": "Lemon juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20juice-small.png", "measure": "1/4 tsp"}, {"name": "Cherry", "image": "https://www.thecocktaildb.com/images/ingredients/Cherry-small.png", "measure": "1"}]'::jsonb),
  ('11368', 'Flying Dutchman', 'Ordinary Drink', true, 'Old-fashioned glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/mwko4q1582482903.jpg', NULL, 'In an old-fashioned glass almost filled with ice cubes, combine the gin and triple sec. Stir well.', 'En un vaso old-fashioned casi lleno de cubitos de hielo, mezcle la ginebra y el triple sec. Remuévalo bien.', '[{"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "2 oz"}, {"name": "Triple sec", "image": "https://www.thecocktaildb.com/images/ingredients/Triple%20sec-small.png", "measure": "1/2 oz"}]'::jsonb),
  ('11369', 'Flying Scotchman', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/q53l911582482518.jpg', NULL, 'Shake all ingredients with ice, strain into a cocktail glass, and serve.', 'Agitar todos los ingredientes con hielo, colar en una copa de cóctel y servir.', '[{"name": "Scotch", "image": "https://www.thecocktaildb.com/images/ingredients/Scotch-small.png", "measure": "1 oz"}, {"name": "Sweet Vermouth", "image": "https://www.thecocktaildb.com/images/ingredients/Sweet%20Vermouth-small.png", "measure": "1 oz"}, {"name": "Bitters", "image": "https://www.thecocktaildb.com/images/ingredients/Bitters-small.png", "measure": "1 dash"}, {"name": "Sugar syrup", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar%20syrup-small.png", "measure": "1/4 tsp"}]'::jsonb),
  ('11375', 'Foxy Lady', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/r9cz3q1504519844.jpg', NULL, 'Shake all ingredients with ice, strain into a chilled cocktail glass, and serve.', 'Agitar todos los ingredientes con hielo, colar en una copa de cóctel fría y servir.', '[{"name": "Amaretto", "image": "https://www.thecocktaildb.com/images/ingredients/Amaretto-small.png", "measure": "1/2 oz"}, {"name": "Creme de Cacao", "image": "https://www.thecocktaildb.com/images/ingredients/Creme%20de%20Cacao-small.png", "measure": "1/2 oz"}, {"name": "Light cream", "image": "https://www.thecocktaildb.com/images/ingredients/Light%20cream-small.png", "measure": "2 oz"}]'::jsonb),
  ('11382', 'Frisco Sour', 'Ordinary Drink', true, 'Whiskey sour glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/acuvjz1582482022.jpg', NULL, 'Shake all ingredients (except slices of lemon and lime) with ice and strain into a whiskey sour glass. Decorate with the slices of lemon and lime and serve.', 'Agite todos los ingredientes (excepto las rodajas de limón y lima) con hielo y cuele en un vaso de whisky sour. Decora con las rodajas de limón y lima y sirve.', '[{"name": "Blended whiskey", "image": "https://www.thecocktaildb.com/images/ingredients/Blended%20whiskey-small.png", "measure": "2 oz"}, {"name": "Benedictine", "image": "https://www.thecocktaildb.com/images/ingredients/Benedictine-small.png", "measure": "1/2 oz"}, {"name": "Lemon", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon-small.png", "measure": "Juice of 1/4"}, {"name": "Lime", "image": "https://www.thecocktaildb.com/images/ingredients/Lime-small.png", "measure": "Juice of 1/2"}, {"name": "Lemon", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon-small.png", "measure": "1 slice"}, {"name": "Lime", "image": "https://www.thecocktaildb.com/images/ingredients/Lime-small.png", "measure": "1 slice"}]'::jsonb),
  ('11387', 'Frozen Daiquiri', 'Ordinary Drink', true, 'Champagne flute', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/7oyrj91504884412.jpg', NULL, 'Combine all ingredients (except for the cherry) in an electric blender and blend at a low speed for five seconds, then blend at a high speed until firm. Pour contents into a champagne flute, top with the cherry, and serve.', 'Combine todos los ingredientes (excepto la cereza) en una licuadora eléctrica y licue a velocidad baja durante cinco segundos, luego licue a velocidad alta hasta que esté firme. Vierta el contenido en una copa de champán, cubra con la cereza y sirva.', '[{"name": "Light rum", "image": "https://www.thecocktaildb.com/images/ingredients/Light%20rum-small.png", "measure": "1 1/2 oz"}, {"name": "Triple sec", "image": "https://www.thecocktaildb.com/images/ingredients/Triple%20sec-small.png", "measure": "1 tblsp"}, {"name": "Lime juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lime%20juice-small.png", "measure": "1 1/2 oz"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "1 tsp"}, {"name": "Cherry", "image": "https://www.thecocktaildb.com/images/ingredients/Cherry-small.png", "measure": "1"}, {"name": "Ice", "image": "https://www.thecocktaildb.com/images/ingredients/Ice-small.png", "measure": "1 cup crushed"}]'::jsonb),
  ('11390', 'Frozen Mint Daiquiri', 'Ordinary Drink', true, 'Old-fashioned glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/jrhn1q1504884469.jpg', NULL, 'Combine all ingredients with 1 cup of crushed ice in an electric blender. Blend at a low speed for a short length of time. Pour into an old-fashioned glass and serve.', 'Mezcle todos los ingredientes con 1 taza de hielo picado en una batidora eléctrica. Bata a velocidad baja durante poco tiempo. Verter en un vaso old-fashioned y servir.', '[{"name": "Light rum", "image": "https://www.thecocktaildb.com/images/ingredients/Light%20rum-small.png", "measure": "2 oz"}, {"name": "Lime juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lime%20juice-small.png", "measure": "1 tblsp"}, {"name": "Mint", "image": "https://www.thecocktaildb.com/images/ingredients/Mint-small.png", "measure": "6"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "1 tsp"}]'::jsonb),
  ('11391', 'Frozen Pineapple Daiquiri', 'Ordinary Drink', true, 'Cocktail Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/k3aecd1582481679.jpg', NULL, 'Combine all ingredients with 1 cup of crushed ice in an electric blender. Blend at a low speed for a short length of time. Pour into a cocktail glass and serve.', 'Mezcle todos los ingredientes con 1 taza de hielo picado en una batidora eléctrica. Bata a velocidad baja durante un breve espacio de tiempo. Verter en una copa de cóctel y servir.', '[{"name": "Light rum", "image": "https://www.thecocktaildb.com/images/ingredients/Light%20rum-small.png", "measure": "1 1/2 oz"}, {"name": "Pineapple", "image": "https://www.thecocktaildb.com/images/ingredients/Pineapple-small.png", "measure": "4 chunks"}, {"name": "Lime juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lime%20juice-small.png", "measure": "1 tblsp"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "1/2 tsp"}]'::jsonb),
  ('11407', 'Gin Cooler', 'Ordinary Drink', true, 'Collins glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/678xt11582481163.jpg', NULL, 'Stir powdered sugar and 2 oz. carbonated water in a collins glass. Fill glass with ice and add gin. Fill with carbonated water and stir. Add the lemon peel and the orange spiral so that the end of the orange spiral dangles over rim of glass.', 'Mezcle el azúcar en polvo y 2 onzas de agua carbonatada en un vaso Collins. Llene el vaso con hielo y añada la ginebra. Rellene con agua carbonatada y remueva. Añada la piel de limón y la espiral de naranja de modo que el extremo de la espiral de naranja cuelgue sobre el borde del vaso.', '[{"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "2 oz"}, {"name": "Carbonated water", "image": "https://www.thecocktaildb.com/images/ingredients/Carbonated%20water-small.png", "measure": null}, {"name": "Powdered sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Powdered%20sugar-small.png", "measure": null}, {"name": "Orange spiral", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20spiral-small.png", "measure": null}, {"name": "Lemon peel", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20peel-small.png", "measure": null}]'::jsonb),
  ('11408', 'Gin Daisy', 'Ordinary Drink', true, 'Old-fashioned glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/z6e22f1582581155.jpg', NULL, 'In a shaker half-filled with ice cubes, combine the gin, lemon juice, sugar, and grenadine. Shake well. Pour into an old-fashioned glass and garnish with the cherry and the orange slice.', 'En una coctelera llena hasta la mitad con cubitos de hielo, mezcle la ginebra, el zumo de limón, el azúcar y la granadina. Agitar bien. Verter en un vaso old fashioned y decorar con la cereza y la rodaja de naranja.', '[{"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "2 oz"}, {"name": "Lemon juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20juice-small.png", "measure": "1 oz"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "1/2 tsp superfine"}, {"name": "Grenadine", "image": "https://www.thecocktaildb.com/images/ingredients/Grenadine-small.png", "measure": "1/2 tsp"}, {"name": "Maraschino cherry", "image": "https://www.thecocktaildb.com/images/ingredients/Maraschino%20cherry-small.png", "measure": "1"}, {"name": "Orange", "image": "https://www.thecocktaildb.com/images/ingredients/Orange-small.png", "measure": "1"}]'::jsonb),
  ('11410', 'Gin Fizz', 'Ordinary Drink', true, 'Highball glass', 'Unforgettables', '{IBA,Classic}'::text[], 'https://www.thecocktaildb.com/images/media/drink/drtihp1606768397.jpg', 'https://www.youtube.com/watch?v=obGhGNUKx30', 'Shake all ingredients with ice cubes, except soda water. Pour into glass. Top with soda water.', 'Agite todos los ingredientes con cubitos de hielo, excepto el agua de soda. Verter en un vaso. Añadir agua con gas.', '[{"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "2 oz"}, {"name": "Lemon", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon-small.png", "measure": "Juice of 1/2"}, {"name": "Powdered sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Powdered%20sugar-small.png", "measure": "1 tsp"}, {"name": "Carbonated water", "image": "https://www.thecocktaildb.com/images/ingredients/Carbonated%20water-small.png", "measure": null}]'::jsonb),
  ('11415', 'Gin Sling', 'Ordinary Drink', true, 'Old-fashioned glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/8cl9sm1582581761.jpg', NULL, 'Dissolve powdered sugar in mixture of water and juice of lemon. Add gin. Pour into an old-fashioned glass over ice cubes and stir. Add the twist of orange peel and serve.', 'Disolver el azúcar en polvo en la mezcla de agua y zumo de limón. Añadir la ginebra. Verter en un vaso old-fashioned sobre cubitos de hielo y remover. Añadir el twist de piel de naranja y servir.', '[{"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "2 oz"}, {"name": "Lemon", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon-small.png", "measure": "Juice of 1/2"}, {"name": "Powdered sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Powdered%20sugar-small.png", "measure": "1 tsp"}, {"name": "Water", "image": "https://www.thecocktaildb.com/images/ingredients/Water-small.png", "measure": "1 tsp"}, {"name": "Orange peel", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20peel-small.png", "measure": "Twist of"}]'::jsonb),
  ('11416', 'Gin Smash', 'Ordinary Drink', true, 'Old-fashioned glass', NULL, '{Citrus,StrongFlavor}'::text[], 'https://www.thecocktaildb.com/images/media/drink/iprva61606768774.jpg', NULL, 'Muddle sugar with carbonated water and mint sprigs in an old-fashioned glass. Add gin and 1 ice cube. Stir, add the orange slice and the cherry, and serve.', 'Mezcle el azúcar con el agua carbonatada y las ramitas de menta en un vaso old-fashioned. Añada la ginebra y 1 cubito de hielo. Remover, añadir la rodaja de naranja y la cereza, y servir.', '[{"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "2 oz"}, {"name": "Carbonated water", "image": "https://www.thecocktaildb.com/images/ingredients/Carbonated%20water-small.png", "measure": "1 oz"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "1 cube"}, {"name": "Mint", "image": "https://www.thecocktaildb.com/images/ingredients/Mint-small.png", "measure": "4"}, {"name": "Orange", "image": "https://www.thecocktaildb.com/images/ingredients/Orange-small.png", "measure": "1 slice"}, {"name": "Cherry", "image": "https://www.thecocktaildb.com/images/ingredients/Cherry-small.png", "measure": "1"}]'::jsonb),
  ('11417', 'Gin Sour', 'Ordinary Drink', true, 'Whiskey sour glass', NULL, '{Sour}'::text[], 'https://www.thecocktaildb.com/images/media/drink/noxp7e1606769224.jpg', NULL, 'In a shaker half-filled with ice cubes, combine the gin, lemon juice, and sugar. Shake well. Strain into a sour glass and garnish with the orange slice and the cherry.', 'En una coctelera llena hasta la mitad con cubitos de hielo, combine la ginebra, el jugo de limón y el azúcar. Agite bien. Colar en un vaso ácido y decorar con la rodaja de naranja y la cereza.', '[{"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "2 oz"}, {"name": "Lemon juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20juice-small.png", "measure": "1 oz"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "1/2 tsp superfine"}, {"name": "Orange", "image": "https://www.thecocktaildb.com/images/ingredients/Orange-small.png", "measure": "1"}, {"name": "Maraschino cherry", "image": "https://www.thecocktaildb.com/images/ingredients/Maraschino%20cherry-small.png", "measure": "1"}]'::jsonb),
  ('11418', 'Gin Squirt', 'Ordinary Drink', true, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/xrbhz61504883702.jpg', NULL, 'Stir gin, grenadine, and powdered sugar with ice and strain into a highball glass over ice cubes. Fill with carbonated water and stir. Decorate with the pineapple chunks and the strawberries and serve.', 'Remover la ginebra, la granadina y el azúcar glas con hielo y colar en un vaso highball sobre cubitos de hielo. Rellenar con agua carbonatada y remover. Decorar con los trozos de piña y las fresas y servir.', '[{"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "1 1/2 oz"}, {"name": "Grenadine", "image": "https://www.thecocktaildb.com/images/ingredients/Grenadine-small.png", "measure": "1 tsp"}, {"name": "Powdered sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Powdered%20sugar-small.png", "measure": "1 tblsp"}, {"name": "Pineapple", "image": "https://www.thecocktaildb.com/images/ingredients/Pineapple-small.png", "measure": "3 chunks"}, {"name": "Strawberries", "image": "https://www.thecocktaildb.com/images/ingredients/Strawberries-small.png", "measure": "2"}, {"name": "Carbonated water", "image": "https://www.thecocktaildb.com/images/ingredients/Carbonated%20water-small.png", "measure": null}]'::jsonb),
  ('11419', 'Gin Swizzle', 'Ordinary Drink', true, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/sybce31504884026.jpg', NULL, 'In a shaker half-filled with ice cubes, combine the lime juice, sugar, gin, and bitters. Shake well. Almost fill a colling glass with ice cubes. Stir until the glass is frosted. Strain the mixture in the shaker into the glass and add the club soda.', 'En una coctelera llena hasta la mitad con cubitos de hielo, mezcle el zumo de lima, el azúcar, la ginebra y el amargo. Agitar bien. Llene casi por completo un vaso colling con cubitos de hielo. Agitar hasta que el vaso esté escarchado. Cuele la mezcla de la coctelera en el vaso y añada la soda.', '[{"name": "Lime juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lime%20juice-small.png", "measure": "1 1/2 oz"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "1 tsp superfine"}, {"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "2 oz"}, {"name": "Bitters", "image": "https://www.thecocktaildb.com/images/ingredients/Bitters-small.png", "measure": "1 dash"}, {"name": "Club soda", "image": "https://www.thecocktaildb.com/images/ingredients/Club%20soda-small.png", "measure": "3 oz"}]'::jsonb),
  ('11420', 'Gin Toddy', 'Ordinary Drink', true, 'Old-fashioned glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/jxstwf1582582101.jpg', NULL, 'Mix powdered sugar and water in an old-fashioned glass. Add gin and one ice cube. Stir, add the twist of lemon peel, and serve.', 'Mezcle azúcar en polvo y agua en un vaso old-fashioned. Añada la ginebra y un cubito de hielo. Remover, añadir el twist de piel de limón y servir.', '[{"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "2 oz"}, {"name": "Water", "image": "https://www.thecocktaildb.com/images/ingredients/Water-small.png", "measure": "2 tsp"}, {"name": "Powdered sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Powdered%20sugar-small.png", "measure": "1/2 tsp"}, {"name": "Lemon peel", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20peel-small.png", "measure": "1 twist of"}]'::jsonb),
  ('11422', 'Godchild', 'Ordinary Drink', true, 'Champagne flute', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/m5nhtr1504820829.jpg', NULL, 'Shake all ingredients well with cracked ice, strain into a champagne flute, and serve.', 'Agite bien todos los ingredientes con hielo picado, cuele en una copa de champán y sirva.', '[{"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "1 oz"}, {"name": "Amaretto", "image": "https://www.thecocktaildb.com/images/ingredients/Amaretto-small.png", "measure": "1 oz"}, {"name": "Heavy cream", "image": "https://www.thecocktaildb.com/images/ingredients/Heavy%20cream-small.png", "measure": "1 oz"}]'::jsonb),
  ('11423', 'Godfather', 'Ordinary Drink', true, 'Old-fashioned glass', 'Contemporary Classics', '{IBA,ContemporaryClassic}'::text[], 'https://www.thecocktaildb.com/images/media/drink/e5zgao1582582378.jpg', NULL, 'Pour all ingredients directly into old fashioned glass filled with ice cubes. Stir gently.', 'Vierta todos los ingredientes directamente en un vaso old fashioned lleno de cubitos de hielo. Remover suavemente.', '[{"name": "Scotch", "image": "https://www.thecocktaildb.com/images/ingredients/Scotch-small.png", "measure": "1 1/2 oz"}, {"name": "Amaretto", "image": "https://www.thecocktaildb.com/images/ingredients/Amaretto-small.png", "measure": "3/4 oz"}]'::jsonb),
  ('11424', 'Godmother', 'Ordinary Drink', true, 'Old-fashioned glass', NULL, '{IBA,ContemporaryClassic}'::text[], 'https://www.thecocktaildb.com/images/media/drink/quksqg1582582597.jpg', NULL, 'Pour vodka and amaretto into an old-fashioned glass over ice and serve.', 'Vierta el vodka y el amaretto en un vaso old-fashioned con hielo y sírvalo.', '[{"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "1 1/2 oz"}, {"name": "Amaretto", "image": "https://www.thecocktaildb.com/images/ingredients/Amaretto-small.png", "measure": "3/4 oz"}]'::jsonb),
  ('11433', 'Grass Skirt', 'Ordinary Drink', true, 'Old-fashioned glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/qyvprp1473891585.jpg', NULL, 'In a shaker half-filled with ice cubes, combine the gin, triple sec, pineapple juice, and grenadine. Shake well. Pour into an old-fashioned glass and garnish with the pineapple slice.', 'En una coctelera llena hasta la mitad con cubitos de hielo, mezcle la ginebra, el triple sec, el zumo de piña y la granadina. Agitar bien. Verter en un vaso old fashioned y decorar con la rodaja de piña.', '[{"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "1 1/2 oz"}, {"name": "Triple sec", "image": "https://www.thecocktaildb.com/images/ingredients/Triple%20sec-small.png", "measure": "1 oz"}, {"name": "Pineapple juice", "image": "https://www.thecocktaildb.com/images/ingredients/Pineapple%20juice-small.png", "measure": "1 oz"}, {"name": "Grenadine", "image": "https://www.thecocktaildb.com/images/ingredients/Grenadine-small.png", "measure": "1/2 tsp"}, {"name": "Pineapple", "image": "https://www.thecocktaildb.com/images/ingredients/Pineapple-small.png", "measure": "1"}]'::jsonb),
  ('11462', 'Harvey Wallbanger', 'Ordinary Drink', true, 'Collins glass', 'Contemporary Classics', '{IBA,ContemporaryClassic}'::text[], 'https://www.thecocktaildb.com/images/media/drink/7os4gs1606854357.jpg', NULL, 'Stir the vodka and orange juice with ice in the glass, then float the Galliano on top. Garnish and serve.', 'Mezcle el vodka y el zumo de naranja con hielo en el vaso y, a continuación, deje flotar el Galliano por encima. Decorar y servir.', '[{"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "1 oz"}, {"name": "Galliano", "image": "https://www.thecocktaildb.com/images/ingredients/Galliano-small.png", "measure": "1/2 oz"}, {"name": "Orange juice", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20juice-small.png", "measure": "4 oz"}]'::jsonb),
  ('11470', 'Havana Cocktail', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/59splc1504882899.jpg', NULL, 'In a shaker half-filled with ice cubes, combine all of the ingredients. Shake well. Strain into a cocktail glass.', 'En una coctelera llena hasta la mitad con cubitos de hielo, mezcle todos los ingredientes. Agitar bien. Colar en una copa de cóctel.', '[{"name": "Light rum", "image": "https://www.thecocktaildb.com/images/ingredients/Light%20rum-small.png", "measure": "1 oz"}, {"name": "Pineapple juice", "image": "https://www.thecocktaildb.com/images/ingredients/Pineapple%20juice-small.png", "measure": "1 oz"}, {"name": "Lemon juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20juice-small.png", "measure": "1 tsp"}]'::jsonb),
  ('11472', 'Hawaiian Cocktail', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/ujoh9x1504882987.jpg', NULL, 'Shake all ingredients with ice, strain into a cocktail glass, and serve.', 'Agitar todos los ingredientes con hielo, colar en una copa de cóctel y servir.', '[{"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "2 oz"}, {"name": "Triple sec", "image": "https://www.thecocktaildb.com/images/ingredients/Triple%20sec-small.png", "measure": "1/2 oz"}, {"name": "Pineapple juice", "image": "https://www.thecocktaildb.com/images/ingredients/Pineapple%20juice-small.png", "measure": "1 tblsp"}]'::jsonb),
  ('11476', 'Highland Fling Cocktail', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/0bkwca1492975553.jpg', NULL, 'Stir all ingredients (except olive) with ice and strain into a cocktail glass. Add the olive and serve.', 'Remover todos los ingredientes (excepto la aceituna) con hielo y colar en una copa de cóctel. Añada la aceituna y sirva.', '[{"name": "Scotch", "image": "https://www.thecocktaildb.com/images/ingredients/Scotch-small.png", "measure": "1 1/2 oz"}, {"name": "Sweet Vermouth", "image": "https://www.thecocktaildb.com/images/ingredients/Sweet%20Vermouth-small.png", "measure": "3/4 oz"}, {"name": "Orange bitters", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20bitters-small.png", "measure": "2 dashes"}, {"name": "Olive", "image": "https://www.thecocktaildb.com/images/ingredients/Olive-small.png", "measure": "1"}]'::jsonb),
  ('11524', 'Imperial Fizz', 'Ordinary Drink', true, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/zj1usl1504884548.jpg', NULL, 'Shake all ingredients (except carbonated water) with ice and strain into a highball glass over two ice cubes. Fill with carbonated water, stir, and serve.', 'Agitar todos los ingredientes (excepto el agua carbonatada) con hielo y colar en un vaso highball sobre dos cubitos de hielo. Rellenar con agua carbonatada, remover y servir.', '[{"name": "Light rum", "image": "https://www.thecocktaildb.com/images/ingredients/Light%20rum-small.png", "measure": "1/2 oz"}, {"name": "Blended whiskey", "image": "https://www.thecocktaildb.com/images/ingredients/Blended%20whiskey-small.png", "measure": "1 1/2 oz"}, {"name": "Lemon", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon-small.png", "measure": "Juice of 1/2"}, {"name": "Powdered sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Powdered%20sugar-small.png", "measure": "1 tsp"}, {"name": "Carbonated water", "image": "https://www.thecocktaildb.com/images/ingredients/Carbonated%20water-small.png", "measure": null}]'::jsonb),
  ('11528', 'Irish Spring', 'Ordinary Drink', true, 'Collins glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/sot8v41504884783.jpg', NULL, 'Pour all ingredients (except orange slice and cherry) into a collins glass over ice cubes. Garnish with the slice of orange, add the cherry on top, and serve.', 'Verter todos los ingredientes (excepto la rodaja de naranja y la cereza) en un vaso collins sobre cubitos de hielo. Decorar con la rodaja de naranja, añadir la cereza por encima y servir.', '[{"name": "Irish whiskey", "image": "https://www.thecocktaildb.com/images/ingredients/Irish%20whiskey-small.png", "measure": "1 oz"}, {"name": "Peach brandy", "image": "https://www.thecocktaildb.com/images/ingredients/Peach%20brandy-small.png", "measure": "1/2 oz"}, {"name": "Orange juice", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20juice-small.png", "measure": "1 oz"}, {"name": "Sweet and sour", "image": "https://www.thecocktaildb.com/images/ingredients/Sweet%20and%20sour-small.png", "measure": "1 oz"}, {"name": "Orange", "image": "https://www.thecocktaildb.com/images/ingredients/Orange-small.png", "measure": "1 slice"}, {"name": "Cherry", "image": "https://www.thecocktaildb.com/images/ingredients/Cherry-small.png", "measure": "1"}]'::jsonb),
  ('11542', 'Jack Rose Cocktail', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{Beach}'::text[], 'https://www.thecocktaildb.com/images/media/drink/uuqqrv1439907068.jpg', NULL, 'Shake all ingredients with ice, strain into a cocktail glass, and serve.', 'Agitar todos los ingredientes con hielo, colar en una copa de cóctel y servir.', '[{"name": "Apple brandy", "image": "https://www.thecocktaildb.com/images/ingredients/Apple%20brandy-small.png", "measure": "1 1/2 oz"}, {"name": "Grenadine", "image": "https://www.thecocktaildb.com/images/ingredients/Grenadine-small.png", "measure": "1 tsp"}, {"name": "Lime", "image": "https://www.thecocktaildb.com/images/ingredients/Lime-small.png", "measure": "Juice of 1/2"}]'::jsonb),
  ('11558', 'Japanese Fizz', 'Ordinary Drink', true, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/37vzv11504884831.jpg', NULL, 'Shake all ingredients (except carbonated water) with ice and strain into a highball glass over two ice cubes. Fill with carbonated water, stir, and serve.', 'Agitar todos los ingredientes (excepto el agua carbonatada) con hielo y colar en un vaso highball sobre dos cubitos de hielo. Rellenar con agua carbonatada, remover y servir.', '[{"name": "Blended whiskey", "image": "https://www.thecocktaildb.com/images/ingredients/Blended%20whiskey-small.png", "measure": "1 1/2 oz"}, {"name": "Lemon", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon-small.png", "measure": "Juice of 1/2"}, {"name": "Powdered sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Powdered%20sugar-small.png", "measure": "1 tsp"}, {"name": "Port", "image": "https://www.thecocktaildb.com/images/ingredients/Port-small.png", "measure": "1 tblsp"}, {"name": "Egg white", "image": "https://www.thecocktaildb.com/images/ingredients/Egg%20white-small.png", "measure": "1"}, {"name": "Carbonated water", "image": "https://www.thecocktaildb.com/images/ingredients/Carbonated%20water-small.png", "measure": null}]'::jsonb),
  ('11566', 'Jewel Of The Nile', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/hx4nrb1504884947.jpg', NULL, 'In a mixing glass half-filled with ice cubes, combine all of the ingredients. Stir well. Strain into a cocktail glass.', 'En un vaso mezclador lleno hasta la mitad con cubitos de hielo, mezcle todos los ingredientes. Remover bien. Colar en una copa de cóctel.', '[{"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "1 1/2 oz"}, {"name": "Green Chartreuse", "image": "https://www.thecocktaildb.com/images/ingredients/Green%20Chartreuse-small.png", "measure": "1/2 oz"}, {"name": "Yellow Chartreuse", "image": "https://www.thecocktaildb.com/images/ingredients/Yellow%20Chartreuse-small.png", "measure": "1/2 oz"}]'::jsonb),
  ('11580', 'John Collins', 'Ordinary Drink', true, 'Collins glass', NULL, '{IBA}'::text[], 'https://www.thecocktaildb.com/images/media/drink/0t4bv71606854479.jpg', NULL, 'Pour all ingredients directly into highball glass filled with ice. Stir gently. Garnish. Add a dash of Angostura bitters.', 'Vierta todos los ingredientes directamente en un vaso highball lleno de hielo. Remover suavemente. Decorar. Añada un chorrito de amargo de Angostura.', '[{"name": "Bourbon", "image": "https://www.thecocktaildb.com/images/ingredients/Bourbon-small.png", "measure": "2 oz"}, {"name": "Lemon juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20juice-small.png", "measure": "1 oz"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "1 tsp superfine"}, {"name": "Club soda", "image": "https://www.thecocktaildb.com/images/ingredients/Club%20soda-small.png", "measure": "3 oz"}, {"name": "Maraschino cherry", "image": "https://www.thecocktaildb.com/images/ingredients/Maraschino%20cherry-small.png", "measure": "1"}, {"name": "Orange", "image": "https://www.thecocktaildb.com/images/ingredients/Orange-small.png", "measure": "1"}]'::jsonb),
  ('11600', 'Kamikaze', 'Ordinary Drink', true, 'Cocktail glass', 'New Era Drinks', '{IBA,NewEra}'::text[], 'https://www.thecocktaildb.com/images/media/drink/d7ff7u1606855412.jpg', NULL, 'Shake all ingredients together with ice. Strain into glass, garnish and serve.', 'Agitar todos los ingredientes con hielo. Cuele en un vaso, decore y sirva.', '[{"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "1 oz"}, {"name": "Triple sec", "image": "https://www.thecocktaildb.com/images/ingredients/Triple%20sec-small.png", "measure": "1 oz"}, {"name": "Lime juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lime%20juice-small.png", "measure": "1 oz"}]'::jsonb),
  ('11602', 'Kentucky B And B', 'Ordinary Drink', true, 'Brandy snifter', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/sqxsxp1478820236.jpg', NULL, 'Pour the bourbon and Benedictine into a brandy snifter.', 'Vierta el bourbon y el benedictino en una copa de brandy.', '[{"name": "Bourbon", "image": "https://www.thecocktaildb.com/images/ingredients/Bourbon-small.png", "measure": "2 oz"}, {"name": "Benedictine", "image": "https://www.thecocktaildb.com/images/ingredients/Benedictine-small.png", "measure": "1/2 oz"}]'::jsonb),
  ('11604', 'Kentucky Colonel', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/utqwpu1478820348.jpg', NULL, 'In a shaker half-filled with ice cubes combine the courbon and Benedictine. Shake and strain into a cocktail glass. Garnish with the lemon twist.', 'En una coctelera llena hasta la mitad con cubitos de hielo, combinar el courbon y el Benedictine. Agitar y colar en una copa de cóctel. Decorar con el twist de limón.', '[{"name": "Bourbon", "image": "https://www.thecocktaildb.com/images/ingredients/Bourbon-small.png", "measure": "3 oz"}, {"name": "Benedictine", "image": "https://www.thecocktaildb.com/images/ingredients/Benedictine-small.png", "measure": "1/2 oz"}, {"name": "Lemon peel", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20peel-small.png", "measure": "1 twist of"}]'::jsonb),
  ('11634', 'Lady Love Fizz', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/20d63k1504885263.jpg', NULL, 'Shake all ingredients (except carbonated water) with ice and strain into a cocktail glass over two ice cubes. Fill with carbonated water, stir, and serve.', 'Agitar todos los ingredientes (excepto el agua carbonatada) con hielo y colar en una copa de cóctel sobre dos cubitos de hielo. Rellenar con agua carbonatada, remover y servir.', '[{"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "2 oz"}, {"name": "Light cream", "image": "https://www.thecocktaildb.com/images/ingredients/Light%20cream-small.png", "measure": "2 tsp"}, {"name": "Powdered sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Powdered%20sugar-small.png", "measure": "1 tsp"}, {"name": "Lemon", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon-small.png", "measure": "Juice of 1/2"}, {"name": "Egg white", "image": "https://www.thecocktaildb.com/images/ingredients/Egg%20white-small.png", "measure": "1"}, {"name": "Carbonated water", "image": "https://www.thecocktaildb.com/images/ingredients/Carbonated%20water-small.png", "measure": null}]'::jsonb),
  ('11658', 'Loch Lomond', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/rpvtpr1468923881.jpg', NULL, 'In a mixing glass half-filled with ice cubes, combine the Scotch, Drambuie, and vermouth. Stir well. Strain into a cocktail glass. Garnish with the lemon twist.', 'En un vaso mezclador lleno hasta la mitad con cubitos de hielo, mezcle el whisky, el Drambuie y el vermut. Remover bien. Colar en una copa de cóctel. Decorar con el twist de limón.', '[{"name": "Scotch", "image": "https://www.thecocktaildb.com/images/ingredients/Scotch-small.png", "measure": "2 oz"}, {"name": "Drambuie", "image": "https://www.thecocktaildb.com/images/ingredients/Drambuie-small.png", "measure": "1/2 oz"}, {"name": "Dry Vermouth", "image": "https://www.thecocktaildb.com/images/ingredients/Dry%20Vermouth-small.png", "measure": "1/2 oz"}, {"name": "Lemon peel", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20peel-small.png", "measure": "1 twist of"}]'::jsonb),
  ('11662', 'London Town', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/rpsrqv1468923507.jpg', NULL, 'In a mixing glass half-filled with ice cubes, combine all of the ingredients. Stir well. Strain into a cocktail glass.', 'En un vaso mezclador lleno hasta la mitad con cubitos de hielo, mezcle todos los ingredientes. Remover bien. Colar en una copa de cóctel.', '[{"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "1 1/2 oz"}, {"name": "Maraschino liqueur", "image": "https://www.thecocktaildb.com/images/ingredients/Maraschino%20liqueur-small.png", "measure": "1/2 oz"}, {"name": "Orange bitters", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20bitters-small.png", "measure": "2 dashes"}]'::jsonb),
  ('11664', 'Lone Tree Cocktail', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/tsxpty1468923417.jpg', NULL, 'Stir ingredients with ice, strain into a cocktail glass, and serve.', 'Remover los ingredientes con hielo, colar en una copa de cóctel y servir.', '[{"name": "Sweet Vermouth", "image": "https://www.thecocktaildb.com/images/ingredients/Sweet%20Vermouth-small.png", "measure": "3/4 oz"}, {"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "1 1/2 oz"}]'::jsonb),
  ('11666', 'Lone Tree Cooler', 'Ordinary Drink', true, 'Collins glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/wsyqry1479298485.jpg', NULL, 'Stir powdered sugar and 2 oz. carbonated water in a collins glass. Fill glass with ice, add gin and vermouth, and stir. Fill with carbonated water and stir again. Add the twist of lemon peel and the orange spiral so that the end dangles over rim of glass.', 'Remover el azúcar en polvo y 2 onzas de agua carbonatada en un vaso collins. Llene el vaso con hielo, añada la ginebra y el vermut y remueva. Rellene con agua carbonatada y vuelva a remover. Añadir el twist de piel de limón y la espiral de naranja de modo que el extremo cuelgue sobre el borde del vaso.', '[{"name": "Carbonated water", "image": "https://www.thecocktaildb.com/images/ingredients/Carbonated%20water-small.png", "measure": null}, {"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": null}, {"name": "Dry Vermouth", "image": "https://www.thecocktaildb.com/images/ingredients/Dry%20Vermouth-small.png", "measure": null}, {"name": "Powdered sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Powdered%20sugar-small.png", "measure": null}, {"name": "Orange spiral", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20spiral-small.png", "measure": null}, {"name": "Lemon peel", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20peel-small.png", "measure": null}]'::jsonb),
  ('11670', 'Lord And Lady', 'Ordinary Drink', true, 'Old-fashioned glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/quwrys1468923219.jpg', NULL, 'Pour the rum and Tia Maria into an old-fashioned glass almost filled with ice cubes. Stir well.', 'Vierta el ron y la Tía María en un vaso old-fashioned casi lleno de cubitos de hielo. Remuévalo bien.', '[{"name": "Dark rum", "image": "https://www.thecocktaildb.com/images/ingredients/Dark%20rum-small.png", "measure": "1 1/2 oz"}, {"name": "Tia maria", "image": "https://www.thecocktaildb.com/images/ingredients/Tia%20maria-small.png", "measure": "1/2 oz"}]'::jsonb),
  ('11690', 'Mai Tai', 'Ordinary Drink', true, 'Collins glass', 'Contemporary Classics', '{IBA,ContemporaryClassic}'::text[], 'https://www.thecocktaildb.com/images/media/drink/twyrrp1439907470.jpg', NULL, 'Shake all ingredients with ice. Strain into glass. Garnish and serve with straw.', 'Agitar todos los ingredientes con hielo. Colar en un vaso. Decorar y servir con pajita.', '[{"name": "Light rum", "image": "https://www.thecocktaildb.com/images/ingredients/Light%20rum-small.png", "measure": "1 oz"}, {"name": "Orgeat syrup", "image": "https://www.thecocktaildb.com/images/ingredients/Orgeat%20syrup-small.png", "measure": "1/2 oz"}, {"name": "Triple sec", "image": "https://www.thecocktaildb.com/images/ingredients/Triple%20sec-small.png", "measure": "1/2 oz"}, {"name": "Sweet and sour", "image": "https://www.thecocktaildb.com/images/ingredients/Sweet%20and%20sour-small.png", "measure": "1 1/2 oz"}, {"name": "Cherry", "image": "https://www.thecocktaildb.com/images/ingredients/Cherry-small.png", "measure": "1"}]'::jsonb),
  ('11728', 'Martini', 'Cocktail', true, 'Cocktail glass', 'Unforgettables', '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/71t8581504353095.jpg', 'https://www.youtube.com/watch?v=ApMR3IWYZHI', 'Straight: Pour all ingredients into mixing glass with ice cubes. Stir well. Strain in chilled martini cocktail glass. Squeeze oil from lemon peel onto the drink, or garnish with olive.', 'Derecho: Vierta todos los ingredientes en un vaso mezclador con cubitos de hielo. Remover bien. Colar en una copa de martini fría. Exprima el aceite de la cáscara de limón sobre la bebida, o decore con aceitunas.', '[{"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "1 2/3 oz"}, {"name": "Dry Vermouth", "image": "https://www.thecocktaildb.com/images/ingredients/Dry%20Vermouth-small.png", "measure": "1/3 oz"}, {"name": "Olive", "image": "https://www.thecocktaildb.com/images/ingredients/Olive-small.png", "measure": "1"}]'::jsonb),
  ('11798', 'Monkey Wrench', 'Ordinary Drink', true, 'Old-fashioned glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/bw2noj1582473243.jpg', NULL, 'Pour all of the ingredients into an old-fashioned glass almost filled with ice cubes. Stir well.', 'Vierta todos los ingredientes en un vaso old-fashioned casi lleno de cubitos de hielo. Remuévalo bien.', '[{"name": "Light rum", "image": "https://www.thecocktaildb.com/images/ingredients/Light%20rum-small.png", "measure": "1 1/2 oz"}, {"name": "Grapefruit juice", "image": "https://www.thecocktaildb.com/images/ingredients/Grapefruit%20juice-small.png", "measure": "3 oz"}, {"name": "Bitters", "image": "https://www.thecocktaildb.com/images/ingredients/Bitters-small.png", "measure": "1 dash"}]'::jsonb),
  ('11844', 'New York Sour', 'Ordinary Drink', true, 'Whiskey sour glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/61wgch1504882795.jpg', NULL, 'Shake blended whiskey, juice of lemon, and powdered sugar with ice and strain into a whiskey sour glass. Float claret on top. Decorate with the half-slice of lemon and the cherry and serve.', 'Agite el whisky mezclado, el jugo de limón y el azúcar en polvo con hielo y cuele en un vaso de whisky sour. Coloque el clarete encima. Decorar con la media rodaja de limón y la cereza y servir.', '[{"name": "Blended whiskey", "image": "https://www.thecocktaildb.com/images/ingredients/Blended%20whiskey-small.png", "measure": "2 oz"}, {"name": "Lemon", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon-small.png", "measure": "Juice of 1/2"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "1 tsp"}, {"name": "Red wine", "image": "https://www.thecocktaildb.com/images/ingredients/Red%20wine-small.png", "measure": "(Claret)"}, {"name": "Lemon", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon-small.png", "measure": null}, {"name": "Cherry", "image": "https://www.thecocktaildb.com/images/ingredients/Cherry-small.png", "measure": null}]'::jsonb),
  ('11870', 'Orange Oasis', 'Ordinary Drink', true, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/su1olx1582473812.jpg', NULL, 'Shake brandy, gin, and orange juice with ice and strain into a highball glass over ice cubes. Fill with ginger ale, stir, and serve.', 'Agitar el brandy, la ginebra y el zumo de naranja con hielo y colar en un vaso highball sobre cubitos de hielo. Rellenar con ginger ale, remover y servir.', '[{"name": "Cherry brandy", "image": "https://www.thecocktaildb.com/images/ingredients/Cherry%20brandy-small.png", "measure": "1/2 oz"}, {"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "1 1/2 oz"}, {"name": "Orange juice", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20juice-small.png", "measure": "4 oz"}, {"name": "Ginger ale", "image": "https://www.thecocktaildb.com/images/ingredients/Ginger%20ale-small.png", "measure": null}]'::jsonb),
  ('11872', 'Orgasm', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/vr6kle1504886114.jpg', NULL, 'Shake all ingredients with ice, strain into a chilled cocktail glass, and serve.', 'Agite todos los ingredientes con hielo, cuele en una copa de cóctel fría y sirva.', '[{"name": "Creme de Cacao", "image": "https://www.thecocktaildb.com/images/ingredients/Creme%20de%20Cacao-small.png", "measure": "1/2 oz white"}, {"name": "Amaretto", "image": "https://www.thecocktaildb.com/images/ingredients/Amaretto-small.png", "measure": "1/2 oz"}, {"name": "Triple sec", "image": "https://www.thecocktaildb.com/images/ingredients/Triple%20sec-small.png", "measure": "1/2 oz"}, {"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "1/2 oz"}, {"name": "Light cream", "image": "https://www.thecocktaildb.com/images/ingredients/Light%20cream-small.png", "measure": "1 oz"}]'::jsonb),
  ('11936', 'Pink Gin', 'Ordinary Drink', true, 'White wine glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/qyr51e1504888618.jpg', NULL, 'Pour the bitters into a wine glass. Swirl the glass to coat the inside with the bitters, shake out the excess. Pour the gin into the glass. Do not add ice.', 'Vierta los amargos en una copa de vino. Agita el vaso para cubrir el interior con el amargo y sacude el exceso. Vierte la ginebra en el vaso. No agregue hielo.', '[{"name": "Bitters", "image": "https://www.thecocktaildb.com/images/ingredients/Bitters-small.png", "measure": "3 dashes"}, {"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "2 oz"}]'::jsonb),
