  ('11959', 'Poppy Cocktail', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/cslw1w1504389915.jpg', NULL, 'Shake ingredients with ice, strain into a cocktail glass, and serve.', 'Agite los ingredientes con hielo, cuele en una copa de cóctel y sirva.', '[{"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "1 1/2 oz"}, {"name": "Creme de Cacao", "image": "https://www.thecocktaildb.com/images/ingredients/Creme%20de%20Cacao-small.png", "measure": "3/4 oz white"}]'::jsonb),
  ('11961', 'Port And Starboard', 'Ordinary Drink', true, 'Pousse cafe glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/wxvupx1441553911.jpg', NULL, 'Pour carefully into a pousse-cafe glass, so that creme de menthe floats on grenadine. Serve without mixing.', 'Vierta con cuidado en un vaso de pousse-café, de modo que la crema de menta flote sobre la granadina. Servir sin mezclar.', '[{"name": "Grenadine", "image": "https://www.thecocktaildb.com/images/ingredients/Grenadine-small.png", "measure": "1 tblsp"}, {"name": "Green Creme de Menthe", "image": "https://www.thecocktaildb.com/images/ingredients/Green%20Creme%20de%20Menthe-small.png", "measure": "1/2 oz"}]'::jsonb),
  ('11963', 'Port Wine Cocktail', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/qruprq1441553976.jpg', NULL, 'Stir ingredients with ice, strain into a cocktail glass, and serve.', 'Revuelva los ingredientes con hielo, cuele en una copa de cóctel y sirva.', '[{"name": "Port", "image": "https://www.thecocktaildb.com/images/ingredients/Port-small.png", "measure": "2 1/2 oz"}, {"name": "Brandy", "image": "https://www.thecocktaildb.com/images/ingredients/Brandy-small.png", "measure": "1/2 tsp"}]'::jsonb),
  ('11965', 'Port Wine Flip', 'Ordinary Drink', true, 'Whiskey sour glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/vrprxu1441553844.jpg', NULL, 'Shake all ingredients (except nutmeg) with ice and strain into a whiskey sour glass. Sprinkle nutmeg on top and serve.', 'Agite todos los ingredientes (excepto la nuez moscada) con hielo y cuele en un vaso de whisky sour. Espolvorea nuez moscada por encima y sirve.', '[{"name": "Port", "image": "https://www.thecocktaildb.com/images/ingredients/Port-small.png", "measure": "1 1/2 oz"}, {"name": "Light cream", "image": "https://www.thecocktaildb.com/images/ingredients/Light%20cream-small.png", "measure": "2 tsp"}, {"name": "Powdered sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Powdered%20sugar-small.png", "measure": "1 tsp"}, {"name": "Egg", "image": "https://www.thecocktaildb.com/images/ingredients/Egg-small.png", "measure": "1 whole"}, {"name": "Nutmeg", "image": "https://www.thecocktaildb.com/images/ingredients/Nutmeg-small.png", "measure": null}]'::jsonb),
  ('11983', 'Quaker''s Cocktail', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/yrqppx1478962314.jpg', NULL, 'Shake all ingredients with ice, strain into a cocktail glass, and serve.', 'Agite todos los ingredientes con hielo, cuele en una copa de cóctel y sirva.', '[{"name": "Light rum", "image": "https://www.thecocktaildb.com/images/ingredients/Light%20rum-small.png", "measure": "3/4 oz"}, {"name": "Brandy", "image": "https://www.thecocktaildb.com/images/ingredients/Brandy-small.png", "measure": "3/4 oz"}, {"name": "Lemon", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon-small.png", "measure": "Juice of 1/4"}, {"name": "Raspberry syrup", "image": "https://www.thecocktaildb.com/images/ingredients/Raspberry%20syrup-small.png", "measure": "2 tsp"}]'::jsonb),
  ('11985', 'Quarter Deck Cocktail', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/qrwvps1478963017.jpg', NULL, 'Stir all ingredients with ice, strain into a cocktail glass, and serve.', 'Revuelve todos los ingredientes con hielo, cuela en una copa de cóctel y sirve.', '[{"name": "Light rum", "image": "https://www.thecocktaildb.com/images/ingredients/Light%20rum-small.png", "measure": "1 1/2"}, {"name": "Sherry", "image": "https://www.thecocktaildb.com/images/ingredients/Sherry-small.png", "measure": "1/3 oz cream"}, {"name": "Lime", "image": "https://www.thecocktaildb.com/images/ingredients/Lime-small.png", "measure": "Juice of 1/2"}]'::jsonb),
  ('11987', 'Queen Bee', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/rvvpxu1478963194.jpg', NULL, 'Shake all ingredients with ice, strain into a cocktail glass, and serve.', 'Agite todos los ingredientes con hielo, cuele en una copa de cóctel y sirva.', '[{"name": "Coffee brandy", "image": "https://www.thecocktaildb.com/images/ingredients/Coffee%20brandy-small.png", "measure": "1 oz"}, {"name": "Lime vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Lime%20vodka-small.png", "measure": "1 1/2 oz"}, {"name": "Sherry", "image": "https://www.thecocktaildb.com/images/ingredients/Sherry-small.png", "measure": "1/2 oz cream"}]'::jsonb),
  ('11989', 'Queen Charlotte', 'Ordinary Drink', true, 'Collins glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/vqruyt1478963249.jpg', NULL, 'Pour red wine and grenadine into a collins glass over ice cubes. Fill with lemon-lime soda, stir, and serve.', 'Verter el vino tinto y la granadina en un vaso collins sobre cubitos de hielo. Rellenar con refresco de lima-limón, remover y servir.', '[{"name": "Red wine", "image": "https://www.thecocktaildb.com/images/ingredients/Red%20wine-small.png", "measure": "2 oz"}, {"name": "Grenadine", "image": "https://www.thecocktaildb.com/images/ingredients/Grenadine-small.png", "measure": "1 oz"}, {"name": "Lemon-lime soda", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon-lime%20soda-small.png", "measure": null}]'::jsonb),
  ('11991', 'Queen Elizabeth', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/vpqspv1478963339.jpg', NULL, 'Stir all ingredients with ice, strain into a cocktail glass, and serve.', 'Revuelve todos los ingredientes con hielo, cuela en una copa de cóctel y sirve.', '[{"name": "Dry Vermouth", "image": "https://www.thecocktaildb.com/images/ingredients/Dry%20Vermouth-small.png", "measure": "1/2 oz"}, {"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "1 1/2 oz"}, {"name": "Benedictine", "image": "https://www.thecocktaildb.com/images/ingredients/Benedictine-small.png", "measure": "1 1/2 tsp"}]'::jsonb),
  ('11993', 'Quentin', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/spxtqp1478963398.jpg', NULL, 'In a shaker half-filled with ice cubes, combine the rum, Kahlua, and cream. Shake well. Strain into a cocktail glass and garnish with the nutmeg.', 'En una coctelera llena hasta la mitad con cubitos de hielo, combine el ron, Kahlua y la crema. Agite bien. Colar en una copa de cóctel y decorar con nuez moscada.', '[{"name": "Dark rum", "image": "https://www.thecocktaildb.com/images/ingredients/Dark%20rum-small.png", "measure": "1 1/2 oz"}, {"name": "Kahlua", "image": "https://www.thecocktaildb.com/images/ingredients/Kahlua-small.png", "measure": "1/2 oz"}, {"name": "Light cream", "image": "https://www.thecocktaildb.com/images/ingredients/Light%20cream-small.png", "measure": "1 oz"}, {"name": "Nutmeg", "image": "https://www.thecocktaildb.com/images/ingredients/Nutmeg-small.png", "measure": "1/8 tsp grated"}]'::jsonb),
  ('12055', 'Royal Fizz', 'Ordinary Drink', true, 'Collins glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/wrh44j1504390609.jpg', NULL, 'Shake all ingredients (except cola) with ice and strain into a chilled collins glass. Fill with cola and serve.', 'Agitar todos los ingredientes (excepto la cola) con hielo y colar en un vaso Collins frío. Rellenar con cola y servir.', '[{"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "1 oz"}, {"name": "Sweet and sour", "image": "https://www.thecocktaildb.com/images/ingredients/Sweet%20and%20sour-small.png", "measure": "2 oz"}, {"name": "Egg", "image": "https://www.thecocktaildb.com/images/ingredients/Egg-small.png", "measure": "1 whole"}, {"name": "Coca-Cola", "image": "https://www.thecocktaildb.com/images/ingredients/Coca-Cola-small.png", "measure": null}]'::jsonb),
  ('12057', 'Royal Gin Fizz', 'Ordinary Drink', true, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/pe1x1c1504735672.jpg', NULL, 'Shake all ingredients (except carbonated water) with ice and strain into a highball glass over two ice cubes. Fill with carbonated water, stir, and serve.', 'Agite todos los ingredientes (excepto el agua carbonatada) con hielo y cuele en un vaso alto sobre dos cubitos de hielo. Llene con agua carbonatada, revuelva y sirva.', '[{"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "2 oz"}, {"name": "Lemon", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon-small.png", "measure": "Juice of 1/2"}, {"name": "Powdered sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Powdered%20sugar-small.png", "measure": "1 tsp"}, {"name": "Egg", "image": "https://www.thecocktaildb.com/images/ingredients/Egg-small.png", "measure": "1 whole"}, {"name": "Carbonated water", "image": "https://www.thecocktaildb.com/images/ingredients/Carbonated%20water-small.png", "measure": null}]'::jsonb),
  ('12067', 'Rum Cobbler', 'Ordinary Drink', true, 'Old-fashioned glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/5vh9ld1504390683.jpg', NULL, 'In an old-fashioned glass, dissolve the sugar in the club soda. Add crushed ice until the glass is almost full. Add the rum. Stir well. Garnish with the cherry and the orange and lemon slices.', 'En un vaso old-fashioned, disuelva el azúcar en la soda. Añada hielo picado hasta que el vaso esté casi lleno. Añada el ron. Remover bien. Decorar con la cereza y las rodajas de naranja y limón.', '[{"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "1 tsp superfine"}, {"name": "Club soda", "image": "https://www.thecocktaildb.com/images/ingredients/Club%20soda-small.png", "measure": "3 oz"}, {"name": "Lemon", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon-small.png", "measure": "1"}, {"name": "Dark rum", "image": "https://www.thecocktaildb.com/images/ingredients/Dark%20rum-small.png", "measure": "2 oz"}, {"name": "Maraschino cherry", "image": "https://www.thecocktaildb.com/images/ingredients/Maraschino%20cherry-small.png", "measure": "1"}, {"name": "Orange", "image": "https://www.thecocktaildb.com/images/ingredients/Orange-small.png", "measure": "1"}]'::jsonb),
  ('12071', 'Rum Cooler', 'Ordinary Drink', true, 'Collins glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/2hgwsb1504888674.jpg', NULL, 'Pour the rum and soda into a collins glass almost filled with ice cubes. Stir well and garnish with the lemon wedge.', 'Vierta el ron y la soda en un vaso collins casi lleno de cubitos de hielo. Remover bien y decorar con la rodaja de limón.', '[{"name": "Rum", "image": "https://www.thecocktaildb.com/images/ingredients/Rum-small.png", "measure": "2 oz light or dark"}, {"name": "Lemon-lime soda", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon-lime%20soda-small.png", "measure": "4 oz"}, {"name": "Lemon", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon-small.png", "measure": "1"}]'::jsonb),
  ('12087', 'Rum Milk Punch', 'Ordinary Drink', true, 'Collins glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/w64lqm1504888810.jpg', NULL, 'Shake all ingredients (except nutmeg) with ice and strain into a collins glass. Sprinkle nutmeg on top and serve.', 'Agitar todos los ingredientes (excepto la nuez moscada) con hielo y colar en un vaso Collins. Espolvorear nuez moscada por encima y servir.', '[{"name": "Light rum", "image": "https://www.thecocktaildb.com/images/ingredients/Light%20rum-small.png", "measure": "2 oz"}, {"name": "Milk", "image": "https://www.thecocktaildb.com/images/ingredients/Milk-small.png", "measure": "1 cup"}, {"name": "Powdered sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Powdered%20sugar-small.png", "measure": "1 tsp"}, {"name": "Nutmeg", "image": "https://www.thecocktaildb.com/images/ingredients/Nutmeg-small.png", "measure": null}]'::jsonb),
  ('12089', 'Rum Old-fashioned', 'Ordinary Drink', true, 'Old-fashioned glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/otn2011504820649.jpg', NULL, 'Stir powdered sugar, water, and bitters in an old-fashioned glass. When sugar has dissolved add ice cubes and light rum. Add the twist of lime peel, float 151 proof rum on top, and serve.', 'Mezcle el azúcar en polvo, el agua y el amargo en un vaso old-fashioned. Cuando el azúcar se haya disuelto, añada cubitos de hielo y ron ligero. Añadir el twist de piel de lima, dejar flotar el ron de 151 grados por encima y servir.', '[{"name": "Light rum", "image": "https://www.thecocktaildb.com/images/ingredients/Light%20rum-small.png", "measure": "1 1/2 oz"}, {"name": "151 proof rum", "image": "https://www.thecocktaildb.com/images/ingredients/151%20proof%20rum-small.png", "measure": "1 tsp"}, {"name": "Powdered sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Powdered%20sugar-small.png", "measure": "1/2 tsp"}, {"name": "Bitters", "image": "https://www.thecocktaildb.com/images/ingredients/Bitters-small.png", "measure": "1 dash"}, {"name": "Water", "image": "https://www.thecocktaildb.com/images/ingredients/Water-small.png", "measure": "1 tsp"}, {"name": "Lime peel", "image": "https://www.thecocktaildb.com/images/ingredients/Lime%20peel-small.png", "measure": "Twist of"}]'::jsonb),
  ('12091', 'Rum Screwdriver', 'Ordinary Drink', true, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/4c85zq1511782093.jpg', NULL, 'Pour rum into a highball glass over ice cubes. Add orange juice, stir, and serve.', 'Vierta ron en un vaso alto sobre cubitos de hielo. Agrega el jugo de naranja, revuelve y sirve.', '[{"name": "Light rum", "image": "https://www.thecocktaildb.com/images/ingredients/Light%20rum-small.png", "measure": "1 1/2 oz"}, {"name": "Orange juice", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20juice-small.png", "measure": "5 oz"}]'::jsonb),
  ('12093', 'Rum Sour', 'Ordinary Drink', true, 'Whiskey sour glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/bylfi21504886323.jpg', NULL, 'In a shaker half-filled with ice cubes, combine the rum, lemon juice, and sugar. Shake well. Strain into a sour glass and garnish with the orange slice and the cherry.', 'En una coctelera llena hasta la mitad con cubitos de hielo, combine el ron, el jugo de limón y el azúcar. Agite bien. Colar en un vaso ácido y decorar con la rodaja de naranja y la cereza.', '[{"name": "Light rum", "image": "https://www.thecocktaildb.com/images/ingredients/Light%20rum-small.png", "measure": "2 oz"}, {"name": "Lemon juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20juice-small.png", "measure": "1 oz"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "1/2 tsp superfine"}, {"name": "Orange", "image": "https://www.thecocktaildb.com/images/ingredients/Orange-small.png", "measure": "1"}, {"name": "Maraschino cherry", "image": "https://www.thecocktaildb.com/images/ingredients/Maraschino%20cherry-small.png", "measure": "1"}]'::jsonb),
  ('12097', 'Rum Toddy', 'Ordinary Drink', true, 'Old-fashioned glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/athdk71504886286.jpg', NULL, 'Dissolve powdered sugar in water in an old-fashioned glass. Add rum and one ice cube and stir. Add the twist of lemon peel and serve.', 'Disuelva el azúcar en polvo en agua en un vaso old-fashioned. Añada el ron y un cubito de hielo y remueva. Añada el toque de piel de limón y sirva.', '[{"name": "Rum", "image": "https://www.thecocktaildb.com/images/ingredients/Rum-small.png", "measure": "2 oz light or dark"}, {"name": "Powdered sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Powdered%20sugar-small.png", "measure": "2 tsp"}, {"name": "Lemon peel", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20peel-small.png", "measure": "1 twist of"}, {"name": "Water", "image": "https://www.thecocktaildb.com/images/ingredients/Water-small.png", "measure": "2 tsp"}]'::jsonb),
  ('12101', 'Rusty Nail', 'Ordinary Drink', true, 'Old-fashioned glass', 'Unforgettables', '{IBA,Classic}'::text[], 'https://www.thecocktaildb.com/images/media/drink/yqsvtw1478252982.jpg', 'https://www.youtube.com/watch?v=3po6GT4Te64', 'Pour the Scotch and Drambuie into an old-fashioned glass almost filled with ice cubes. Stir well. Garnish with the lemon twist.', 'Vierta el whisky y el Drambuie en un vaso old-fashioned casi lleno de cubitos de hielo. Remover bien. Decorar con el twist de limón.', '[{"name": "Scotch", "image": "https://www.thecocktaildb.com/images/ingredients/Scotch-small.png", "measure": "1 1/2 oz"}, {"name": "Drambuie", "image": "https://www.thecocktaildb.com/images/ingredients/Drambuie-small.png", "measure": "1/2 oz"}, {"name": "Lemon peel", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20peel-small.png", "measure": "1 twist of"}]'::jsonb),
  ('12107', 'Salty Dog', 'Ordinary Drink', true, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/4vfge01504890216.jpg', NULL, 'Pour all ingredients over ice cubes in a highball glass. Stir well and serve. (Vodka may be substituted for gin, if preferred.)', 'Vierta todos los ingredientes sobre cubitos de hielo en un vaso alto. Revuelva bien y sirva. (Si se prefiere, se puede sustituir el vodka por ginebra).', '[{"name": "Grapefruit juice", "image": "https://www.thecocktaildb.com/images/ingredients/Grapefruit%20juice-small.png", "measure": "5 oz"}, {"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "1 1/2 oz"}, {"name": "Salt", "image": "https://www.thecocktaildb.com/images/ingredients/Salt-small.png", "measure": "1/4 tsp"}]'::jsonb),
  ('12127', 'Sazerac', 'Ordinary Drink', true, 'Old-fashioned glass', 'Unforgettables', '{IBA,Classic}'::text[], 'https://www.thecocktaildb.com/images/media/drink/vvpxwy1439907208.jpg', 'https://www.youtube.com/watch?v=RuZzOcjJUYw', 'Rinse a chilled old-fashioned glass with the absinthe, add crushed ice, and set it aside. Stir the remaining ingredients over ice and set it aside. Discard the ice and any excess absinthe from the prepared glass, and strain the drink into the glass. Add the lemon peel for garnish.', 'Enjuaga un vaso old-fashioned frío con la absenta, añade hielo picado y resérvalo. Remover el resto de ingredientes con hielo y reservar. Deseche el hielo y el exceso de absenta del vaso preparado y cuele la bebida en el vaso. Añada la piel de limón para adornar.', '[{"name": "Ricard", "image": "https://www.thecocktaildb.com/images/ingredients/Ricard-small.png", "measure": "1 tsp"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "1/2 tsp superfine"}, {"name": "Peychaud bitters", "image": "https://www.thecocktaildb.com/images/ingredients/Peychaud%20bitters-small.png", "measure": "2 dashes"}, {"name": "Water", "image": "https://www.thecocktaildb.com/images/ingredients/Water-small.png", "measure": "1 tsp"}, {"name": "Bourbon", "image": "https://www.thecocktaildb.com/images/ingredients/Bourbon-small.png", "measure": "2 oz"}, {"name": "Lemon peel", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20peel-small.png", "measure": "1 twist of"}]'::jsonb),
  ('12130', 'Scooter', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/twuptu1483388307.jpg', NULL, 'Shake all ingredients well with cracked ice, strain into a cocktail glass, and serve.', 'Agitar bien todos los ingredientes con hielo picado, colar en una copa de cóctel y servir.', '[{"name": "Brandy", "image": "https://www.thecocktaildb.com/images/ingredients/Brandy-small.png", "measure": "1 oz"}, {"name": "Amaretto", "image": "https://www.thecocktaildb.com/images/ingredients/Amaretto-small.png", "measure": "1 oz"}, {"name": "Light cream", "image": "https://www.thecocktaildb.com/images/ingredients/Light%20cream-small.png", "measure": "1 oz"}]'::jsonb),
  ('12158', 'Scotch Sour', 'Ordinary Drink', true, 'Whiskey sour glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/0dnb6k1504890436.jpg', NULL, 'Shake scotch, juice of lime, and powdered sugar with ice and strain into a whiskey sour glass. Decorate with 1/2 slice lemon, top with the cherry, and serve.', 'Agite el whisky escocés, el jugo de lima y el azúcar en polvo con hielo y cuele en un vaso de whisky sour. Decora con 1/2 rodaja de limón, cubre con la cereza y sirve.', '[{"name": "Scotch", "image": "https://www.thecocktaildb.com/images/ingredients/Scotch-small.png", "measure": "1 1/2 oz"}, {"name": "Lime", "image": "https://www.thecocktaildb.com/images/ingredients/Lime-small.png", "measure": "Juice of 1/2"}, {"name": "Powdered sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Powdered%20sugar-small.png", "measure": "1/2 tsp"}, {"name": "Lemon", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon-small.png", "measure": "1/2 slice"}, {"name": "Cherry", "image": "https://www.thecocktaildb.com/images/ingredients/Cherry-small.png", "measure": "1"}]'::jsonb),
  ('12162', 'Screwdriver', 'Ordinary Drink', true, 'Highball glass', 'Unforgettables', '{IBA}'::text[], 'https://www.thecocktaildb.com/images/media/drink/8xnyke1504352207.jpg', 'https://www.youtube.com/watch?v=ce_YOgaEo3Q', 'Mix in a highball glass with ice. Garnish and serve.', 'Mezclar en un vaso alto con hielo. Adorne y sirva.', '[{"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "2 oz"}, {"name": "Orange juice", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20juice-small.png", "measure": null}]'::jsonb),
  ('12188', 'Sherry Eggnog', 'Ordinary Drink', true, 'Collins glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/xwrpsv1478820541.jpg', NULL, 'Shake sherry, powdered sugar, and egg with ice and strain into a collins glass. Fill with milk and stir. Sprinkle nutmeg on top and serve.', 'Agitar el jerez, el azúcar glas y el huevo con hielo y colar en un vaso Collins. Rellenar con leche y remover. Espolvorear nuez moscada por encima y servir.', '[{"name": "Sherry", "image": "https://www.thecocktaildb.com/images/ingredients/Sherry-small.png", "measure": "2 oz cream"}, {"name": "Powdered sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Powdered%20sugar-small.png", "measure": "1 tsp"}, {"name": "Egg", "image": "https://www.thecocktaildb.com/images/ingredients/Egg-small.png", "measure": "1 whole"}, {"name": "Milk", "image": "https://www.thecocktaildb.com/images/ingredients/Milk-small.png", "measure": null}, {"name": "Nutmeg", "image": "https://www.thecocktaildb.com/images/ingredients/Nutmeg-small.png", "measure": null}]'::jsonb),
  ('12190', 'Sherry Flip', 'Ordinary Drink', true, 'Nick and Nora Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/qrryvq1478820428.jpg', NULL, 'Shake all ingredients (except nutmeg) with ice and strain into a whiskey sour glass. Sprinkle nutmeg on top and serve.', 'Agite todos los ingredientes (excepto la nuez moscada) con hielo y cuele en un vaso de whisky sour. Espolvorea nuez moscada por encima y sirve.', '[{"name": "Sherry", "image": "https://www.thecocktaildb.com/images/ingredients/Sherry-small.png", "measure": "1 1/2 oz cream"}, {"name": "Light cream", "image": "https://www.thecocktaildb.com/images/ingredients/Light%20cream-small.png", "measure": "2 tsp"}, {"name": "Powdered sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Powdered%20sugar-small.png", "measure": "1 tsp"}, {"name": "Egg", "image": "https://www.thecocktaildb.com/images/ingredients/Egg-small.png", "measure": "1 whole"}, {"name": "Nutmeg", "image": "https://www.thecocktaildb.com/images/ingredients/Nutmeg-small.png", "measure": null}]'::jsonb),
  ('12196', 'Sidecar', 'Ordinary Drink', true, 'Cocktail glass', 'Unforgettables', '{IBA,Classic}'::text[], 'https://www.thecocktaildb.com/images/media/drink/x72sik1606854964.jpg', 'https://www.youtube.com/watch?v=uvKKILoO-Nk', 'Pour all ingredients into cocktail shaker filled with ice. Shake well and strain into cocktail glass.', 'Vierta todos los ingredientes en una coctelera llena de hielo. Agite bien y cuele en una copa de cóctel.', '[{"name": "Cognac", "image": "https://www.thecocktaildb.com/images/ingredients/Cognac-small.png", "measure": "2 oz"}, {"name": "Cointreau", "image": "https://www.thecocktaildb.com/images/ingredients/Cointreau-small.png", "measure": "1/2 oz"}, {"name": "Lemon juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20juice-small.png", "measure": "1 oz"}]'::jsonb),
  ('12256', 'Sol Y Sombra', 'Ordinary Drink', true, 'Brandy snifter', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/3gz2vw1503425983.jpg', NULL, 'Shake ingredients with ice, strain into a brandy snifter, and serve. (The English translation of the name of this drink is "Sun and Shade", and after sampling this drink, you''ll understand why. Thanks, Kirby.)', 'Agite los ingredientes con hielo, cuele en una copa de brandy y sirva. (La traducción al inglés del nombre de esta bebida es "Sun and Shade", y después de probarla, entenderás por qué. Gracias, Kirby).', '[{"name": "Brandy", "image": "https://www.thecocktaildb.com/images/ingredients/Brandy-small.png", "measure": "1 1/2 oz"}, {"name": "Anisette", "image": "https://www.thecocktaildb.com/images/ingredients/Anisette-small.png", "measure": "1 1/2 oz"}]'::jsonb),
  ('12308', 'Stone Sour', 'Ordinary Drink', true, 'Whiskey sour glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/vruvtp1472719895.jpg', NULL, 'Shake all ingredients with ice, strain into a chilled whiskey sour glass, and serve.', 'Vierte la sambuca en un vaso de chupito y luego vierte la crema irlandesa por encima para que los dos líquidos no se mezclen.', '[{"name": "Apricot brandy", "image": "https://www.thecocktaildb.com/images/ingredients/Apricot%20brandy-small.png", "measure": "1 oz"}, {"name": "Orange juice", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20juice-small.png", "measure": "1 oz"}, {"name": "Sweet and sour", "image": "https://www.thecocktaildb.com/images/ingredients/Sweet%20and%20sour-small.png", "measure": "1 oz"}]'::jsonb),
  ('12362', 'Tequila Fizz', 'Ordinary Drink', true, 'Collins glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/2bcase1504889637.jpg', NULL, 'Shake all ingredients (except ginger ale) with ice and strain into a collins glass over ice cubes. Fill with ginger ale, stir, and serve.', 'Agitar todos los ingredientes (excepto el ginger ale) con hielo y colar en un vaso collins sobre cubitos de hielo. Rellenar con ginger ale, remover y servir.', '[{"name": "Tequila", "image": "https://www.thecocktaildb.com/images/ingredients/Tequila-small.png", "measure": "2 oz"}, {"name": "Lemon juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20juice-small.png", "measure": "1 tblsp"}, {"name": "Grenadine", "image": "https://www.thecocktaildb.com/images/ingredients/Grenadine-small.png", "measure": "3/4 oz"}, {"name": "Egg white", "image": "https://www.thecocktaildb.com/images/ingredients/Egg%20white-small.png", "measure": "1"}, {"name": "Ginger ale", "image": "https://www.thecocktaildb.com/images/ingredients/Ginger%20ale-small.png", "measure": null}]'::jsonb),
  ('12370', 'Tequila Sour', 'Ordinary Drink', true, 'Whiskey sour glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/ek0mlq1504820601.jpg', NULL, 'Shake tequila, juice of lemon, and powdered sugar with ice and strain into a whiskey sour glass. Add the half-slice of lemon, top with the cherry, and serve.', 'Agite el tequila, el jugo de limón y el azúcar en polvo con hielo y cuele en un vaso de whisky sour. Agrega la media rodaja de limón, cubre con la cereza y sirve.', '[{"name": "Tequila", "image": "https://www.thecocktaildb.com/images/ingredients/Tequila-small.png", "measure": "2 oz"}, {"name": "Lemon", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon-small.png", "measure": "Juice of 1/2"}, {"name": "Powdered sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Powdered%20sugar-small.png", "measure": "1 tsp"}, {"name": "Lemon", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon-small.png", "measure": "1/2 slice"}, {"name": "Cherry", "image": "https://www.thecocktaildb.com/images/ingredients/Cherry-small.png", "measure": "1"}]'::jsonb),
  ('12388', 'Thriller', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/rvuswq1461867714.jpg', NULL, 'In a shaker half-filled with ice cubes, combine all of the ingredients. Shake well. Strain into a cocktail glass.', 'En una coctelera llena hasta la mitad con cubitos de hielo, combine todos los ingredientes. Agite bien. Colar en una copa de cóctel.', '[{"name": "Scotch", "image": "https://www.thecocktaildb.com/images/ingredients/Scotch-small.png", "measure": "1 1/2 oz"}, {"name": "Wine", "image": "https://www.thecocktaildb.com/images/ingredients/Wine-small.png", "measure": "1 oz Green Ginger"}, {"name": "Orange juice", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20juice-small.png", "measure": "1 oz"}]'::jsonb),
  ('12402', 'Tom Collins', 'Ordinary Drink', true, 'Collins glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/7cll921606854636.jpg', NULL, 'In a shaker half-filled with ice cubes, combine the gin, lemon juice, and sugar. Shake well. Strain into a collins glass alomst filled with ice cubes. Add the club soda. Stir and garnish with the cherry and the orange slice.', 'En una coctelera llena hasta la mitad con cubitos de hielo, mezcle la ginebra, el zumo de limón y el azúcar. Agitar bien. Colar en un vaso collins también lleno de cubitos de hielo. Añadir la soda. Remover y decorar con la cereza y la rodaja de naranja.', '[{"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "2 oz"}, {"name": "Lemon juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20juice-small.png", "measure": "1 oz"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "1 tsp superfine"}, {"name": "Club soda", "image": "https://www.thecocktaildb.com/images/ingredients/Club%20soda-small.png", "measure": "3 oz"}, {"name": "Maraschino cherry", "image": "https://www.thecocktaildb.com/images/ingredients/Maraschino%20cherry-small.png", "measure": "1"}, {"name": "Orange", "image": "https://www.thecocktaildb.com/images/ingredients/Orange-small.png", "measure": "1"}]'::jsonb),
  ('12418', 'Turf Cocktail', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/utypqq1441554367.jpg', NULL, 'Stir all ingredients (except orange peel) with ice and strain into a cocktail glass. Add the twist of orange peel and serve.', 'Revuelva todos los ingredientes (excepto la piel de naranja) con hielo y cuele en una copa de cóctel. Agrega la rodaja de piel de naranja y sirve.', '[{"name": "Dry Vermouth", "image": "https://www.thecocktaildb.com/images/ingredients/Dry%20Vermouth-small.png", "measure": "1 oz"}, {"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "1 oz"}, {"name": "Anis", "image": "https://www.thecocktaildb.com/images/ingredients/Anis-small.png", "measure": "1/4 tsp"}, {"name": "Bitters", "image": "https://www.thecocktaildb.com/images/ingredients/Bitters-small.png", "measure": "2 dashes"}, {"name": "Orange peel", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20peel-small.png", "measure": "Twist of"}]'::jsonb),
  ('12420', 'Tuxedo Cocktail', 'Ordinary Drink', true, 'Cocktail glass', 'Unforgettables', '{IBA,Classic}'::text[], 'https://www.thecocktaildb.com/images/media/drink/4u0nbl1504352551.jpg', 'https://www.youtube.com/watch?v=347ZY5eJFU8', 'Stir all ingredients with ice and strain into a cocktail glass. Garnish with a cherry and a twist of lemon zest.', 'Revuelve todos los ingredientes con hielo y cuela en una copa de cóctel. Adorne con una cereza y una rodaja de ralladura de limón.', '[{"name": "Dry Vermouth", "image": "https://www.thecocktaildb.com/images/ingredients/Dry%20Vermouth-small.png", "measure": "1 1/2 oz"}, {"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "1 1/2 oz"}, {"name": "Maraschino liqueur", "image": "https://www.thecocktaildb.com/images/ingredients/Maraschino%20liqueur-small.png", "measure": "1/4 tsp"}, {"name": "Anis", "image": "https://www.thecocktaildb.com/images/ingredients/Anis-small.png", "measure": "1/4 tsp"}, {"name": "Orange bitters", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20bitters-small.png", "measure": "2 dashes"}, {"name": "Cherry", "image": "https://www.thecocktaildb.com/images/ingredients/Cherry-small.png", "measure": "1"}]'::jsonb),
  ('12434', 'Valencia Cocktail', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/9myuc11492975640.jpg', NULL, 'Shake all ingredients with ice, strain into a cocktail glass, and serve.', 'Agite todos los ingredientes con hielo, cuele en una copa de cóctel y sirva.', '[{"name": "Apricot brandy", "image": "https://www.thecocktaildb.com/images/ingredients/Apricot%20brandy-small.png", "measure": "1 1/2 oz"}, {"name": "Orange juice", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20juice-small.png", "measure": "1 tblsp"}, {"name": "Orange bitters", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20bitters-small.png", "measure": "2 dashes"}]'::jsonb),
  ('12436', 'Van Vleet', 'Ordinary Drink', true, 'Old-fashioned glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/fgq2bl1492975771.jpg', NULL, 'Shake all ingredients with ice, strain into an old-fashioned glass over ice cubes, and serve.', 'Agitar todos los ingredientes con hielo, colar en un vaso old-fashioned sobre cubitos de hielo y servir.', '[{"name": "Light rum", "image": "https://www.thecocktaildb.com/images/ingredients/Light%20rum-small.png", "measure": "3 oz"}, {"name": "Maple syrup", "image": "https://www.thecocktaildb.com/images/ingredients/Maple%20syrup-small.png", "measure": "1 oz"}, {"name": "Lemon juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20juice-small.png", "measure": "1 oz"}]'::jsonb),
