  ('12446', 'Veteran', 'Ordinary Drink', true, 'Old-fashioned glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/iwml9t1492976255.jpg', NULL, 'Pour the rum and cherry brandy into an old-fashioned glass almost filled with ice cubes. Stir well.', 'Vierta el ron y el licor de cereza en un vaso old-fashioned casi lleno de cubitos de hielo. Remuévalo bien.', '[{"name": "Dark rum", "image": "https://www.thecocktaildb.com/images/ingredients/Dark%20rum-small.png", "measure": "2 oz"}, {"name": "Cherry brandy", "image": "https://www.thecocktaildb.com/images/ingredients/Cherry%20brandy-small.png", "measure": "1/2 oz"}]'::jsonb),
