  ('12452', 'Victory Collins', 'Ordinary Drink', true, 'Collins glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/lx0lvs1492976619.jpg', NULL, 'Shake all ingredients (except orange slice) with ice and strain into a collins glass over ice cubes. Add the slice of orange and serve.', 'Agitar todos los ingredientes (excepto la rodaja de naranja) con hielo y colar en un vaso collins sobre cubitos de hielo. Añadir la rodaja de naranja y servir.', '[{"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "1 1/2 oz"}, {"name": "Lemon juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20juice-small.png", "measure": "3 oz"}, {"name": "Grape juice", "image": "https://www.thecocktaildb.com/images/ingredients/Grape%20juice-small.png", "measure": "3 oz unsweetened"}, {"name": "Powdered sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Powdered%20sugar-small.png", "measure": "1 tsp"}, {"name": "Orange", "image": "https://www.thecocktaildb.com/images/ingredients/Orange-small.png", "measure": "1 slice"}]'::jsonb),
