  ('12474', 'Waikiki Beachcomber', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/ysuqus1441208583.jpg', NULL, 'Shake all ingredients with ice, strain into a cocktail glass, and serve.', 'Agite todos los ingredientes con hielo, cuele en una copa de cóctel y sirva.', '[{"name": "Triple sec", "image": "https://www.thecocktaildb.com/images/ingredients/Triple%20sec-small.png", "measure": "3/4 oz"}, {"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "3/4 oz"}, {"name": "Pineapple juice", "image": "https://www.thecocktaildb.com/images/ingredients/Pineapple%20juice-small.png", "measure": "1 tblsp"}]'::jsonb),
  ('12518', 'Whisky Mac', 'Ordinary Drink', true, 'Collins Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/yvvwys1461867858.jpg', NULL, 'Pour both of the ingredients into a wine goblet with no ice.', 'Vierta ambos ingredientes en una copa de vino sin hielo.', '[{"name": "Scotch", "image": "https://www.thecocktaildb.com/images/ingredients/Scotch-small.png", "measure": "1 1/2 oz"}, {"name": "Wine", "image": "https://www.thecocktaildb.com/images/ingredients/Wine-small.png", "measure": "1 oz Green Ginger"}]'::jsonb),
  ('12528', 'White Russian', 'Ordinary Drink', true, 'Old-fashioned glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/vsrupw1472405732.jpg', NULL, 'Pour vodka and coffee liqueur over ice cubes in an old-fashioned glass. Fill with light cream and serve.', 'Vierta el vodka y el licor de café sobre cubitos de hielo en un vaso old-fashioned. Rellenar con nata ligera y servir.', '[{"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "2 oz"}, {"name": "Coffee liqueur", "image": "https://www.thecocktaildb.com/images/ingredients/Coffee%20liqueur-small.png", "measure": "1 oz"}, {"name": "Light cream", "image": "https://www.thecocktaildb.com/images/ingredients/Light%20cream-small.png", "measure": null}]'::jsonb),
  ('12560', 'Afterglow', 'Cocktail', false, 'Highball Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/vuquyv1468876052.jpg', NULL, 'Mix. Serve over ice.', 'Mezclar. Servir con hielo.', '[{"name": "Grenadine", "image": "https://www.thecocktaildb.com/images/ingredients/Grenadine-small.png", "measure": "1 part"}, {"name": "Orange juice", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20juice-small.png", "measure": "4 parts"}, {"name": "Pineapple juice", "image": "https://www.thecocktaildb.com/images/ingredients/Pineapple%20juice-small.png", "measure": "4 parts"}]'::jsonb),
  ('12572', 'Bora Bora', 'Cocktail', false, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/xwuqvw1473201811.jpg', NULL, 'Prepare in a blender or shaker, serve in a highball glass on the rocks. Garnish with 1 slice of pineapple and one cherry.', 'Preparar en una batidora o coctelera, servir en un vaso highball con hielo. Decorar con 1 rodaja de piña y una cereza.', '[{"name": "Pineapple juice", "image": "https://www.thecocktaildb.com/images/ingredients/Pineapple%20juice-small.png", "measure": "10 cl"}, {"name": "Passion fruit juice", "image": "https://www.thecocktaildb.com/images/ingredients/Passion%20fruit%20juice-small.png", "measure": "6 cl"}, {"name": "Lemon juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20juice-small.png", "measure": "1 cl"}, {"name": "Grenadine", "image": "https://www.thecocktaildb.com/images/ingredients/Grenadine-small.png", "measure": "1 cl"}]'::jsonb),
  ('12618', 'Orangeade', 'Cocktail', false, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/ytsxxw1441167732.jpg', NULL, 'Place some ice cubes in a large tumbler or highball glass, add lemon juice, orange juice, sugar syrup, and stir well. Top up with cold soda water, serve with a drinking straw.', 'Ponga unos cubitos de hielo en un vaso grande, añada zumo de limón, zumo de naranja, jarabe de azúcar y remueva bien. Añada agua con gas fría y sírvalo con una pajita.', '[{"name": "Lemon juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20juice-small.png", "measure": "5 cl"}, {"name": "Orange juice", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20juice-small.png", "measure": "15 cl"}, {"name": "Sugar syrup", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar%20syrup-small.png", "measure": "2-3 cl"}, {"name": "Soda water", "image": "https://www.thecocktaildb.com/images/ingredients/Soda%20water-small.png", "measure": null}]'::jsonb),
  ('12630', 'Rail Splitter', 'Cocktail', false, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/stsuqq1441207660.jpg', NULL, 'Mix sugar syrup with lemon juice in a tall glass. Fill up with ginger ale.', 'Mezcle el jarabe de azúcar con el zumo de limón en un vaso alto. Rellenar con ginger ale.', '[{"name": "Sugar syrup", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar%20syrup-small.png", "measure": "2 tsp"}, {"name": "Lemon juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20juice-small.png", "measure": null}, {"name": "Ginger ale", "image": "https://www.thecocktaildb.com/images/ingredients/Ginger%20ale-small.png", "measure": null}]'::jsonb),
  ('12668', 'Egg Cream', 'Other / Unknown', false, 'Coffee mug', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/mvis731484430445.jpg', NULL, 'Mix syrup and milk in a fountain glass. Add soda water, serve with a straw.', 'Mezclar en un vaso fuente el almíbar y la leche. Agregue agua con gas, sirva con una pajita.', '[{"name": "Chocolate syrup", "image": "https://www.thecocktaildb.com/images/ingredients/Chocolate%20syrup-small.png", "measure": "2 tblsp"}, {"name": "Milk", "image": "https://www.thecocktaildb.com/images/ingredients/Milk-small.png", "measure": "6 oz whole"}, {"name": "Soda water", "image": "https://www.thecocktaildb.com/images/ingredients/Soda%20water-small.png", "measure": "6 oz"}]'::jsonb),
  ('12670', 'Fruit Cooler', 'Other / Unknown', false, 'Highball Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/i3tfn31484430499.jpg', NULL, 'Toss strawberries with sugar, and let sit overnight in refrigerator. Cut lemon, reserve two slices. Juice the rest. Mix together the lemon juice, strawberries, apple juice, and soda water. Add slices of lemon (decor, really). In glasses, put ice cubes, and a slice of apple. Pour drink in, and serve.', 'Mezcle las fresas con el azúcar y déjelas reposar toda la noche en el frigorífico. Corte el limón y reserve dos rodajas. Exprima el resto. Mezcle el zumo de limón, las fresas, el zumo de manzana y el agua con gas. Añadir rodajas de limón (decorar, de verdad). En los vasos, poner cubitos de hielo y una rodaja de manzana. Verter la bebida y servir.', '[{"name": "Apple juice", "image": "https://www.thecocktaildb.com/images/ingredients/Apple%20juice-small.png", "measure": "1 can frozen"}, {"name": "Strawberries", "image": "https://www.thecocktaildb.com/images/ingredients/Strawberries-small.png", "measure": "1 cup"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "2 tblsp"}, {"name": "Lemon", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon-small.png", "measure": "1"}, {"name": "Apple", "image": "https://www.thecocktaildb.com/images/ingredients/Apple-small.png", "measure": "1"}, {"name": "Soda water", "image": "https://www.thecocktaildb.com/images/ingredients/Soda%20water-small.png", "measure": "1 L"}, {"name": "Ice", "image": "https://www.thecocktaildb.com/images/ingredients/Ice-small.png", "measure": null}]'::jsonb),
  ('12672', 'Fruit Flip-Flop', 'Other / Unknown', false, 'Highball Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/nfdx6p1484430633.jpg', NULL, 'Place all ingredients in the blender jar - cover and whiz on medium speed until well blended. Pour in one tall, 2 medium or 3 small glasses and drink up.', 'Ponga todos los ingredientes en la jarra de la batidora, tápela y bátala a velocidad media hasta que estén bien mezclados. Verter en un vaso alto, 2 medianos o 3 pequeños y beber.', '[{"name": "Yoghurt", "image": "https://www.thecocktaildb.com/images/ingredients/Yoghurt-small.png", "measure": "1 cup"}, {"name": "Fruit juice", "image": "https://www.thecocktaildb.com/images/ingredients/Fruit%20juice-small.png", "measure": "1 cup"}]'::jsonb),
  ('12674', 'Fruit Shake', 'Other / Unknown', false, 'Highball Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/q0fg2m1484430704.jpg', NULL, 'Blend til smooth.', 'Mezclar hasta que quede suave.', '[{"name": "Yoghurt", "image": "https://www.thecocktaildb.com/images/ingredients/Yoghurt-small.png", "measure": "1 cup fruit"}, {"name": "Banana", "image": "https://www.thecocktaildb.com/images/ingredients/Banana-small.png", "measure": "1"}, {"name": "Orange juice", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20juice-small.png", "measure": "4 oz frozen"}, {"name": "Fruit", "image": "https://www.thecocktaildb.com/images/ingredients/Fruit-small.png", "measure": "1/2 piece textural"}, {"name": "Ice", "image": "https://www.thecocktaildb.com/images/ingredients/Ice-small.png", "measure": "6"}]'::jsonb),
  ('12688', 'Just a Moonmint', 'Shake', false, 'Highball Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/znald61487604035.jpg', NULL, 'Place all ingredients in the blender jar - cover and whiz on medium speed until well blended. Pour in one tall, 2 medium or 3 small glasses and drink up.', 'Ponga todos los ingredientes en la jarra de la batidora, tápela y bátala a velocidad media hasta que estén bien mezclados. Verter en un vaso alto, 2 medianos o 3 pequeños y beber.', '[{"name": "Milk", "image": "https://www.thecocktaildb.com/images/ingredients/Milk-small.png", "measure": "2 cups"}, {"name": "Chocolate syrup", "image": "https://www.thecocktaildb.com/images/ingredients/Chocolate%20syrup-small.png", "measure": null}, {"name": "Mint syrup", "image": "https://www.thecocktaildb.com/images/ingredients/Mint%20syrup-small.png", "measure": null}]'::jsonb),
  ('12690', 'Lassi - A South Indian Drink', 'Other / Unknown', false, 'Highball Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/iq6scx1487603980.jpg', NULL, 'Blend in a blender for 3 seconds. Lassi is one of the easiest things to make, and there are many ways of making it. Basically, it is buttermilk (yoghurt whisked with water), and you can choose almost any consistency that you like, from the thinnest to the thickest. Serve cold.', 'Triturar en la batidora durante 3 segundos. El lassi es una de las cosas más fáciles de hacer, y hay muchas formas de prepararlo. Básicamente, es suero de leche (yogur batido con agua), y puedes elegir casi cualquier consistencia que te guste, desde la más fina a la más espesa. Sírvalo frío.', '[{"name": "Yoghurt", "image": "https://www.thecocktaildb.com/images/ingredients/Yoghurt-small.png", "measure": "1/2 cup plain"}, {"name": "Water", "image": "https://www.thecocktaildb.com/images/ingredients/Water-small.png", "measure": "1 1/4 cup cold"}, {"name": "Cumin seed", "image": "https://www.thecocktaildb.com/images/ingredients/Cumin%20seed-small.png", "measure": "1/2 tsp ground roasted"}, {"name": "Salt", "image": "https://www.thecocktaildb.com/images/ingredients/Salt-small.png", "measure": "1/4 tsp"}, {"name": "Mint", "image": "https://www.thecocktaildb.com/images/ingredients/Mint-small.png", "measure": "1/4 tsp dried"}]'::jsonb),
  ('12692', 'Lassi Khara', 'Other / Unknown', false, 'Highball Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/m1suzm1487603970.jpg', NULL, 'Blend (frappe) in blender until frothy. Add torn curry leaves and serve cold.', 'Mezclar (frappe) en la batidora hasta que esté espumoso. Añada las hojas de curry arrancadas y sírvalo frío.', '[{"name": "Yoghurt", "image": "https://www.thecocktaildb.com/images/ingredients/Yoghurt-small.png", "measure": "1 cup"}, {"name": "Water", "image": "https://www.thecocktaildb.com/images/ingredients/Water-small.png", "measure": "2 cups cold"}, {"name": "Salt", "image": "https://www.thecocktaildb.com/images/ingredients/Salt-small.png", "measure": "1 tsp"}, {"name": "Asafoetida", "image": "https://www.thecocktaildb.com/images/ingredients/Asafoetida-small.png", "measure": "1 pinch"}]'::jsonb),
  ('12694', 'Lassi Raita', 'Other / Unknown', false, 'Highball Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/s4x0qj1487603933.jpg', NULL, 'Blend the yoghurt and ice cubes together, until the yoghurt becomes more liquid. Add sugar to taste. The lemon/lime is optional but it gives it a slightly tart taste. Dash of salt. Raita is also good for the summer. Instead of having a traditional salad you can make raita instead.', 'Mezclar el yogur y los cubitos de hielo, hasta que el yogur se vuelva más líquido. Añadir azúcar al gusto. El limón es opcional, pero le da un sabor ligeramente ácido. Una pizca de sal. La raita también es buena para el verano. En lugar de una ensalada tradicional, se puede preparar raita.', '[{"name": "Yoghurt", "image": "https://www.thecocktaildb.com/images/ingredients/Yoghurt-small.png", "measure": "2 cups"}, {"name": "Ice", "image": "https://www.thecocktaildb.com/images/ingredients/Ice-small.png", "measure": "4-6"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": null}, {"name": "Lime", "image": "https://www.thecocktaildb.com/images/ingredients/Lime-small.png", "measure": null}, {"name": "Salt", "image": "https://www.thecocktaildb.com/images/ingredients/Salt-small.png", "measure": null}]'::jsonb),
  ('12696', 'Lassi - Sweet', 'Other / Unknown', false, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/9jeifz1487603885.jpg', NULL, 'Put all ingredients into a blender and blend until nice and frothy. Serve chilled.', 'Poner todos los ingredientes en una batidora y batir hasta que esté bien espumoso. Sírvalo frío.', '[{"name": "Yoghurt", "image": "https://www.thecocktaildb.com/images/ingredients/Yoghurt-small.png", "measure": "1 cup"}, {"name": "Water", "image": "https://www.thecocktaildb.com/images/ingredients/Water-small.png", "measure": "2 cups cold"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "4 tblsp"}, {"name": "Salt", "image": "https://www.thecocktaildb.com/images/ingredients/Salt-small.png", "measure": "pinch"}, {"name": "Lemon juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20juice-small.png", "measure": "2 tblsp"}]'::jsonb),
  ('12698', 'Lassi - Mango', 'Other / Unknown', false, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/1bw6sd1487603816.jpg', NULL, 'Put it all in a blender and pour over crushed ice. You can also use other fruits like strawberries and bananas.', 'Póngalo todo en una batidora y viértalo sobre hielo picado. También puedes utilizar otras frutas como fresas y plátanos.', '[{"name": "Mango", "image": "https://www.thecocktaildb.com/images/ingredients/Mango-small.png", "measure": "2"}, {"name": "Yoghurt", "image": "https://www.thecocktaildb.com/images/ingredients/Yoghurt-small.png", "measure": "2 cups"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "1/2 cup"}, {"name": "Water", "image": "https://www.thecocktaildb.com/images/ingredients/Water-small.png", "measure": "1 cup iced"}]'::jsonb),
  ('12702', 'Lemouroudji', 'Other / Unknown', false, 'Highball Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/eirmo71487603745.jpg', NULL, 'Juice the lemons. Peel and grate the ginger. Place the grated ginger and a liberal dash of the cayenne pepper into a piece of cheesecloth, and tie it into a knot. Let soak in the water. After 15 minutes or so, add the sugar, and the lemon juice. Chill, and serve.', 'Exprimir los limones. Pelar y rallar el jengibre. Coloca el jengibre rallado y una pizca de pimienta de cayena en un trozo de estopilla y haz un nudo. Déjalo en remojo en el agua. Pasados unos 15 minutos, añada el azúcar y el zumo de limón. Enfríe y sirva.', '[{"name": "Ginger", "image": "https://www.thecocktaildb.com/images/ingredients/Ginger-small.png", "measure": "2 pieces"}, {"name": "Water", "image": "https://www.thecocktaildb.com/images/ingredients/Water-small.png", "measure": "1 gal"}, {"name": "Lemon", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon-small.png", "measure": "1 lb"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "1 cup"}, {"name": "Cayenne pepper", "image": "https://www.thecocktaildb.com/images/ingredients/Cayenne%20pepper-small.png", "measure": "ground"}]'::jsonb),
  ('12704', 'Limeade', 'Other / Unknown', false, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/5jdp5r1487603680.jpg', NULL, 'In a large glass, put the lime juice and sugar, and stir well. Add cold seltzer water to fill. Put the lime peels in the glass. Drink. Repeat until limes or soda run out.', 'En un vaso grande, ponga el zumo de lima y el azúcar, y remueva bien. Añada agua de Seltz fría hasta llenar. Ponga las cáscaras de lima en el vaso. Beber. Repite la operación hasta que se acaben las cáscaras de lima o el agua de seltz.', '[{"name": "Lime", "image": "https://www.thecocktaildb.com/images/ingredients/Lime-small.png", "measure": "Juice of 1"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "1 tblsp"}, {"name": "Soda water", "image": "https://www.thecocktaildb.com/images/ingredients/Soda%20water-small.png", "measure": "(seltzer water)"}, {"name": "Lime peel", "image": "https://www.thecocktaildb.com/images/ingredients/Lime%20peel-small.png", "measure": null}]'::jsonb),
  ('12706', 'Imperial Cocktail', 'Cocktail', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/bcsj2e1487603625.jpg', NULL, 'Shake with ice and strain into cocktail glass.', 'Agitar con hielo y colar en copa de cóctel.', '[{"name": "Lime juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lime%20juice-small.png", "measure": "4 cl"}, {"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "2 cl"}, {"name": "Aperol", "image": "https://www.thecocktaildb.com/images/ingredients/Aperol-small.png", "measure": "4 cl"}]'::jsonb),
  ('12714', 'Kiwi Papaya Smoothie', 'Other / Unknown', false, 'Highball Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/jogv4w1487603571.jpg', NULL, 'Throw everything into a blender and liquify.', 'Echar todo en una batidora y licuar.', '[{"name": "Kiwi", "image": "https://www.thecocktaildb.com/images/ingredients/Kiwi-small.png", "measure": "3"}, {"name": "Papaya", "image": "https://www.thecocktaildb.com/images/ingredients/Papaya-small.png", "measure": "1/2"}]'::jsonb),
  ('12718', 'Pineapple Gingerale Smoothie', 'Other / Unknown', false, 'Highball Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/eg9i1d1487603469.jpg', NULL, 'Throw everything into a blender and liquify.', 'Echar todo en una batidora y licuar.', '[{"name": "Ginger", "image": "https://www.thecocktaildb.com/images/ingredients/Ginger-small.png", "measure": "1/4 inch"}, {"name": "Pineapple", "image": "https://www.thecocktaildb.com/images/ingredients/Pineapple-small.png", "measure": "1/2"}]'::jsonb),
  ('12720', 'Kill the cold Smoothie', 'Other / Unknown', false, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/7j1z2e1487603414.jpg', NULL, 'Juice ginger and lemon and add it to hot water. You may add cardomom.', 'Haz zumo de jengibre y limón y añádelo al agua caliente. Puede añadir cardomomo.', '[{"name": "Ginger", "image": "https://www.thecocktaildb.com/images/ingredients/Ginger-small.png", "measure": "1 inch"}, {"name": "Lemon", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon-small.png", "measure": "1/4"}, {"name": "Water", "image": "https://www.thecocktaildb.com/images/ingredients/Water-small.png", "measure": "1 cup hot"}]'::jsonb),
  ('12724', 'Sweet Bananas', 'Shake', false, 'Highball Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/sxpcj71487603345.jpg', NULL, 'Place all ingredients in the blender jar - cover and whiz on medium speed until well blended. Pour in one tall, 2 medium or 3 small glasses and drink up.', 'Coloque todos los ingredientes en la jarra de la licuadora, cubra y bata a velocidad media hasta que estén bien mezclados. Vierta un vaso alto, 2 medianos o 3 pequeños y bébalo.', '[{"name": "Milk", "image": "https://www.thecocktaildb.com/images/ingredients/Milk-small.png", "measure": "2 cups"}, {"name": "Banana", "image": "https://www.thecocktaildb.com/images/ingredients/Banana-small.png", "measure": "1"}, {"name": "Honey", "image": "https://www.thecocktaildb.com/images/ingredients/Honey-small.png", "measure": "1 tblsp"}]'::jsonb),
  ('12726', 'Tomato Tang', 'Other / Unknown', false, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/869qr81487603278.jpg', NULL, 'Place all ingredients in the blender jar - cover and whiz on medium speed until well blended. Pour in one tall, 2 medium or 3 small glasses and drink up.', 'Coloque todos los ingredientes en la jarra de la licuadora, cubra y bata a velocidad media hasta que estén bien mezclados. Vierta un vaso alto, 2 medianos o 3 pequeños y bébalo.', '[{"name": "Tomato juice", "image": "https://www.thecocktaildb.com/images/ingredients/Tomato%20juice-small.png", "measure": "2 cups"}, {"name": "Lemon juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20juice-small.png", "measure": "1-2 tblsp"}, {"name": "Celery salt", "image": "https://www.thecocktaildb.com/images/ingredients/Celery%20salt-small.png", "measure": "1 dash"}]'::jsonb),
  ('12728', 'Yoghurt Cooler', 'Other / Unknown', false, 'Highball Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/trttrv1441254466.jpg', NULL, 'Place all ingredients in the blender jar - cover and whiz on medium speed until well blended. Pour in one tall, 2 medium or 3 small glasses and drink up. Note: Use lots of ice in this one - great on hot days! To add ice: Remove the center of the cover while the blender is on - drop 3 or 4 ice cubs and blend until they''re completely crushed.', 'Coloque todos los ingredientes en la jarra de la licuadora, cubra y bata a velocidad media hasta que estén bien mezclados. Vierta un vaso alto, 2 medianos o 3 pequeños y bébalo. Nota: Utilice mucho hielo en este caso. ¡Excelente para los días calurosos! Para agregar hielo: Retire el centro de la tapa mientras la licuadora está encendida; deje caer 3 o 4 cubitos de hielo y licue hasta que estén completamente triturados.', '[{"name": "Yoghurt", "image": "https://www.thecocktaildb.com/images/ingredients/Yoghurt-small.png", "measure": "1 cup"}, {"name": "Fruit", "image": "https://www.thecocktaildb.com/images/ingredients/Fruit-small.png", "measure": "1 cup"}, {"name": "Ice", "image": "https://www.thecocktaildb.com/images/ingredients/Ice-small.png", "measure": null}]'::jsonb),
  ('12734', 'Chocolate Drink', 'Cocoa', false, 'Coffee mug', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/q7w4xu1487603180.jpg', NULL, 'Melt the bar in a small amount of boiling water. Add milk. Cook over low heat, whipping gently (with a whisk, i would assume) until heated well. Don''t let it boil! Serve in coffee mug.', 'Derretir la barra en una pequeña cantidad de agua hirviendo. Agrega la leche. Cocine a fuego lento, batiendo suavemente (supongo que con un batidor) hasta que esté bien caliente. ¡No dejes que hierva! Servir en taza de café.', '[{"name": "Chocolate", "image": "https://www.thecocktaildb.com/images/ingredients/Chocolate-small.png", "measure": "125 gr"}, {"name": "Milk", "image": "https://www.thecocktaildb.com/images/ingredients/Milk-small.png", "measure": "3/4 L"}, {"name": "Water", "image": "https://www.thecocktaildb.com/images/ingredients/Water-small.png", "measure": null}]'::jsonb),
  ('12736', 'Drinking Chocolate', 'Cocoa', false, 'Coffee mug', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/u6jrdf1487603173.jpg', NULL, 'Heat the cream and milk with the cinnamon and vanilla bean very slowly for 15-20 minutes. (If you don''t have any beans add 1-2 tsp of vanilla after heating). Remove the bean and cinnamon. Add the chocolate. Mix until fully melted. Serve topped with some very dense fresh whipped cream. Serves 1-2 depending upon how much of a glutton you are. For a richer chocolate, use 4 oz of milk, 4 oz of cream, 4 oz of chocolate. Serve in coffee mug.', 'Calentar la nata y la leche con la canela y la vaina de vainilla muy lentamente durante 15-20 minutos. (Si no tiene frijoles, agregue 1-2 cucharaditas de vainilla después de calentar). Retire el frijol y la canela. Agrega el chocolate. Mezclar hasta que se derrita por completo. Sirva cubierto con un poco de crema batida fresca muy densa. Sirve 1 o 2 porciones dependiendo de qué tan glotón seas. Para un chocolate más rico, use 4 oz de leche, 4 oz de crema, 4 oz de chocolate. Servir en taza de café.', '[{"name": "Heavy cream", "image": "https://www.thecocktaildb.com/images/ingredients/Heavy%20cream-small.png", "measure": "2 oz"}, {"name": "Milk", "image": "https://www.thecocktaildb.com/images/ingredients/Milk-small.png", "measure": "6-8 oz"}, {"name": "Cinnamon", "image": "https://www.thecocktaildb.com/images/ingredients/Cinnamon-small.png", "measure": "1 stick"}, {"name": "Vanilla", "image": "https://www.thecocktaildb.com/images/ingredients/Vanilla-small.png", "measure": "1"}, {"name": "Chocolate", "image": "https://www.thecocktaildb.com/images/ingredients/Chocolate-small.png", "measure": "2 oz finely chopped dark"}, {"name": "Whipped cream", "image": "https://www.thecocktaildb.com/images/ingredients/Whipped%20cream-small.png", "measure": "Fresh"}]'::jsonb),
  ('12738', 'Hot Chocolate to Die for', 'Cocoa', false, 'Coffee mug', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/0lrmjp1487603166.jpg', NULL, 'Melt the chocolate, butter and vanilla in a double boiler. When just smooth stir in the cream.', 'Derretir el chocolate, la mantequilla y la vainilla al baño maría. Cuando todo esté suave, agrega la crema.', '[{"name": "Chocolate", "image": "https://www.thecocktaildb.com/images/ingredients/Chocolate-small.png", "measure": "12 oz fine"}, {"name": "Butter", "image": "https://www.thecocktaildb.com/images/ingredients/Butter-small.png", "measure": "1 tsp"}, {"name": "Vanilla extract", "image": "https://www.thecocktaildb.com/images/ingredients/Vanilla%20extract-small.png", "measure": "1/2 tsp"}, {"name": "Half-and-half", "image": "https://www.thecocktaildb.com/images/ingredients/Half-and-half-small.png", "measure": "1 cup"}, {"name": "Marshmallows", "image": "https://www.thecocktaildb.com/images/ingredients/Marshmallows-small.png", "measure": "mini"}]'::jsonb),
  ('12746', 'Nuked Hot Chocolate', 'Cocoa', false, 'Coffee mug', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/xcu6nb1487603142.jpg', NULL, 'Mix with a bit of milk (1 oz or so) in coffee mug. Nuke mug for about 30-50 seconds. Stir until the heated cocoa dissolves. Fill mug with milk. Nuke for 1-2 minutes, depending on wattage and preferences as to burnt mouth parts.', 'Mezcle con un poco de leche (aproximadamente 1 oz) en una taza de café. Taza nuclear durante unos 30-50 segundos. Revuelve hasta que el cacao calentado se disuelva. Llene la taza con leche. Nuke durante 1-2 minutos, dependiendo de la potencia y las preferencias en cuanto a las piezas bucales quemadas.', '[{"name": "Cocoa powder", "image": "https://www.thecocktaildb.com/images/ingredients/Cocoa%20powder-small.png", "measure": "2 tsp"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "1 tsp"}, {"name": "Vanilla extract", "image": "https://www.thecocktaildb.com/images/ingredients/Vanilla%20extract-small.png", "measure": "1/2 tsp"}, {"name": "Milk", "image": "https://www.thecocktaildb.com/images/ingredients/Milk-small.png", "measure": "12 oz"}]'::jsonb),
  ('12748', 'Orange Scented Hot Chocolate', 'Cocoa', false, 'Coffee mug', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/hdzwrh1487603131.jpg', NULL, 'Combine all ingredients in heavy medium saucepan. Stir over low heat until chocolate melts. Increase heat and bring just to a boil, stirring often. Remove from heat and whisk untily frothy. Return to heat and bring to boil again. Remove from heat, whisk until frothy. Repeat heating and whisking once again. Discard orange peel. (Can be prepared 2 hours ahead. Let stand at room temperature. Before serving, bring just to boil, remove from heat and whisk until frothy.) Pour hot chocolate into coffee mugs. Makes 2 servings.', 'Combine todos los ingredientes en una cacerola mediana y pesada. Revuelve a fuego lento hasta que el chocolate se derrita. Aumente el fuego y deje que hierva, revolviendo con frecuencia. Retirar del fuego y batir hasta que esté espumoso. Regresar al fuego y dejar hervir nuevamente. Retirar del fuego, batir hasta que esté espumoso. Repita calentar y batir una vez más. Deseche la cáscara de naranja. (Se puede preparar con 2 horas de anticipación. Dejar reposar a temperatura ambiente. Antes de servir, dejar hervir, retirar del fuego y batir hasta que esté espumoso). Vierta el chocolate caliente en tazas de café. Rinde 2 porciones.', '[{"name": "Milk", "image": "https://www.thecocktaildb.com/images/ingredients/Milk-small.png", "measure": "2 cups"}, {"name": "Chocolate", "image": "https://www.thecocktaildb.com/images/ingredients/Chocolate-small.png", "measure": "4 oz chopped bittersweet or semi-sweet"}, {"name": "Orange peel", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20peel-small.png", "measure": "3 2-inch strips"}, {"name": "Espresso", "image": "https://www.thecocktaildb.com/images/ingredients/Espresso-small.png", "measure": "1/2 tsp instant"}, {"name": "Nutmeg", "image": "https://www.thecocktaildb.com/images/ingredients/Nutmeg-small.png", "measure": "1/8 tsp ground"}]'::jsonb),
  ('12752', 'Lemon Shot', 'Shot', true, 'Shot glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/mx31hv1487602979.jpg', NULL, 'Mix Galliano and Absolut Citron in a shot glass, lay lemon wedge sprinkled with sugar over glass and pour a rum over wedge and glass. light rum with a lighter and let burn for a second. Do shot quickly and suck on lemon. If it is done correctly, this will taste like a shot of sweet lemonade.', 'Mezcle Galliano y Absolut Citron en un vaso de chupito, coloque una rodaja de limón espolvoreada con azúcar sobre el vaso y vierta ron sobre la rodaja y el vaso. Enciende el ron con un encendedor y deja quemar por un segundo. Dispara rápido y chupa limón. Si se hace correctamente, sabrá a un trago de limonada dulce.', '[{"name": "Galliano", "image": "https://www.thecocktaildb.com/images/ingredients/Galliano-small.png", "measure": "1/2 oz"}, {"name": "Absolut Citron", "image": "https://www.thecocktaildb.com/images/ingredients/Absolut%20Citron-small.png", "measure": "1/2 oz"}, {"name": "Lemon", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon-small.png", "measure": "wedge"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "Bacardi"}, {"name": "151 proof rum", "image": "https://www.thecocktaildb.com/images/ingredients/151%20proof%20rum-small.png", "measure": null}]'::jsonb),
  ('12758', 'Gagliardo', 'Cocktail', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/lyloe91487602877.jpg', NULL, 'Shake well and serve in a cocktail glass. This is a home cocktail of American/Internet Bar del Pozzo, Pavia, Italy.', 'Agitar bien y servir en copa de cóctel. Este es un cóctel casero de American/Internet Bar del Pozzo, Pavia, Italia.', '[{"name": "Peach Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Peach%20Vodka-small.png", "measure": "5 parts"}, {"name": "Lemon juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20juice-small.png", "measure": "3 parts"}, {"name": "Galliano", "image": "https://www.thecocktaildb.com/images/ingredients/Galliano-small.png", "measure": "1 part"}, {"name": "Sirup of roses", "image": "https://www.thecocktaildb.com/images/ingredients/Sirup%20of%20roses-small.png", "measure": "1 part"}]'::jsonb),
  ('12764', 'Karsk', 'Ordinary Drink', true, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/808mxk1487602471.jpg', NULL, 'Put a copper coin in a coffe-cup and fill up with coffee until you no longer see the coin, then add alcohol until you see the coin. Norwegian speciality.', 'Se pone una moneda de cobre en una taza de café y se llena con café hasta que ya no se vea la moneda, después se añade alcohol hasta que se vea la moneda. Especialidad noruega.', '[{"name": "Coffee", "image": "https://www.thecocktaildb.com/images/ingredients/Coffee-small.png", "measure": "1 part"}, {"name": "Grain alcohol", "image": "https://www.thecocktaildb.com/images/ingredients/Grain%20alcohol-small.png", "measure": "2 parts"}]'::jsonb),
  ('12766', 'Happy Skipper', 'Ordinary Drink', true, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/42w2g41487602448.jpg', NULL, 'Pour Captain Morgan''s Spiced Rum over ice, fill glass to top with Ginger Ale. Garnish with lime. Tastes like a cream soda. Named for the Gilligan''s Island reference ("The Captain" *in* "Ginger" is a Happy Skipper!)', 'Vierta el ron Captain Morgan''s Spiced sobre hielo, llene el vaso hasta arriba con Ginger Ale. Adorne con lima. Sabe como un refresco de crema. Llamado así por la referencia a Gilligan''s Island ("The Captain" *in* "Ginger" is a Happy Skipper!)', '[{"name": "Spiced rum", "image": "https://www.thecocktaildb.com/images/ingredients/Spiced%20rum-small.png", "measure": "1 1/2 cl"}, {"name": "Ginger ale", "image": "https://www.thecocktaildb.com/images/ingredients/Ginger%20ale-small.png", "measure": null}, {"name": "Lime", "image": "https://www.thecocktaildb.com/images/ingredients/Lime-small.png", "measure": null}, {"name": "Ice", "image": "https://www.thecocktaildb.com/images/ingredients/Ice-small.png", "measure": null}]'::jsonb),
  ('12768', 'Frappé', 'Coffee / Tea', false, 'Highball Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/vqwryq1441245927.jpg', NULL, 'Mix together. Blend at highest blender speed for about 1 minute. Pour into a glass and drink with a straw. Notes: This works best if everything is cold (if you make fresh coffee, mix it with the milk and let it sit in the fridge for 1/2 hour. If it is not frothy, add more milk, or even just some more milk powder. The froth gradually turns to liquid at the bottom of the glass, so you will find that you can sit and drink this for about 1/2 hour, with more iced coffee continually appearing at the bottom. Very refreshing.', 'Mezclar. Licuar a máxima velocidad durante 1 minuto. Verter en un vaso y beber con pajita. Notas: Esto funciona mejor si todo está frío (si haces café fresco, mézclalo con la leche y déjalo reposar en la nevera durante 1/2 hora. Si no está espumoso, añade más leche, o incluso un poco más de leche en polvo. La espuma se va convirtiendo poco a poco en líquido en el fondo del vaso, por lo que se puede beber durante media hora, sin que deje de aparecer café helado en el fondo. Muy refrescante.', '[{"name": "Coffee", "image": "https://www.thecocktaildb.com/images/ingredients/Coffee-small.png", "measure": "1/2 cup black"}, {"name": "Milk", "image": "https://www.thecocktaildb.com/images/ingredients/Milk-small.png", "measure": "1/2 cup"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "1-2 tsp"}]'::jsonb),
  ('12770', 'Iced Coffee', 'Coffee / Tea', false, 'Coffee mug', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/ytprxy1454513855.jpg', NULL, 'Mix together until coffee and sugar is dissolved. Add milk. Shake well. Using a blender or milk shake maker produces a very foamy drink. Serve in coffee mug.', 'Mezclar hasta que el café y el azúcar se disuelvan. Agrega la leche. Agite bien. Usar una licuadora o una batidora produce una bebida muy espumosa. Servir en taza de café.', '[{"name": "Coffee", "image": "https://www.thecocktaildb.com/images/ingredients/Coffee-small.png", "measure": "1/4 cup instant"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "1/4 cup"}, {"name": "Water", "image": "https://www.thecocktaildb.com/images/ingredients/Water-small.png", "measure": "1/4 cup hot"}, {"name": "Milk", "image": "https://www.thecocktaildb.com/images/ingredients/Milk-small.png", "measure": "4 cups cold"}]'::jsonb),
  ('12772', 'Iced Coffee Fillip', 'Coffee / Tea', true, 'Coffee mug', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/sxtxrp1454514223.jpg', NULL, 'Mix together in a coffee mug and chill before serving.', 'Mezclar en una taza de café y enfriar antes de servir.', '[{"name": "Kahlua", "image": "https://www.thecocktaildb.com/images/ingredients/Kahlua-small.png", "measure": "2 tsp"}, {"name": "Coffee", "image": "https://www.thecocktaildb.com/images/ingredients/Coffee-small.png", "measure": "Strong cold"}]'::jsonb),
  ('12774', 'Masala Chai', 'Coffee / Tea', false, 'Coffee Mug', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/uyrpww1441246384.jpg', NULL, 'Bring 2 cups of water to boil. Add all the ingredients and boil again for about 15 seconds. Let stand for a minute. Warm milk in a pot. Filter tea into cups. Add milk and sugar. That''s IT.', 'Pon a hervir 2 tazas de agua. Agrega todos los ingredientes y vuelve a hervir durante unos 15 segundos. Dejar reposar por un minuto. Calienta la leche en una olla. Filtra el té en tazas. Agrega la leche y el azúcar. Eso es todo.', '[{"name": "Water", "image": "https://www.thecocktaildb.com/images/ingredients/Water-small.png", "measure": "2 cups"}, {"name": "Tea", "image": "https://www.thecocktaildb.com/images/ingredients/Tea-small.png", "measure": "3-4 tsp"}, {"name": "Ginger", "image": "https://www.thecocktaildb.com/images/ingredients/Ginger-small.png", "measure": "1 chunk dried"}, {"name": "Cardamom", "image": "https://www.thecocktaildb.com/images/ingredients/Cardamom-small.png", "measure": "3-4 crushed"}, {"name": "Cloves", "image": "https://www.thecocktaildb.com/images/ingredients/Cloves-small.png", "measure": "3"}, {"name": "Cinnamon", "image": "https://www.thecocktaildb.com/images/ingredients/Cinnamon-small.png", "measure": "1 piece"}, {"name": "Black pepper", "image": "https://www.thecocktaildb.com/images/ingredients/Black%20pepper-small.png", "measure": "1-2 whole"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "to taste"}, {"name": "Milk", "image": "https://www.thecocktaildb.com/images/ingredients/Milk-small.png", "measure": "to taste"}]'::jsonb),
  ('12776', 'Melya', 'Coffee / Tea', false, 'Coffee mug', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/xwtptq1441247579.jpg', NULL, 'Brew espresso. In a coffee mug, place 1 teaspoon of unsweetened powdered cocoa, then cover a teaspoon with honey and drizzle it into the cup. Stir while the coffee brews, this is the fun part. The cocoa seems to coat the honey without mixing, so you get a dusty, sticky mass that looks as though it will never mix. Then all at once, presto! It looks like dark chocolate sauce. Pour hot espresso over the honey, stirring to dissolve. Serve with cream.', 'Prepara café expreso. En una taza de café, coloca 1 cucharadita de cacao en polvo sin azúcar, luego cubre una cucharadita con miel y rocíala en la taza. Revuelve mientras se prepara el café, esta es la parte divertida. El cacao parece cubrir la miel sin mezclarse, por lo que se obtiene una masa polvorienta y pegajosa que parece que nunca se mezclará. Entonces, de repente, ¡listo! Parece salsa de chocolate amargo. Vierta el espresso caliente sobre la miel, revolviendo para que se disuelva. Servir con crema.', '[{"name": "Espresso", "image": "https://www.thecocktaildb.com/images/ingredients/Espresso-small.png", "measure": null}, {"name": "Honey", "image": "https://www.thecocktaildb.com/images/ingredients/Honey-small.png", "measure": "Unsweetened"}, {"name": "Cocoa powder", "image": "https://www.thecocktaildb.com/images/ingredients/Cocoa%20powder-small.png", "measure": null}]'::jsonb),
  ('12782', 'Thai Coffee', 'Coffee / Tea', false, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/wquwxs1441247025.jpg', NULL, 'Place the coffee and spices in the filter cone of your coffee maker. Brew coffee as usual, let it cool. In a tall glass, dissolve 1 or 2 teaspoons of sugar in an ounce of the coffee (it''s easier to dissolve than if you put it right over ice). Add 5-6 ice cubes and pour coffee to within about 1 inch of the top of the glass. Rest a spoon on top of the coffee and slowly pour whipping cream into the spoon. This will make the cream float on top of the coffee rather than dispersing into it right away.', 'Coloca el café y las especias en el cono de filtro de tu cafetera. Prepare el café como de costumbre y déjelo enfriar. En un vaso alto, disuelve 1 o 2 cucharaditas de azúcar en una onza de café (es más fácil de disolver que si lo pones directamente sobre hielo). Agregue 5-6 cubitos de hielo y vierta el café hasta aproximadamente 1 pulgada de la parte superior del vaso. Coloca una cuchara sobre el café y vierte lentamente la crema para batir en la cuchara. Esto hará que la crema flote sobre el café en lugar de dispersarse inmediatamente.', '[{"name": "Coffee", "image": "https://www.thecocktaildb.com/images/ingredients/Coffee-small.png", "measure": "6 tblsp ground"}, {"name": "Coriander", "image": "https://www.thecocktaildb.com/images/ingredients/Coriander-small.png", "measure": "1/4 tsp"}, {"name": "Cardamom", "image": "https://www.thecocktaildb.com/images/ingredients/Cardamom-small.png", "measure": "4-5 whole green"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": null}, {"name": "Whipping cream", "image": "https://www.thecocktaildb.com/images/ingredients/Whipping%20cream-small.png", "measure": null}, {"name": "Ice", "image": "https://www.thecocktaildb.com/images/ingredients/Ice-small.png", "measure": null}]'::jsonb),
  ('12784', 'Thai Iced Coffee', 'Coffee / Tea', false, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/rqpypv1441245650.jpg', NULL, 'Prepare a pot of coffee at a good European strength. In the ground coffee, add 2 or 3 freshly ground cardamom pods. Sweeten while hot, then cool quickly. Serve in highball glass over ice, with cream. To get the layered effect, place a spoon atop the coffee and pour the milk carefully into the spoon so that it floats on the top of the coffee.', 'Prepare una taza de café con una buena concentración europea. En el café molido añadir 2 o 3 vainas de cardamomo recién molidas. Endulce mientras esté caliente y luego enfríe rápidamente. Sirva en un vaso alto con hielo y crema. Para obtener el efecto de capas, coloque una cuchara encima del café y vierta la leche con cuidado en la cuchara para que flote sobre la superficie del café.', '[{"name": "Coffee", "image": "https://www.thecocktaildb.com/images/ingredients/Coffee-small.png", "measure": "black"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": null}, {"name": "Cream", "image": "https://www.thecocktaildb.com/images/ingredients/Cream-small.png", "measure": "pods"}, {"name": "Cardamom", "image": "https://www.thecocktaildb.com/images/ingredients/Cardamom-small.png", "measure": null}]'::jsonb),
  ('12786', 'Thai Iced Tea', 'Coffee / Tea', false, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/trvwpu1441245568.jpg', NULL, 'Combine Thai tea (i.e., the powder), boiling water, and sweetened condensed milk, stir until blended. Pour into 2 tall glasses filled with ice cubes. Garnish with mint leaves. Makes 2 servings.', 'Combine el té tailandés (es decir, el polvo), el agua hirviendo y la leche condensada azucarada, revuelva hasta que se mezclen. Vierta en 2 vasos altos llenos de cubitos de hielo. Adorne con hojas de menta. Rinde 2 porciones.', '[{"name": "Tea", "image": "https://www.thecocktaildb.com/images/ingredients/Tea-small.png", "measure": "1/4 cup Thai"}, {"name": "Water", "image": "https://www.thecocktaildb.com/images/ingredients/Water-small.png", "measure": "1/2 cup boiling"}, {"name": "Condensed milk", "image": "https://www.thecocktaildb.com/images/ingredients/Condensed%20milk-small.png", "measure": "2 tsp sweetened"}, {"name": "Ice", "image": "https://www.thecocktaildb.com/images/ingredients/Ice-small.png", "measure": "cubes"}, {"name": "Mint", "image": "https://www.thecocktaildb.com/images/ingredients/Mint-small.png", "measure": "garnish"}]'::jsonb),
  ('12798', 'Coffee Liqueur', 'Homemade Liqueur', true, 'Collins Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/ryvtsu1441253851.jpg', NULL, 'Combine coffee, sugar and water. Simmer 1 hour and let cool. Add vanilla and vodka. Age in sealed jar 2 to 3 weeks.', 'Mezclar el café, el azúcar y el agua. Cocer a fuego lento durante 1 hora y dejar enfriar. Añadir la vainilla y el vodka. Envejecer en un tarro cerrado de 2 a 3 semanas.', '[{"name": "Coffee", "image": "https://www.thecocktaildb.com/images/ingredients/Coffee-small.png", "measure": "10 tblsp instant"}, {"name": "Vanilla extract", "image": "https://www.thecocktaildb.com/images/ingredients/Vanilla%20extract-small.png", "measure": "4 tblsp"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "2 1/2 cups"}, {"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "1 qt"}, {"name": "Water", "image": "https://www.thecocktaildb.com/images/ingredients/Water-small.png", "measure": "2 1/2 cups"}]'::jsonb),
  ('12800', 'Coffee-Vodka', 'Homemade Liqueur', true, 'Collins Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/qvrrvu1472667494.jpg', NULL, 'Boil water and sugar until dissolved. Turn off heat. Slowly add dry instant coffee and continue stirring. Add a chopped vanilla bean to the vodka, then combine the cooled sugar syrup and coffee solution with the vodka. Cover tightly and shake vigorously each day for 3 weeks. Strain and filter. Its also best to let the sugar mixture cool completely so the vodka won''t evaporate when its added. If you like a smoother feel to the liqueur you can add about 1 teaspoon of glycerine to the finished product.', 'Hervir el agua y el azúcar hasta que se disuelvan. Apague el fuego. Añadir lentamente el café instantáneo seco y seguir removiendo. Añadir una vaina de vainilla picada al vodka y, a continuación, mezclar el jarabe de azúcar enfriado y la solución de café con el vodka. Tapar bien y agitar enérgicamente todos los días durante 3 semanas. Colar y filtrar. También es mejor dejar enfriar completamente la mezcla de azúcar para que el vodka no se evapore al añadirlo. Si desea un licor más suave, puede añadir una cucharadita de glicerina al producto final.', '[{"name": "Water", "image": "https://www.thecocktaildb.com/images/ingredients/Water-small.png", "measure": "2 cups"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "2 cups white"}, {"name": "Coffee", "image": "https://www.thecocktaildb.com/images/ingredients/Coffee-small.png", "measure": "1/2 cup instant"}, {"name": "Vanilla", "image": "https://www.thecocktaildb.com/images/ingredients/Vanilla-small.png", "measure": "1/2"}, {"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "1 1/2 cup"}, {"name": "Caramel coloring", "image": "https://www.thecocktaildb.com/images/ingredients/Caramel%20coloring-small.png", "measure": null}]'::jsonb),
  ('12820', 'Irish Cream', 'Homemade Liqueur', true, 'Irish coffee cup', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/90etyl1504884699.jpg', NULL, 'Mix scotch and milk. Add half-and-half. Add rest.', 'Mezclar whisky y leche. Agrega mitad y mitad. Añade resto.', '[{"name": "Scotch", "image": "https://www.thecocktaildb.com/images/ingredients/Scotch-small.png", "measure": "1 cup"}, {"name": "Half-and-half", "image": "https://www.thecocktaildb.com/images/ingredients/Half-and-half-small.png", "measure": "1 1/4 cup"}, {"name": "Condensed milk", "image": "https://www.thecocktaildb.com/images/ingredients/Condensed%20milk-small.png", "measure": "1 can sweetened"}, {"name": "Coconut syrup", "image": "https://www.thecocktaildb.com/images/ingredients/Coconut%20syrup-small.png", "measure": "3 drops"}, {"name": "Chocolate syrup", "image": "https://www.thecocktaildb.com/images/ingredients/Chocolate%20syrup-small.png", "measure": "1 tblsp"}]'::jsonb),
  ('12856', 'Tia-Maria', 'Homemade Liqueur', true, 'Collins Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/sih81u1504367097.jpg', NULL, 'Boil water, sugar and coffe for 10 mins and let cool. Add rum and vanilla. Put in clean bottle(s) and leave for 1 week before using.', 'Hervir el agua, el azúcar y el café durante 10 minutos y dejar enfriar. Añadir el ron y la vainilla. Métalo en una botella limpia y déjelo reposar durante 1 semana antes de usarlo.', '[{"name": "Water", "image": "https://www.thecocktaildb.com/images/ingredients/Water-small.png", "measure": "1 cup"}, {"name": "Brown sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Brown%20sugar-small.png", "measure": "3/4-1 cup"}, {"name": "Coffee", "image": "https://www.thecocktaildb.com/images/ingredients/Coffee-small.png", "measure": "4 tsp"}, {"name": "Rum", "image": "https://www.thecocktaildb.com/images/ingredients/Rum-small.png", "measure": "1 cup"}, {"name": "Vanilla extract", "image": "https://www.thecocktaildb.com/images/ingredients/Vanilla%20extract-small.png", "measure": "4 tsp"}]'::jsonb),
  ('12890', 'Cranberry Punch', 'Punch / Party Drink', false, 'Punch Bowl', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/mzgaqu1504389248.jpg', NULL, 'Combine first four ingredients. Stir until sugar is dissolved, chill. Then add ginger ale just before serving. Add ice ring to keep punch cold.', 'Mezclar los cuatro primeros ingredientes. Remover hasta que se disuelva el azúcar y enfriar. A continuación, añada ginger ale justo antes de servir. Añada un anillo de hielo para mantener el ponche frío.', '[{"name": "Cranberry juice", "image": "https://www.thecocktaildb.com/images/ingredients/Cranberry%20juice-small.png", "measure": "4 cups"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "1 1/2 cup"}, {"name": "Pineapple juice", "image": "https://www.thecocktaildb.com/images/ingredients/Pineapple%20juice-small.png", "measure": "4 cups"}, {"name": "Almond flavoring", "image": "https://www.thecocktaildb.com/images/ingredients/Almond%20flavoring-small.png", "measure": "1 tblsp"}, {"name": "Ginger ale", "image": "https://www.thecocktaildb.com/images/ingredients/Ginger%20ale-small.png", "measure": "2 qt"}]'::jsonb),
  ('12910', 'Egg Nog #4', 'Punch / Party Drink', true, 'Punch bowl', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/wpspsy1468875747.jpg', NULL, 'In a small mixer bowl beat egg yolks till blended. Gradually add 1/4 cup sugar, beating at high speed till thick and lemon colored. Stir in milk, stir in rum, bourbon, vanilla, and salt. Chill thoroughly. Whip cream. Wash beaters well. In a large mixer bowl beat egg whites till soft peaks form. Gradually add remaining 1/4 cup sugar, beating to stiff peaks. Fold yolk mixture and whipped cream into egg whites. Serve immediately. Sprinkle nutmeg over each serving. Serve in a punch bowl or another big bowl. NOTE: For a nonalcoholic eggnog, prepare Eggnog as above, except omit the bourbon and rum and increase the milk to 3 cups.', 'En una batidora pequeña, bata las yemas de huevo hasta obtener una mezcla homogénea. Añada gradualmente 1/4 de taza de azúcar, batiendo a velocidad alta hasta que espese y adquiera el color del limón. Añada la leche, el ron, el bourbon, la vainilla y la sal. Enfríe bien. Montar la nata. Lavar bien los batidores. En un bol grande batir las claras a punto de nieve. Añadir gradualmente el 1/4 de taza de azúcar restante, batiendo a punto de nieve. Incorporar la mezcla de yemas y nata montada a las claras. Servir inmediatamente. Espolvoree nuez moscada sobre cada porción. Servir en una ponchera u otro bol grande. NOTA: Para un ponche de huevo sin alcohol, prepare el ponche de huevo como se indica arriba, pero omita el bourbon y el ron y aumente la leche a 3 tazas.', '[{"name": "Egg yolk", "image": "https://www.thecocktaildb.com/images/ingredients/Egg%20yolk-small.png", "measure": "6"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "1/4 cup"}, {"name": "Milk", "image": "https://www.thecocktaildb.com/images/ingredients/Milk-small.png", "measure": "2 cups"}, {"name": "Light rum", "image": "https://www.thecocktaildb.com/images/ingredients/Light%20rum-small.png", "measure": "1/2 cup"}, {"name": "Bourbon", "image": "https://www.thecocktaildb.com/images/ingredients/Bourbon-small.png", "measure": "1/2 cup"}, {"name": "Vanilla extract", "image": "https://www.thecocktaildb.com/images/ingredients/Vanilla%20extract-small.png", "measure": "1 tsp"}, {"name": "Salt", "image": "https://www.thecocktaildb.com/images/ingredients/Salt-small.png", "measure": "1/4 tsp"}, {"name": "Whipping cream", "image": "https://www.thecocktaildb.com/images/ingredients/Whipping%20cream-small.png", "measure": "1 cup"}, {"name": "Egg white", "image": "https://www.thecocktaildb.com/images/ingredients/Egg%20white-small.png", "measure": "6"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "1/4 cup"}, {"name": "Nutmeg", "image": "https://www.thecocktaildb.com/images/ingredients/Nutmeg-small.png", "measure": "Ground"}]'::jsonb),
  ('12914', 'Egg-Nog - Classic Cooked', 'Punch / Party Drink', true, 'Pitcher', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/quxsvt1468875505.jpg', NULL, 'In large saucepan, beat together eggs, sugar and salt, if desired. Stir in 2 cups of the milk. Cook over low heat, stirring constantly, until mixture is thick enough to coat a metal spoon and reaches 160 degrees F. Remove from heat. Stir in remaining 2 cups milk and vanilla. Cover and regfigerate until thoroughly chilled, several hours or overnight. Just before serving, pour into bowl or pitcher. Garnish or add stir-ins, if desired. Choose 1 or several of: Chocolate curls, cinnamon sticks, extracts of flavorings, flavored brandy or liqueur, fruit juice or nectar, ground nutmeg, maraschino cherries, orange slices, peppermint sticks or candy canes, plain brandy, run or whiskey, sherbet or ice-cream, whipping cream, whipped. Serve immediately.', 'En un cazo grande, batir los huevos, el azúcar y la sal, si se desea. Añadir 2 tazas de leche. Cocer a fuego lento, sin dejar de remover, hasta que la mezcla esté lo bastante espesa como para cubrir una cuchara de metal y alcance los 160 grados F. Retirar del fuego. Añada las 2 tazas de leche restantes y la vainilla. Cúbrala y refrigérela hasta que esté bien fría, varias horas o toda la noche. Justo antes de servir, viértalo en un bol o en una jarra. Adorne o añada complementos, si lo desea. Elija 1 o varios de: Rizos de chocolate, palitos de canela, extractos de aromatizantes, brandy o licor aromatizado, zumo o néctar de frutas, nuez moscada molida, cerezas al marrasquino, rodajas de naranja, palitos de menta o bastones de caramelo, brandy natural, run o whisky, sorbete o helado, nata montada, chantilly. Servir inmediatamente.', '[{"name": "Egg", "image": "https://www.thecocktaildb.com/images/ingredients/Egg-small.png", "measure": "6"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "1/4 cup"}, {"name": "Salt", "image": "https://www.thecocktaildb.com/images/ingredients/Salt-small.png", "measure": "1/4 tsp"}, {"name": "Milk", "image": "https://www.thecocktaildb.com/images/ingredients/Milk-small.png", "measure": "1 qt"}, {"name": "Vanilla extract", "image": "https://www.thecocktaildb.com/images/ingredients/Vanilla%20extract-small.png", "measure": "1 tsp"}]'::jsonb),
  ('12916', 'Egg Nog - Healthy', 'Punch / Party Drink', true, 'Collins Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/qxuppv1468875308.jpg', NULL, 'Whip egg substitute and sugar together, combine with the two kinds of milk, vanilla, and rum. Mix well. Chill over night. Sprinkle with nutmeg. Makes 6 servings.', 'Batir el sustituto del huevo y el azúcar juntos, combinar con los dos tipos de leche, la vainilla y el ron. Mezcle bien. Dejar enfriar toda la noche. Espolvorear con nuez moscada. Rinde 6 porciones.', '[{"name": "Egg", "image": "https://www.thecocktaildb.com/images/ingredients/Egg-small.png", "measure": "1/2 cup"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "3 tblsp"}, {"name": "Condensed milk", "image": "https://www.thecocktaildb.com/images/ingredients/Condensed%20milk-small.png", "measure": "13 oz skimmed"}, {"name": "Milk", "image": "https://www.thecocktaildb.com/images/ingredients/Milk-small.png", "measure": "3/4 cup skimmed"}, {"name": "Vanilla extract", "image": "https://www.thecocktaildb.com/images/ingredients/Vanilla%20extract-small.png", "measure": "1 tsp"}, {"name": "Rum", "image": "https://www.thecocktaildb.com/images/ingredients/Rum-small.png", "measure": "1 tsp"}, {"name": "Nutmeg", "image": "https://www.thecocktaildb.com/images/ingredients/Nutmeg-small.png", "measure": null}]'::jsonb),
  ('12944', 'Gluehwein', 'Punch / Party Drink', true, 'Irish coffee cup', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/vuxwvt1468875418.jpg', NULL, 'Boil sugar and spices in water, leave in the water for 30 minutes. Strain the spiced water and mix with the wine. Heat slowly until short of boiling temperature. (To remove alcohol, let it boil for a while.) You may add lemon or orange juice to taste. Serve in irish coffee cup.', 'Hervir el azúcar y las especias en agua, dejar en el agua durante 30 minutos. Colar el agua especiada y mezclar con el vino. Calentar lentamente hasta que esté a punto de hervir. (Para eliminar el alcohol, dejar hervir un rato.) Se puede añadir zumo de limón o naranja al gusto. Servir en taza de café irlandés.', '[{"name": "Red wine", "image": "https://www.thecocktaildb.com/images/ingredients/Red%20wine-small.png", "measure": "1 L"}, {"name": "Water", "image": "https://www.thecocktaildb.com/images/ingredients/Water-small.png", "measure": "125 ml"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "60 gr"}, {"name": "Cinnamon", "image": "https://www.thecocktaildb.com/images/ingredients/Cinnamon-small.png", "measure": "1"}, {"name": "Cloves", "image": "https://www.thecocktaildb.com/images/ingredients/Cloves-small.png", "measure": "3"}, {"name": "Lemon peel", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20peel-small.png", "measure": "1 tblsp"}]'::jsonb),
  ('12954', 'Holloween Punch', 'Punch / Party Drink', false, 'Punch bowl', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/lfeoe41504888925.jpg', NULL, 'Take a bunch of grape juice and a bunch of fizzy stuff (club soda, ginger ale, lemonlime, whatever). Mix them in a punch bowl. Take orange sherbet and lime sherbet. Scoop out scoops and float them in the punch, let them melt a little so that a nasty film spreads all over the top of the punch but there are still "bubbles" in it in the form of sherbet scoops. Looks horrible, tastes just fine.', 'Coge un montón de zumo de uva y un montón de bebidas gaseosas (club soda, ginger ale, lima, lo que sea). Mézclalos en una ponchera. Coge sorbete de naranja y sorbete de lima. Saca cucharadas y ponlas a flotar en el ponche, deja que se derritan un poco para que se extienda una película desagradable por toda la parte superior del ponche, pero sigue habiendo "burbujas" en forma de cucharadas de sorbete. Tiene un aspecto horrible, pero sabe muy bien.', '[{"name": "Grape juice", "image": "https://www.thecocktaildb.com/images/ingredients/Grape%20juice-small.png", "measure": null}, {"name": "Carbonated soft drink", "image": "https://www.thecocktaildb.com/images/ingredients/Carbonated%20soft%20drink-small.png", "measure": ", orange"}, {"name": "Sherbet", "image": "https://www.thecocktaildb.com/images/ingredients/Sherbet-small.png", "measure": null}, {"name": "Sherbet", "image": "https://www.thecocktaildb.com/images/ingredients/Sherbet-small.png", "measure": null}]'::jsonb),
  ('12988', 'Mulled Wine', 'Punch / Party Drink', true, 'Collins Glass', NULL, '{Christmas}'::text[], 'https://www.thecocktaildb.com/images/media/drink/iuwi6h1504735724.jpg', NULL, 'Simmer 3 cups water with, sugar, cloves, cinnamon sticks, and lemon peel in a stainless steel pot for 10 minutes. Add wine heat to a "coffee temperature" (DO NOT BOIL) then add the brandy.', 'Cocer a fuego lento 3 tazas de agua con, azúcar, clavo, canela en rama y piel de limón en una olla de acero inoxidable durante 10 minutos. Añadir el vino y calentar a "temperatura de café" (NO HERVIR) y, a continuación, añadir el brandy.', '[{"name": "Water", "image": "https://www.thecocktaildb.com/images/ingredients/Water-small.png", "measure": "3 cups"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "1 cup"}, {"name": "Cloves", "image": "https://www.thecocktaildb.com/images/ingredients/Cloves-small.png", "measure": "12"}, {"name": "Cinnamon", "image": "https://www.thecocktaildb.com/images/ingredients/Cinnamon-small.png", "measure": "2"}, {"name": "Lemon peel", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20peel-small.png", "measure": "1"}, {"name": "Red wine", "image": "https://www.thecocktaildb.com/images/ingredients/Red%20wine-small.png", "measure": "750 ml"}, {"name": "Brandy", "image": "https://www.thecocktaildb.com/images/ingredients/Brandy-small.png", "measure": "1/4 cup"}]'::jsonb),
  ('13020', 'Sangria', 'Punch / Party Drink', true, 'Pitcher', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/xrvxpp1441249280.jpg', NULL, 'Mix all together in a pitcher and refrigerate. Add cloves and cinnamon sticks to taste. Serve in wine glasses.', 'Mézclelo todo en una jarra y refrigérelo. Añada clavo y canela en rama al gusto. Servir en copas de vino.', '[{"name": "Red wine", "image": "https://www.thecocktaildb.com/images/ingredients/Red%20wine-small.png", "measure": "1 bottle"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "1/2 cup"}, {"name": "Orange juice", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20juice-small.png", "measure": "1 cup"}, {"name": "Lemon juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20juice-small.png", "measure": "1 cup"}, {"name": "Cloves", "image": "https://www.thecocktaildb.com/images/ingredients/Cloves-small.png", "measure": null}, {"name": "Cinnamon", "image": "https://www.thecocktaildb.com/images/ingredients/Cinnamon-small.png", "measure": null}]'::jsonb),
  ('13024', 'Sweet Sangria', 'Punch / Party Drink', true, 'Pitcher', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/uqqvsp1468924228.jpg', NULL, 'Dissolve the sugar in hot water and cool. Peel the citrus fruits and break into wedges. Mix the wine, sugar syrup, fruit, and Fresca in a pitcher and put in the fridge for a few hours. Serve in tall glasses with a straw.', 'Disolver el azúcar en agua caliente y enfriar. Pelar los cítricos y partirlos en gajos. Mezcle el vino, el jarabe de azúcar, la fruta y la Fresca en una jarra y métala en el frigorífico durante unas horas. Servir en vasos altos con pajita.', '[{"name": "Red wine", "image": "https://www.thecocktaildb.com/images/ingredients/Red%20wine-small.png", "measure": "2 bottles"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "1 cup"}, {"name": "Water", "image": "https://www.thecocktaildb.com/images/ingredients/Water-small.png", "measure": "2 cups hot"}, {"name": "Apple", "image": "https://www.thecocktaildb.com/images/ingredients/Apple-small.png", "measure": "1 cup"}, {"name": "Orange", "image": "https://www.thecocktaildb.com/images/ingredients/Orange-small.png", "measure": "wedges"}, {"name": "Lime", "image": "https://www.thecocktaildb.com/images/ingredients/Lime-small.png", "measure": "wedges"}, {"name": "Lemon", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon-small.png", "measure": null}, {"name": "Fresca", "image": "https://www.thecocktaildb.com/images/ingredients/Fresca-small.png", "measure": null}]'::jsonb),
  ('13056', 'Wine Cooler', 'Punch / Party Drink', true, 'Collins Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/yutxtv1473344210.jpg', NULL, 'Mix wine and soft drink. Pour into glass. Add ice.', 'Mezclar el vino y el refresco. Verter en un vaso. Añadir hielo.', '[{"name": "Red wine", "image": "https://www.thecocktaildb.com/images/ingredients/Red%20wine-small.png", "measure": "2 oz white or"}, {"name": "Lemon-lime soda", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon-lime%20soda-small.png", "measure": "5 oz"}, {"name": "Ice", "image": "https://www.thecocktaildb.com/images/ingredients/Ice-small.png", "measure": "cubes"}]'::jsonb),
  ('13058', 'Wine Punch', 'Punch / Party Drink', true, 'Collins Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/txustu1473344310.jpg', NULL, 'Combine all of the ingredients and pour over a block of ice.', 'Mezcle todos los ingredientes y viértalos sobre un bloque de hielo.', '[{"name": "Red wine", "image": "https://www.thecocktaildb.com/images/ingredients/Red%20wine-small.png", "measure": "1 bottle"}, {"name": "Lemon", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon-small.png", "measure": "2"}, {"name": "Orange juice", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20juice-small.png", "measure": "1 cup"}, {"name": "Orange", "image": "https://www.thecocktaildb.com/images/ingredients/Orange-small.png", "measure": "3"}, {"name": "Pineapple juice", "image": "https://www.thecocktaildb.com/images/ingredients/Pineapple%20juice-small.png", "measure": "1 cup"}]'::jsonb),
  ('13070', 'Fahrenheit 5000', 'Shot', true, 'Shot glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/tysssx1473344692.jpg', NULL, 'Cover bottom of shot glass with Tabasco Sauce and then fill with half Firewater and half Absolut Peppar.', 'Cubra el fondo del vaso de chupito con Salsa Tabasco y luego llénelo con la mitad de Firewater y la mitad de Absolut Peppar.', '[{"name": "Firewater", "image": "https://www.thecocktaildb.com/images/ingredients/Firewater-small.png", "measure": "1/2 oz"}, {"name": "Absolut Peppar", "image": "https://www.thecocktaildb.com/images/ingredients/Absolut%20Peppar-small.png", "measure": "1/2 oz"}, {"name": "Tabasco sauce", "image": "https://www.thecocktaildb.com/images/ingredients/Tabasco%20sauce-small.png", "measure": "1 dash"}]'::jsonb),
  ('13072', 'Popped cherry', 'Ordinary Drink', true, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/sxvrwv1473344825.jpg', NULL, 'Served over ice in a tall glass with a popped cherry (can add more popped cherries if in the mood)!', 'Servido sobre hielo en un vaso alto con una cereza reventada (puede añadir más cerezas reventadas si le apetece).', '[{"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "2 oz"}, {"name": "Cherry liqueur", "image": "https://www.thecocktaildb.com/images/ingredients/Cherry%20liqueur-small.png", "measure": "2 oz"}, {"name": "Cranberry juice", "image": "https://www.thecocktaildb.com/images/ingredients/Cranberry%20juice-small.png", "measure": "4 oz"}, {"name": "Orange juice", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20juice-small.png", "measure": "4 oz"}]'::jsonb),
  ('13128', 'Diesel', 'Beer', true, 'Pint glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/sxrrqq1454512852.jpg', NULL, 'Pour the lager first then add the blackcurrant cordial. Top up with the cider. The colour sholud be very dark approaching the colour of Guiness.', 'Vierta primero la cerveza y luego agregue el cordial de grosella negra. Completar con la sidra. El color debe ser muy oscuro, acercándose al color de Guiness.', '[{"name": "Lager", "image": "https://www.thecocktaildb.com/images/ingredients/Lager-small.png", "measure": "1/2 pint"}, {"name": "Cider", "image": "https://www.thecocktaildb.com/images/ingredients/Cider-small.png", "measure": "1/2 pint"}, {"name": "Blackcurrant cordial", "image": "https://www.thecocktaildb.com/images/ingredients/Blackcurrant%20cordial-small.png", "measure": "1 dash"}]'::jsonb),
  ('13190', 'Kool-Aid Shot', 'Shot', true, 'Old-fashioned glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/fegm621503564966.jpg', NULL, 'Pour into a large glass with ice and stir. Add a little cranberry juice to taste.', 'Verter en un vaso grande con hielo y remover. Añada un poco de zumo de arándanos al gusto.', '[{"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "1 shot"}, {"name": "Amaretto", "image": "https://www.thecocktaildb.com/images/ingredients/Amaretto-small.png", "measure": "1 shot"}, {"name": "Sloe gin", "image": "https://www.thecocktaildb.com/images/ingredients/Sloe%20gin-small.png", "measure": "1 shot"}, {"name": "Triple sec", "image": "https://www.thecocktaildb.com/images/ingredients/Triple%20sec-small.png", "measure": "1 shot"}, {"name": "Cranberry juice", "image": "https://www.thecocktaildb.com/images/ingredients/Cranberry%20juice-small.png", "measure": null}]'::jsonb),
  ('13192', 'National Aquarium', 'Ordinary Drink', true, 'Collins Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/dlw0om1503565021.jpg', NULL, 'Pour all ingredients into a shaker of ice. Shake well. Serve on the rocks.', 'Vierta todos los ingredientes en una coctelera con hielo. Agitar bien. Servir con hielo.', '[{"name": "Rum", "image": "https://www.thecocktaildb.com/images/ingredients/Rum-small.png", "measure": "1/2 oz"}, {"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "1/2 oz"}, {"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "1/2 oz"}, {"name": "Blue Curacao", "image": "https://www.thecocktaildb.com/images/ingredients/Blue%20Curacao-small.png", "measure": "1/2 oz"}, {"name": "Sour mix", "image": "https://www.thecocktaildb.com/images/ingredients/Sour%20mix-small.png", "measure": "2 oz"}, {"name": "Lemon-lime soda", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon-lime%20soda-small.png", "measure": "1 splash"}]'::jsonb),
  ('13194', 'Damned if you do', 'Shot', true, 'Shot glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/ql7bmx1503565106.jpg', NULL, 'Pour into shot glass. Put in mouth. Repeat as deemed necessary.', 'Vierta en un vaso de chupito. Poner en la boca. Repita según lo considere necesario.', '[{"name": "Whiskey", "image": "https://www.thecocktaildb.com/images/ingredients/Whiskey-small.png", "measure": "0.75 oz"}, {"name": "Hot Damn", "image": "https://www.thecocktaildb.com/images/ingredients/Hot%20Damn-small.png", "measure": "0.25 oz"}]'::jsonb),
  ('13196', 'Long vodka', 'Ordinary Drink', true, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/9179i01503565212.jpg', NULL, 'Shake a tall glass with ice cubes and Angostura, coating the inside of the glass. Por the vodka onto this, add 1 slice of lime and squeeze juice out of remainder, mix with tonic, stir and voila you have a Long Vodka', 'Agite un vaso alto con cubitos de hielo y Angostura, cubriendo el interior del vaso. Vierta el vodka, añada una rodaja de lima y exprima el zumo restante, mezcle con la tónica, remueva y ya tiene un Long Vodka.', '[{"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "5 cl"}, {"name": "Lime", "image": "https://www.thecocktaildb.com/images/ingredients/Lime-small.png", "measure": "1/2"}, {"name": "Angostura bitters", "image": "https://www.thecocktaildb.com/images/ingredients/Angostura%20bitters-small.png", "measure": "4 dashes"}, {"name": "Tonic water", "image": "https://www.thecocktaildb.com/images/ingredients/Tonic%20water-small.png", "measure": "1 dl Schweppes"}, {"name": "Ice", "image": "https://www.thecocktaildb.com/images/ingredients/Ice-small.png", "measure": "4"}]'::jsonb),
  ('13198', 'Quick F**K', 'Shot', true, 'Shot glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/wvtwpp1478963454.jpg', NULL, 'In a shot glass add 1/3 Kahlua first. Then 1/3 Miduri, topping it off with a 1/3 bailey''s irish cream', 'En un vaso de chupito agregue primero 1/3 de Kahlua. Luego 1/3 de Miduri, rematando con 1/3 de crema irlandesa de Bailey''s', '[{"name": "Kahlua", "image": "https://www.thecocktaildb.com/images/ingredients/Kahlua-small.png", "measure": "1 part"}, {"name": "Midori melon liqueur", "image": "https://www.thecocktaildb.com/images/ingredients/Midori%20melon%20liqueur-small.png", "measure": "1 part"}, {"name": "Baileys irish cream", "image": "https://www.thecocktaildb.com/images/ingredients/Baileys%20irish%20cream-small.png", "measure": "1 part"}]'::jsonb),
  ('13200', 'Owen''s Grandmother''s Revenge', 'Ordinary Drink', true, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/0wt4uo1503565321.jpg', NULL, 'Add ingredients and mix in blender.', 'Añada los ingredientes y mézclelos en la batidora.', '[{"name": "Whiskey", "image": "https://www.thecocktaildb.com/images/ingredients/Whiskey-small.png", "measure": "12 oz"}, {"name": "Beer", "image": "https://www.thecocktaildb.com/images/ingredients/Beer-small.png", "measure": "12 oz"}, {"name": "Lemonade", "image": "https://www.thecocktaildb.com/images/ingredients/Lemonade-small.png", "measure": "12 oz frozen"}, {"name": "Ice", "image": "https://www.thecocktaildb.com/images/ingredients/Ice-small.png", "measure": "1 cup crushed"}]'::jsonb),
  ('13202', 'Flaming Dr. Pepper', 'Shot', true, 'Collins Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/d30z931503565384.jpg', NULL, 'Add Amaretto, Bacardi, and vodka. Mix in the Dr. Pepper and beer', 'Añadir Amaretto, Bacardi y vodka. Mezclar el Dr. Pepper y la cerveza', '[{"name": "Amaretto", "image": "https://www.thecocktaildb.com/images/ingredients/Amaretto-small.png", "measure": "1 oz"}, {"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "1 oz"}, {"name": "151 proof rum", "image": "https://www.thecocktaildb.com/images/ingredients/151%20proof%20rum-small.png", "measure": "1 oz Bacardi"}, {"name": "Dr. Pepper", "image": "https://www.thecocktaildb.com/images/ingredients/Dr.%20Pepper-small.png", "measure": "1 oz"}, {"name": "Beer", "image": "https://www.thecocktaildb.com/images/ingredients/Beer-small.png", "measure": "1 oz"}]'::jsonb),
  ('13204', 'New York Lemonade', 'Cocktail', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/b3n0ge1503565473.jpg', NULL, 'Serve in a chilled cocktail glass. Lemon and sugar the rim. Stir and Strain.', 'Servir en una copa de cóctel fría. Limón y azúcar en el borde. Remover y colar.', '[{"name": "Absolut Citron", "image": "https://www.thecocktaildb.com/images/ingredients/Absolut%20Citron-small.png", "measure": "2 oz"}, {"name": "Grand Marnier", "image": "https://www.thecocktaildb.com/images/ingredients/Grand%20Marnier-small.png", "measure": "1 oz"}, {"name": "Lemon juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20juice-small.png", "measure": "2 oz sweetened"}, {"name": "Club soda", "image": "https://www.thecocktaildb.com/images/ingredients/Club%20soda-small.png", "measure": "1 oz"}]'::jsonb),
  ('13206', 'Caipirissima', 'Ordinary Drink', true, 'Collins Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/yd47111503565515.jpg', NULL, 'Same as Caipirinha but instead of cachaca you add WHITE RUM. It''s great!!!!!!!!', 'Igual que la Caipirinha pero en vez de cachaca se le añade RON BLANCO. ¡¡¡¡¡¡¡¡Es genial!!!!!!!!', '[{"name": "Lime", "image": "https://www.thecocktaildb.com/images/ingredients/Lime-small.png", "measure": "2"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "2 tblsp"}, {"name": "White rum", "image": "https://www.thecocktaildb.com/images/ingredients/White%20rum-small.png", "measure": "2-3 oz"}, {"name": "Ice", "image": "https://www.thecocktaildb.com/images/ingredients/Ice-small.png", "measure": "crushed"}]'::jsonb),
  ('13214', 'Pisco Sour', 'Cocktail', true, 'Cocktail glass', 'New Era Drinks', '{IBA,NewEra}'::text[], 'https://www.thecocktaildb.com/images/media/drink/tsssur1439907622.jpg', 'https://www.youtube.com/watch?v=j_LTDlBOX04', 'Vigorously shake and strain contents in a cocktail shaker with ice cubes, then pour into glass and garnish with bitters.', 'Agite vigorosamente y cuele el contenido en una coctelera con cubitos de hielo, luego viértalo en un vaso y decore con amargo.', '[{"name": "Pisco", "image": "https://www.thecocktaildb.com/images/ingredients/Pisco-small.png", "measure": "2 oz"}, {"name": "Lemon juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20juice-small.png", "measure": "1 oz"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "1-2 tblsp"}, {"name": "Ice", "image": "https://www.thecocktaildb.com/images/ingredients/Ice-small.png", "measure": "1"}, {"name": "Egg White", "image": "https://www.thecocktaildb.com/images/ingredients/Egg%20White-small.png", "measure": null}]'::jsonb),
  ('13222', 'Big Red', 'Shot', true, 'Shot glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/yqwuwu1441248116.jpg', NULL, 'Pour ingredients into 1 ounce shot glass', 'Vierta los ingredientes en un vaso de chupito de 1 onza.', '[{"name": "Irish cream", "image": "https://www.thecocktaildb.com/images/ingredients/Irish%20cream-small.png", "measure": "1/2 oz"}, {"name": "Goldschlager", "image": "https://www.thecocktaildb.com/images/ingredients/Goldschlager-small.png", "measure": "1/2 oz"}]'::jsonb),
  ('13328', 'Chocolate Milk', 'Shot', true, 'Shot Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/j6q35t1504889399.jpg', NULL, 'Put the milk in the bottom, pour the Liquer on top and add the dash of amaretto. Do not mix. SLAM IT!', 'Poner la leche en el fondo, verter el Licor encima y añadir el chorrito de amaretto. No mezclar. ¡GOLPELO!', '[{"name": "Chocolate liqueur", "image": "https://www.thecocktaildb.com/images/ingredients/Chocolate%20liqueur-small.png", "measure": "1/2 shot"}, {"name": "Milk", "image": "https://www.thecocktaildb.com/images/ingredients/Milk-small.png", "measure": "1/2 shot"}, {"name": "Amaretto", "image": "https://www.thecocktaildb.com/images/ingredients/Amaretto-small.png", "measure": "1 dash"}]'::jsonb),
  ('13332', 'B-53', 'Shot', true, 'Collins Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/rwqxrv1461866023.jpg', NULL, 'Layer the Kahlua, Sambucca and Grand Marnier into a shot glas in that order. Better than B-52', 'Ponga el Kahlua, el Sambucca y el Grand Marnier en un vaso de chupito en ese orden. Mejor que el B-52', '[{"name": "Kahlua", "image": "https://www.thecocktaildb.com/images/ingredients/Kahlua-small.png", "measure": "1/3 shot"}, {"name": "Sambuca", "image": "https://www.thecocktaildb.com/images/ingredients/Sambuca-small.png", "measure": "1/3 shot"}, {"name": "Grand Marnier", "image": "https://www.thecocktaildb.com/images/ingredients/Grand%20Marnier-small.png", "measure": "1/3 shot"}]'::jsonb),
  ('13377', 'Sea breeze', 'Ordinary Drink', true, 'Highball glass', 'Contemporary Classics', '{IBA,ContemporaryClassic}'::text[], 'https://www.thecocktaildb.com/images/media/drink/7rfuks1504371562.jpg', NULL, 'Build all ingredients in a highball glass filled with ice. Garnish with lime wedge.', 'Coloque todos los ingredientes en un vaso alto lleno de hielo. Adorne con una rodaja de lima.', '[{"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "1 1/2 oz"}, {"name": "Cranberry juice", "image": "https://www.thecocktaildb.com/images/ingredients/Cranberry%20juice-small.png", "measure": "4 oz"}, {"name": "Grapefruit juice", "image": "https://www.thecocktaildb.com/images/ingredients/Grapefruit%20juice-small.png", "measure": "1 oz"}]'::jsonb),
  ('13395', 'Bob Marley', 'Shot', true, 'Shot glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/rrqrst1477140664.jpg', NULL, 'Layer in a 2 oz shot glass or pony glass', 'Coloque en capas en un vaso de chupito o en un vaso de pony de 2 oz', '[{"name": "Midori melon liqueur", "image": "https://www.thecocktaildb.com/images/ingredients/Midori%20melon%20liqueur-small.png", "measure": "1/2 oz"}, {"name": "Jägermeister", "image": "https://www.thecocktaildb.com/images/ingredients/J%C3%A4germeister-small.png", "measure": "1/2 oz"}, {"name": "Goldschlager", "image": "https://www.thecocktaildb.com/images/ingredients/Goldschlager-small.png", "measure": "1/2 oz"}]'::jsonb),
  ('13499', 'Oreo Mudslide', 'Ordinary Drink', true, 'Collins Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/tpwwut1468925017.jpg', NULL, 'Blend Vodka, Kahlua, Bailey''s, ice-cream and the Oreo well in a blender. Pour into a large frosted glass. Garnish with whipped cream and a cherry.', 'Mezcle bien en una batidora el vodka, el Kahlua, el Bailey''s, el helado y las Oreo. Verter en un vaso grande escarchado. Decorar con nata montada y una cereza.', '[{"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "1 oz"}, {"name": "Kahlua", "image": "https://www.thecocktaildb.com/images/ingredients/Kahlua-small.png", "measure": "1 oz"}, {"name": "Baileys irish cream", "image": "https://www.thecocktaildb.com/images/ingredients/Baileys%20irish%20cream-small.png", "measure": "1 oz"}, {"name": "Vanilla ice-cream", "image": "https://www.thecocktaildb.com/images/ingredients/Vanilla%20ice-cream-small.png", "measure": "2 scoops"}, {"name": "Oreo cookie", "image": "https://www.thecocktaildb.com/images/ingredients/Oreo%20cookie-small.png", "measure": "1"}]'::jsonb),
  ('13501', 'ABC', 'Shot', true, 'Shot glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/tqpvqp1472668328.jpg', NULL, 'Layered in a shot glass.', 'Coloque todos los ingredientes en un vaso de chupito.', '[{"name": "Amaretto", "image": "https://www.thecocktaildb.com/images/ingredients/Amaretto-small.png", "measure": "1/3"}, {"name": "Baileys irish cream", "image": "https://www.thecocktaildb.com/images/ingredients/Baileys%20irish%20cream-small.png", "measure": "1/3"}, {"name": "Cognac", "image": "https://www.thecocktaildb.com/images/ingredients/Cognac-small.png", "measure": "1/3"}]'::jsonb),
  ('13535', 'Pink Panty Pulldowns', 'Ordinary Drink', true, 'Collins Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/squsuy1468926657.jpg', NULL, 'Shake well', 'Agitar bien', '[{"name": "Sprite", "image": "https://www.thecocktaildb.com/images/ingredients/Sprite-small.png", "measure": "1 L"}, {"name": "Pink lemonade", "image": "https://www.thecocktaildb.com/images/ingredients/Pink%20lemonade-small.png", "measure": "2 cups"}, {"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "2 cups"}]'::jsonb),
  ('13539', 'Ice Pick', 'Ordinary Drink', true, 'Collins Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/ypsrqp1469091726.jpg', NULL, 'Put Vodka in glass fill with iced tea. Stir in lemon to taste.', 'Ponga el vodka en un vaso y llénelo con té helado. Añada limón al gusto.', '[{"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "1 1/2 oz"}, {"name": "Iced tea", "image": "https://www.thecocktaildb.com/images/ingredients/Iced%20tea-small.png", "measure": "6 oz"}, {"name": "Lemon juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20juice-small.png", "measure": "to taste"}]'::jsonb),
  ('13581', '410 Gone', 'Ordinary Drink', true, 'Collins Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/xtuyqv1472669026.jpg', NULL, 'Mix together and enjoy!', NULL, '[{"name": "Peach Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Peach%20Vodka-small.png", "measure": "2-3 oz"}, {"name": "Coca-Cola", "image": "https://www.thecocktaildb.com/images/ingredients/Coca-Cola-small.png", "measure": null}]'::jsonb),
  ('13621', 'Tequila Sunrise', 'Cocktail', true, 'Highball glass', 'Contemporary Classics', '{IBA,ContemporaryClassic}'::text[], 'https://www.thecocktaildb.com/images/media/drink/quqyqp1480879103.jpg', NULL, 'Pour the tequila and orange juice into glass over ice. Add the grenadine, which will sink to the bottom. Stir gently to create the sunrise effect. Garnish and serve.', 'Vierta el tequila y el jugo de naranja en un vaso con hielo. Agrega la granadina, que se hundirá hasta el fondo. Revuelva suavemente para crear el efecto del amanecer. Adorne y sirva.', '[{"name": "Tequila", "image": "https://www.thecocktaildb.com/images/ingredients/Tequila-small.png", "measure": "2 measures"}, {"name": "Orange juice", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20juice-small.png", "measure": null}, {"name": "Grenadine", "image": "https://www.thecocktaildb.com/images/ingredients/Grenadine-small.png", "measure": null}]'::jsonb),
  ('13675', 'Flander''s Flake-Out', 'Ordinary Drink', true, 'Collins Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/sqvqrx1461866705.jpg', NULL, 'Bang ''em both in.', 'Golpéalos a ambos.', '[{"name": "Sambuca", "image": "https://www.thecocktaildb.com/images/ingredients/Sambuca-small.png", "measure": "1/4 glass"}, {"name": "Sarsaparilla", "image": "https://www.thecocktaildb.com/images/ingredients/Sarsaparilla-small.png", "measure": "3/4 glass"}]'::jsonb),
  ('13751', 'Cuba Libra', 'Ordinary Drink', true, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/ck6d0p1504388696.jpg', NULL, 'Fill tall glass with ice cubes. Add rum. Rub cut edge of lime on rim of glass then squeeze juice into glass. Fill with Coca-Cola. Garnish with lime slice. Enjoy!', 'Llene el vaso alto con cubitos de hielo. Añada ron. Frote el borde cortado de la lima en el borde del vaso y, a continuación, exprima el zumo en el vaso. Rellenar con Coca-Cola. Decóralo con una rodaja de lima. ¡Que aproveche!', '[{"name": "Dark rum", "image": "https://www.thecocktaildb.com/images/ingredients/Dark%20rum-small.png", "measure": "1-2 shot"}, {"name": "Lime", "image": "https://www.thecocktaildb.com/images/ingredients/Lime-small.png", "measure": "Squeeze"}, {"name": "Coca-Cola", "image": "https://www.thecocktaildb.com/images/ingredients/Coca-Cola-small.png", "measure": "Fill with"}, {"name": "Ice", "image": "https://www.thecocktaildb.com/images/ingredients/Ice-small.png", "measure": null}]'::jsonb),
  ('13775', 'Jelly Bean', 'Shot', true, 'Cordial glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/bglc6y1504388797.jpg', NULL, 'mix equal parts in pony glass-tastes just like a jelly bean!', 'mezcle partes iguales en un vaso de pony; ¡sabe como una gominola!', '[{"name": "Blackberry brandy", "image": "https://www.thecocktaildb.com/images/ingredients/Blackberry%20brandy-small.png", "measure": "1 oz"}, {"name": "Anis", "image": "https://www.thecocktaildb.com/images/ingredients/Anis-small.png", "measure": "1 oz"}]'::jsonb),
  ('13837', 'Kir Royale', 'Ordinary Drink', true, 'Champagne Flute', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/yt9i7n1504370388.jpg', NULL, 'Pour Creme de cassis in glass, gently pour champagne on top', 'Vierta la crema de cassis en un vaso y vierta suavemente el champán encima.', '[{"name": "Creme de Cassis", "image": "https://www.thecocktaildb.com/images/ingredients/Creme%20de%20Cassis-small.png", "measure": "1 part"}, {"name": "Champagne", "image": "https://www.thecocktaildb.com/images/ingredients/Champagne-small.png", "measure": "5 parts"}]'::jsonb),
  ('13847', 'Jackhammer', 'Ordinary Drink', true, 'Collins Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/9von5j1504388896.jpg', NULL, 'Serve over ice- Warning,Deadly!', 'Servir sobre hielo. ¡Advertencia, mortal!', '[{"name": "Jack Daniels", "image": "https://www.thecocktaildb.com/images/ingredients/Jack%20Daniels-small.png", "measure": "1 oz"}, {"name": "Amaretto", "image": "https://www.thecocktaildb.com/images/ingredients/Amaretto-small.png", "measure": "1 oz"}]'::jsonb),
  ('13861', 'Nutty Irishman', 'Shake', true, 'Highball Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/xspupx1441248014.jpg', NULL, 'Serve over ice', 'Servir con hielo', '[{"name": "Baileys irish cream", "image": "https://www.thecocktaildb.com/images/ingredients/Baileys%20irish%20cream-small.png", "measure": "1 part"}, {"name": "Frangelico", "image": "https://www.thecocktaildb.com/images/ingredients/Frangelico-small.png", "measure": "1 part"}, {"name": "Milk", "image": "https://www.thecocktaildb.com/images/ingredients/Milk-small.png", "measure": "1 part"}]'::jsonb),
  ('13899', '3 Wise Men', 'Shot', true, 'Collins glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/wxqpyw1468877677.jpg', NULL, 'put them them in a glass... and slam it to tha head.', 'mételos en un vaso... y dáselo en la cabeza.', '[{"name": "Jack Daniels", "image": "https://www.thecocktaildb.com/images/ingredients/Jack%20Daniels-small.png", "measure": "1/3 oz"}, {"name": "Johnnie Walker", "image": "https://www.thecocktaildb.com/images/ingredients/Johnnie%20Walker-small.png", "measure": "1/3 oz"}, {"name": "Jim Beam", "image": "https://www.thecocktaildb.com/images/ingredients/Jim%20Beam-small.png", "measure": "1/3 oz"}]'::jsonb),
  ('13936', 'Miami Vice', 'Cocktail', true, 'Cocktail glass', NULL, '{IBA}'::text[], 'https://www.thecocktaildb.com/images/media/drink/qvuyqw1441208955.jpg', NULL, 'First: Mix pina colada with 2.5 oz. of rum with ice(set aside). Second: Mix daiquiri with 2.5 oz. of rum with ice. Third: While frozen, add pina colda mix then daiquiri mix in glass (Making sure they do not get mixed together).', 'Primero: Mezclar la piña colada con 2,5 onzas de ron con hielo (reservar). Segundo: Mezclar el daiquiri con 2,5 onzas de ron y hielo. Tercero: Mientras está congelado, añada la mezcla de piña colada y luego la de daiquiri en el vaso (asegurándose de que no se mezclen).', '[{"name": "151 proof rum", "image": "https://www.thecocktaildb.com/images/ingredients/151%20proof%20rum-small.png", "measure": "5 oz Bacardi"}, {"name": "Pina colada mix", "image": "https://www.thecocktaildb.com/images/ingredients/Pina%20colada%20mix-small.png", "measure": "frozen"}, {"name": "Daiquiri mix", "image": "https://www.thecocktaildb.com/images/ingredients/Daiquiri%20mix-small.png", "measure": "frozen"}]'::jsonb),
  ('13938', 'AT&T', 'Ordinary Drink', true, 'Highball Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/rhhwmp1493067619.jpg', NULL, 'Pour Vodka and Gin over ice, add Tonic and Stir', 'Vierta el vodka y la ginebra sobre el hielo, añada la tónica y remueva', '[{"name": "Absolut Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Absolut%20Vodka-small.png", "measure": "1 oz"}, {"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "1 oz"}, {"name": "Tonic water", "image": "https://www.thecocktaildb.com/images/ingredients/Tonic%20water-small.png", "measure": "4 oz"}]'::jsonb),
  ('13940', '69 Special', 'Ordinary Drink', true, 'Collins Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/vqyxqx1472669095.jpg', NULL, 'Pour 2 oz. gin. Add 4 oz. 7-up. Add Lemon Juice for flavor. If you are weak, top up glass with more 7-Up.', 'Vierta 2 oz. de ginebra. Añada 4 oz. de 7-up. Añada zumo de limón para darle sabor. Si es débil, rellene el vaso con más 7-Up.', '[{"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "2 oz dry"}, {"name": "7-Up", "image": "https://www.thecocktaildb.com/images/ingredients/7-Up-small.png", "measure": "4 oz"}, {"name": "Lemon juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20juice-small.png", "measure": "0.75 oz"}]'::jsonb),
  ('13971', 'Irish Coffee', 'Coffee / Tea', true, 'Irish coffee cup', 'Contemporary Classics', '{IBA,ContemporaryClassic}'::text[], 'https://www.thecocktaildb.com/images/media/drink/sywsqw1439906999.jpg', NULL, 'Heat the coffee, whiskey and sugar; do not boil. Pour into glass and top with cream; serve hot.', 'Calentar el café, el whisky y el azúcar; no hervir. Vierta en un vaso y cubra con crema; servir caliente.', '[{"name": "Irish whiskey", "image": "https://www.thecocktaildb.com/images/ingredients/Irish%20whiskey-small.png", "measure": "1 1/2 oz"}, {"name": "Coffee", "image": "https://www.thecocktaildb.com/images/ingredients/Coffee-small.png", "measure": "8 oz"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "1 tsp"}, {"name": "Whipped cream", "image": "https://www.thecocktaildb.com/images/ingredients/Whipped%20cream-small.png", "measure": "1 tblsp"}]'::jsonb),
  ('14029', '57 Chevy with a White License Plate', 'Cocktail', true, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/qyyvtu1468878544.jpg', NULL, '1. Fill a rocks glass with ice 2.add white creme de cacao and vodka 3.stir', '1. Llenar un vaso con hielo 2.Añadir crema de cacao blanco y vodka 3.Remover', '[{"name": "Creme de Cacao", "image": "https://www.thecocktaildb.com/images/ingredients/Creme%20de%20Cacao-small.png", "measure": "1 oz white"}, {"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "1 oz"}]'::jsonb),
  ('14065', 'Zippy''s Revenge', 'Cocktail', true, 'Old-fashioned glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/1sqm7n1485620312.jpg', NULL, 'Mix Kool-Aid to taste then add Rum and ammaretto. shake well to disolve the sugar in the Kool-Aid... serve cold', 'Mezclar Kool-Aid al gusto y añadir el ron y el ammaretto. agitar bien para disolver el azúcar en el Kool-Aid... servir frío', '[{"name": "Amaretto", "image": "https://www.thecocktaildb.com/images/ingredients/Amaretto-small.png", "measure": "2 oz"}, {"name": "Rum", "image": "https://www.thecocktaildb.com/images/ingredients/Rum-small.png", "measure": "2 oz"}, {"name": "Kool-Aid", "image": "https://www.thecocktaildb.com/images/ingredients/Kool-Aid-small.png", "measure": "4 oz Grape"}]'::jsonb),
  ('14087', 'Red Snapper', 'Shot', true, 'Old-fashioned glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/7p607y1504735343.jpg', NULL, 'One shot each, shake n shoot', 'Un disparo cada uno, agitar y disparar', '[{"name": "Crown Royal", "image": "https://www.thecocktaildb.com/images/ingredients/Crown%20Royal-small.png", "measure": "1 shot"}, {"name": "Amaretto", "image": "https://www.thecocktaildb.com/images/ingredients/Amaretto-small.png", "measure": "1 shot"}, {"name": "Cranberry juice", "image": "https://www.thecocktaildb.com/images/ingredients/Cranberry%20juice-small.png", "measure": "1 shot"}]'::jsonb),
  ('14095', 'Jamaica Kiss', 'Shake', true, 'Hurricane glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/urpvvv1441249549.jpg', NULL, 'Fill a tumbler with ice cubes. Add a shot of Tia Maria and a shot of Jamaican light rum. Fill the tumbler with milk. Blend until smooth and serve immediately.', 'Llena un vaso con cubitos de hielo. Agregue un trago de Tía María y un trago de ron ligero jamaicano. Llena el vaso con leche. Licue hasta que quede suave y sirva inmediatamente.', '[{"name": "Coffee liqueur", "image": "https://www.thecocktaildb.com/images/ingredients/Coffee%20liqueur-small.png", "measure": "1 shot"}, {"name": "Light rum", "image": "https://www.thecocktaildb.com/images/ingredients/Light%20rum-small.png", "measure": "1 shot Jamaican"}, {"name": "Ice", "image": "https://www.thecocktaildb.com/images/ingredients/Ice-small.png", "measure": "cubes"}, {"name": "Milk", "image": "https://www.thecocktaildb.com/images/ingredients/Milk-small.png", "measure": null}]'::jsonb),
  ('14157', 'Ziemes Martini Apfelsaft', 'Ordinary Drink', true, 'Collins Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/xnzr2p1485619687.jpg', NULL, 'Serve without ice. At least the juice shold have room temperature.', 'Servir sin hielo. Al menos el jugo debe tener temperatura ambiente.', '[{"name": "Vermouth", "image": "https://www.thecocktaildb.com/images/ingredients/Vermouth-small.png", "measure": "4 cl"}, {"name": "Apple juice", "image": "https://www.thecocktaildb.com/images/ingredients/Apple%20juice-small.png", "measure": "16 cl"}]'::jsonb),
  ('14167', 'Vodka Martini', 'Ordinary Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/qyxrqw1439906528.jpg', NULL, 'Shake the vodka and vermouth together with a number of ice cubes, strain into a cocktail glass, add the olive and serve.', 'Agitar el vodka y el vermú junto con unos cubitos de hielo, colar en una copa de cóctel, añadir la aceituna y servir.', '[{"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "1 1/2 oz"}, {"name": "Dry Vermouth", "image": "https://www.thecocktaildb.com/images/ingredients/Dry%20Vermouth-small.png", "measure": "3/4 oz"}, {"name": "Olive", "image": "https://www.thecocktaildb.com/images/ingredients/Olive-small.png", "measure": "1"}]'::jsonb),
  ('14181', 'Cafe Savoy', 'Coffee / Tea', true, 'Coffee mug', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/vqwptt1441247711.jpg', NULL, 'Fill mug almost to top with coffee.Add milk, triple sec and brandy. Stir.', 'Llene la taza casi hasta arriba con café. Agregue la leche, el triple seco y el brandy. Remover.', '[{"name": "Coffee", "image": "https://www.thecocktaildb.com/images/ingredients/Coffee-small.png", "measure": null}, {"name": "Milk", "image": "https://www.thecocktaildb.com/images/ingredients/Milk-small.png", "measure": "1/2 oz"}, {"name": "Triple sec", "image": "https://www.thecocktaildb.com/images/ingredients/Triple%20sec-small.png", "measure": "1/2 oz"}, {"name": "Brandy", "image": "https://www.thecocktaildb.com/images/ingredients/Brandy-small.png", "measure": null}]'::jsonb),
  ('14195', 'Snowball', 'Ordinary Drink', true, 'Highball glass', NULL, '{Christmas}'::text[], 'https://www.thecocktaildb.com/images/media/drink/7ibfs61504735416.jpg', NULL, 'Place one ice cube in the glass and add 1 1/2 oz of Advocaat. Fill up the glass with lemonade and decorate with a slice of lemon. Serve at once.', 'Coloque un cubito de hielo en el vaso y agregue 1 1/2 oz de Advocaat. Llena el vaso con limonada y decora con una rodaja de limón. Servir de inmediato.', '[{"name": "Advocaat", "image": "https://www.thecocktaildb.com/images/ingredients/Advocaat-small.png", "measure": "1 1/2 oz"}, {"name": "Lemonade", "image": "https://www.thecocktaildb.com/images/ingredients/Lemonade-small.png", "measure": "8-10 oz cold"}, {"name": "Lemon", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon-small.png", "measure": "1 slice"}, {"name": "Ice", "image": "https://www.thecocktaildb.com/images/ingredients/Ice-small.png", "measure": "cubes"}]'::jsonb),
  ('14209', 'Mocha-Berry', 'Coffee / Tea', true, 'Irish coffee cup', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/vtwyyx1441246448.jpg', NULL, 'pour 6 oz. of coffee in a mug or Irish coffee cup. add coca mix and chambord, mix well and top off with whipped cream.', 'vierta 6 oz. de café en una taza o taza de café irlandés. agregue la mezcla de coca y el chambord, mezcle bien y complete con crema batida.', '[{"name": "Coffee", "image": "https://www.thecocktaildb.com/images/ingredients/Coffee-small.png", "measure": "6 oz"}, {"name": "Chambord raspberry liqueur", "image": "https://www.thecocktaildb.com/images/ingredients/Chambord%20raspberry%20liqueur-small.png", "measure": "2 oz"}, {"name": "Cocoa powder", "image": "https://www.thecocktaildb.com/images/ingredients/Cocoa%20powder-small.png", "measure": "2 tblsp"}, {"name": "Whipped cream", "image": "https://www.thecocktaildb.com/images/ingredients/Whipped%20cream-small.png", "measure": null}]'::jsonb),
  ('14229', '747', 'Shot', true, 'Shot glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/xxsxqy1472668106.jpg', NULL, 'pour kaluha, then Baileys, then Frangelico not chilled and not layered -- SERVE!!!', 'vierta kaluha, luego Baileys, luego Frangelico no frío ni en capas - ¡¡¡SERVIR!!!', '[{"name": "Kahlua", "image": "https://www.thecocktaildb.com/images/ingredients/Kahlua-small.png", "measure": "1/3 part"}, {"name": "Baileys irish cream", "image": "https://www.thecocktaildb.com/images/ingredients/Baileys%20irish%20cream-small.png", "measure": "1/3 part"}, {"name": "Frangelico", "image": "https://www.thecocktaildb.com/images/ingredients/Frangelico-small.png", "measure": "1/3 part"}]'::jsonb),
  ('14366', 'Lemon Drop', 'Cocktail', true, 'Cocktail glass', NULL, '{IBA,NewEra}'::text[], 'https://www.thecocktaildb.com/images/media/drink/mtpxgk1504373297.jpg', NULL, 'Shake and strain into a chilled cocktail glass rimmed with sugar.', 'Agitar y colar en una copa de cóctel fría con borde de azúcar.', '[{"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "1 1/2 shot"}, {"name": "Cointreau", "image": "https://www.thecocktaildb.com/images/ingredients/Cointreau-small.png", "measure": "1 1/2 shot"}, {"name": "Lemon", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon-small.png", "measure": "Juice of 1 wedge"}]'::jsonb),
  ('14378', 'Lunch Box', 'Beer', true, 'Pint glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/qywpvt1454512546.jpg', NULL, 'Fill a pint glass almost full with beer. Then fill the rest with orange juice (careful not to fill it to the top). Then take the shot of Amaretto and drop it in.', 'Llene un vaso de pinta casi lleno con cerveza. Luego rellena el resto con zumo de naranja (con cuidado de no llenarlo hasta arriba). Luego toma la foto de Amaretto y colócala.', '[{"name": "Beer", "image": "https://www.thecocktaildb.com/images/ingredients/Beer-small.png", "measure": "3/4 bottle"}, {"name": "Amaretto", "image": "https://www.thecocktaildb.com/images/ingredients/Amaretto-small.png", "measure": "1 shot"}, {"name": "Orange juice", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20juice-small.png", "measure": "1 oz"}]'::jsonb),
  ('14446', 'Kool-Aid Slammer', 'Shot', true, 'Shot glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/kugu2m1504735473.jpg', NULL, 'Fill half the shot glass with the kool-aid first. Then put a paper towel over the top of the glass and slowly pour in the vodka. If you do it right, you should be able to see that the two liquids are separated, with the vodka on top. Now slam it! The last thing you''ll taste is the kool-aid.', 'Primero llena la mitad del vaso de chupito con kool-aid. Luego, coloca una toalla de papel sobre la parte superior del vaso y vierte lentamente el vodka. Si lo haces bien, deberías poder ver que los dos líquidos están separados, con el vodka encima. ¡Ahora golpéalo! Lo último que probarás es el kool-aid.', '[{"name": "Kool-Aid", "image": "https://www.thecocktaildb.com/images/ingredients/Kool-Aid-small.png", "measure": "1/2 oz Grape"}, {"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "1/2 oz"}]'::jsonb),
  ('14456', 'Kurant Tea', 'Coffee / Tea', true, 'Champagne flute', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/xrsrpr1441247464.jpg', NULL, 'Pour Absolut Kurant into a comfortably big tea-cup. Add the not too hot(!) apple tea and, if you like, some sugar. Enjoy!', 'Vierta Absolut Kurant en una taza de té cómodamente grande. Añade el té de manzana no demasiado caliente (!) y, si quieres, un poco de azúcar. ¡Disfrutar!', '[{"name": "Absolut Kurant", "image": "https://www.thecocktaildb.com/images/ingredients/Absolut%20Kurant-small.png", "measure": "4 cl"}, {"name": "Tea", "image": "https://www.thecocktaildb.com/images/ingredients/Tea-small.png", "measure": "Turkish apple"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "(if needed)"}]'::jsonb),
  ('14466', 'Dirty Nipple', 'Shot', true, 'Shot glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/vtyqrt1461866508.jpg', NULL, 'This is a layered shot - the Bailey''s must be on top', 'Esta es una toma en capas: Bailey''s debe estar en la cima.', '[{"name": "Kahlua", "image": "https://www.thecocktaildb.com/images/ingredients/Kahlua-small.png", "measure": null}, {"name": "Sambuca", "image": "https://www.thecocktaildb.com/images/ingredients/Sambuca-small.png", "measure": null}, {"name": "Baileys irish cream", "image": "https://www.thecocktaildb.com/images/ingredients/Baileys%20irish%20cream-small.png", "measure": null}]'::jsonb),
  ('14482', 'Darkwood Sling', 'Soft Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/sxxsyq1472719303.jpg', NULL, 'There are many good cherry liqueurs you can use, but I prefere Heering. Add one share of the liqueur. Then you add one share of Soda. For a sour sling use Tonic (most people prefer the drink without Tonic). Afterwards you fill the glass with Orange Juice and ice cubes.', 'Se pueden utilizar muchos licores de cereza buenos, pero yo prefiero el Heering. Añada una parte del licor. A continuación, añada una parte de soda. Para un sour sling utiliza Tónica (la mayoría de la gente prefiere la bebida sin Tónica). Después se llena el vaso con zumo de naranja y cubitos de hielo.', '[{"name": "Cherry Heering", "image": "https://www.thecocktaildb.com/images/ingredients/Cherry%20Heering-small.png", "measure": "1 part"}, {"name": "Soda water", "image": "https://www.thecocktaildb.com/images/ingredients/Soda%20water-small.png", "measure": "1 part"}, {"name": "Orange juice", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20juice-small.png", "measure": "1 part"}, {"name": "Ice", "image": "https://www.thecocktaildb.com/images/ingredients/Ice-small.png", "measure": "cubes"}]'::jsonb),
  ('14538', 'Bumble Bee', 'Shot', true, 'Shot glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/uwqpvv1461866378.jpg', NULL, 'This is a layered shot. First pour the Bailey''s into the shot glass. Then take an upside down spoon and touch it to the inside wall of the glass. Carefully add the Kahlua. Repeat this process for the Sambuca. If done properly, the alcohol will stay separated and resemble a bumble bee. Enjoy!!!', 'Esta es una toma en capas. Primero vierte el Bailey''s en el vaso de chupito. Luego toma una cuchara invertida y toca la pared interior del vaso. Agrega con cuidado el Kahlua. Repita este proceso para la Sambuca. Si se hace correctamente, el alcohol permanecerá separado y se parecerá a un abejorro. ¡¡¡Disfrutar!!!', '[{"name": "Baileys irish cream", "image": "https://www.thecocktaildb.com/images/ingredients/Baileys%20irish%20cream-small.png", "measure": "1/3 oz"}, {"name": "Kahlua", "image": "https://www.thecocktaildb.com/images/ingredients/Kahlua-small.png", "measure": "1/3 oz"}, {"name": "Sambuca", "image": "https://www.thecocktaildb.com/images/ingredients/Sambuca-small.png", "measure": "1/3 oz"}]'::jsonb),
  ('14586', 'Orange Push-up', 'Ordinary Drink', true, 'Hurricane glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/mgf0y91503565781.jpg', NULL, 'Combine liquors in a blender. Add a half scoop of ice and blend. Garnish with an orange and cherry flag. So good it will melt in your mouth!!!', 'Combine los licores en una licuadora. Añade media bola de hielo y licúa. Adorne con una bandera de naranja y cereza. ¡¡¡Tan rico que se deshará en tu boca!!!', '[{"name": "Spiced rum", "image": "https://www.thecocktaildb.com/images/ingredients/Spiced%20rum-small.png", "measure": "1.5 oz"}, {"name": "Grenadine", "image": "https://www.thecocktaildb.com/images/ingredients/Grenadine-small.png", "measure": "0.5 oz"}, {"name": "Orange juice", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20juice-small.png", "measure": "4 oz"}, {"name": "Sour mix", "image": "https://www.thecocktaildb.com/images/ingredients/Sour%20mix-small.png", "measure": "1 splash"}]'::jsonb),
  ('14588', '151 Florida Bushwacker', 'Shake', true, 'Beer mug', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/rvwrvv1468877323.jpg', NULL, 'Combine all ingredients. Blend until smooth. Garnish with chocolate shavings if desired.', 'Combina todos los ingredientes. Licue hasta que quede suave. Adorne con virutas de chocolate si lo desea.', '[{"name": "Malibu rum", "image": "https://www.thecocktaildb.com/images/ingredients/Malibu%20rum-small.png", "measure": "1/2 oz"}, {"name": "Light rum", "image": "https://www.thecocktaildb.com/images/ingredients/Light%20rum-small.png", "measure": "1/2 oz"}, {"name": "151 proof rum", "image": "https://www.thecocktaildb.com/images/ingredients/151%20proof%20rum-small.png", "measure": "1/2 oz Bacardi"}, {"name": "Dark Creme de Cacao", "image": "https://www.thecocktaildb.com/images/ingredients/Dark%20Creme%20de%20Cacao-small.png", "measure": "1 oz"}, {"name": "Cointreau", "image": "https://www.thecocktaildb.com/images/ingredients/Cointreau-small.png", "measure": "1 oz"}, {"name": "Milk", "image": "https://www.thecocktaildb.com/images/ingredients/Milk-small.png", "measure": "3 oz"}, {"name": "Coconut liqueur", "image": "https://www.thecocktaildb.com/images/ingredients/Coconut%20liqueur-small.png", "measure": "1 oz"}, {"name": "Vanilla ice-cream", "image": "https://www.thecocktaildb.com/images/ingredients/Vanilla%20ice-cream-small.png", "measure": "1 cup"}]'::jsonb),
  ('14594', 'Zizi Coin-coin', 'Punch / Party Drink', true, 'Margarita/Coupette glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/0fbo2t1485620752.jpg', NULL, 'Pour 5cl of Cointreau on ice, add 2cl of fresh lemon (or lime) juice, stir gently, and finally add slices of lemon/lime in glass.', 'Vierta 5 cl de Cointreau sobre hielo, añada 2 cl de zumo de limón (o lima) fresco, remueva suavemente y, por último, añada rodajas de limón/lima en el vaso.', '[{"name": "Cointreau", "image": "https://www.thecocktaildb.com/images/ingredients/Cointreau-small.png", "measure": "5 cl"}, {"name": "Lemon juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20juice-small.png", "measure": "2 cl"}, {"name": "Ice", "image": "https://www.thecocktaildb.com/images/ingredients/Ice-small.png", "measure": "cubes"}, {"name": "Lemon", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon-small.png", "measure": "or lime"}]'::jsonb),
  ('14598', '50/50', 'Ordinary Drink', true, 'Collins Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/wwpyvr1461919316.jpg', NULL, 'fill glass with crushed ice. Add vodka. Add a splash of grand-marnier. Fill with o.j.', 'Llenar el vaso con hielo picado. Añada el vodka. Añada un chorrito de grand-marnier. Rellenar con O.J.', '[{"name": "Vanilla vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vanilla%20vodka-small.png", "measure": "2 1/2 oz"}, {"name": "Grand Marnier", "image": "https://www.thecocktaildb.com/images/ingredients/Grand%20Marnier-small.png", "measure": "1 splash"}, {"name": "Orange juice", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20juice-small.png", "measure": "Fill with"}]'::jsonb),
  ('14602', 'Tequila Surprise', 'Shot', true, 'Shot glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/8189p51504735581.jpg', NULL, 'Fill shot glass with Tequila. Add drops of Tobasco sauce.', 'Llene el vaso de chupito con Tequila. Agrega gotas de salsa Tabasco.', '[{"name": "Tequila", "image": "https://www.thecocktaildb.com/images/ingredients/Tequila-small.png", "measure": "full glass"}, {"name": "Tabasco sauce", "image": "https://www.thecocktaildb.com/images/ingredients/Tabasco%20sauce-small.png", "measure": "About 8 drops"}]'::jsonb),
  ('14608', 'Cream Soda', 'Cocktail', true, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/yqstxr1479209367.jpg', NULL, 'Pour 1oz of Spiced Rum into a highball glass with ice. Fill with Ginger Ale.', 'Vierta 1 onza de ron especiado en un vaso highball con hielo. Rellenar con Ginger Ale.', '[{"name": "Spiced rum", "image": "https://www.thecocktaildb.com/images/ingredients/Spiced%20rum-small.png", "measure": "1 oz"}, {"name": "Ginger ale", "image": "https://www.thecocktaildb.com/images/ingredients/Ginger%20ale-small.png", "measure": null}]'::jsonb),
  ('14610', 'ACID', 'Shot', true, 'Shot glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/xuxpxt1479209317.jpg', NULL, 'Poor in the 151 first followed by the 101 served with a Coke or Dr Pepper chaser.', 'Vierta primero el Bacardi 151, seguido del Wild Turkey 101 y sirva con Coca-Cola o Dr Pepper.', '[{"name": "151 proof rum", "image": "https://www.thecocktaildb.com/images/ingredients/151%20proof%20rum-small.png", "measure": "1 oz Bacardi"}, {"name": "Wild Turkey", "image": "https://www.thecocktaildb.com/images/ingredients/Wild%20Turkey-small.png", "measure": "1 oz"}]'::jsonb),
  ('14642', 'Grim Reaper', 'Ordinary Drink', true, 'Old-fashioned glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/kztu161504883192.jpg', NULL, 'Mix Kahlua and 151 in glass. Quickly add ice and pour grenadine over ice to give ice red tint.', 'Mezclar Kahlua y 151 en el vaso. Añada hielo rápidamente y vierta granadina sobre el hielo para darle un tinte rojo.', '[{"name": "Kahlua", "image": "https://www.thecocktaildb.com/images/ingredients/Kahlua-small.png", "measure": "1 oz"}, {"name": "151 proof rum", "image": "https://www.thecocktaildb.com/images/ingredients/151%20proof%20rum-small.png", "measure": "1 oz Bacardi"}, {"name": "Grenadine", "image": "https://www.thecocktaildb.com/images/ingredients/Grenadine-small.png", "measure": "1 dash"}]'::jsonb),
  ('14688', 'Freddy Kruger', 'Shot', true, 'Shot glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/tuppuq1461866798.jpg', NULL, 'make it an ample size shot!!', '¡¡Hazlo en una toma de tamaño amplio!!', '[{"name": "Jägermeister", "image": "https://www.thecocktaildb.com/images/ingredients/J%C3%A4germeister-small.png", "measure": "1/2 oz"}, {"name": "Sambuca", "image": "https://www.thecocktaildb.com/images/ingredients/Sambuca-small.png", "measure": "1/2 oz"}, {"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "1/2 oz"}]'::jsonb),
  ('14730', 'Bubble Gum', 'Shot', true, 'Shot glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/spuurv1468878783.jpg', NULL, 'Layer in order into a shot glass.', 'Coloque en capas en orden en un vaso de chupito.', '[{"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "1/4"}, {"name": "Banana liqueur", "image": "https://www.thecocktaildb.com/images/ingredients/Banana%20liqueur-small.png", "measure": "1/4"}, {"name": "Orange juice", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20juice-small.png", "measure": "1/4"}, {"name": "Peach schnapps", "image": "https://www.thecocktaildb.com/images/ingredients/Peach%20schnapps-small.png", "measure": "1/4"}]'::jsonb),
  ('14752', 'Kiwi Lemon', 'Ordinary Drink', true, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/tpupvr1478251697.jpg', NULL, 'Mix in highball glass. Stirr. Garnish with slice of kiwi.', 'Mezclar en un vaso highball. Remover. Decorar con una rodaja de kiwi.', '[{"name": "Kiwi liqueur", "image": "https://www.thecocktaildb.com/images/ingredients/Kiwi%20liqueur-small.png", "measure": "1 part"}, {"name": "Bitter lemon", "image": "https://www.thecocktaildb.com/images/ingredients/Bitter%20lemon-small.png", "measure": "2 parts"}, {"name": "Ice", "image": "https://www.thecocktaildb.com/images/ingredients/Ice-small.png", "measure": "cubes"}]'::jsonb),
  ('14782', 'Hot Creamy Bush', 'Coffee / Tea', true, 'Irish coffee cup', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/spvrtp1472668037.jpg', NULL, 'Combine all ingredients in glass', 'Combina todos los ingredientes en un vaso.', '[{"name": "Irish whiskey", "image": "https://www.thecocktaildb.com/images/ingredients/Irish%20whiskey-small.png", "measure": "1 shot"}, {"name": "Baileys irish cream", "image": "https://www.thecocktaildb.com/images/ingredients/Baileys%20irish%20cream-small.png", "measure": "3/4 shot"}, {"name": "Coffee", "image": "https://www.thecocktaildb.com/images/ingredients/Coffee-small.png", "measure": "6 oz hot"}]'::jsonb),
  ('14842', 'Midnight Mint', 'Cocktail', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/svuvrq1441208310.jpg', NULL, 'If available, rim cocktail (Martini) glass with sugar syrup then dip into chocolate flakes or powder. Add ingredients into shaker with ice. Shake well then strain into cocktail glass.', 'Si se dispone de ella, poner el borde de la copa de cóctel (Martini) con sirope de azúcar y luego sumergirlo en copos o polvo de chocolate. Añada los ingredientes a la coctelera con hielo. Agitar bien y colar en una copa de cóctel.', '[{"name": "Baileys irish cream", "image": "https://www.thecocktaildb.com/images/ingredients/Baileys%20irish%20cream-small.png", "measure": "1 oz"}, {"name": "White Creme de Menthe", "image": "https://www.thecocktaildb.com/images/ingredients/White%20Creme%20de%20Menthe-small.png", "measure": "3/4 oz"}, {"name": "Cream", "image": "https://www.thecocktaildb.com/images/ingredients/Cream-small.png", "measure": "3/4 oz double"}]'::jsonb),
  ('14860', 'Talos Coffee', 'Coffee / Tea', true, 'Brandy snifter', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/rswqpy1441246518.jpg', NULL, 'Add your GM and then add your coffee.', 'Agrega tu GM y luego agrega tu café.', '[{"name": "Grand Marnier", "image": "https://www.thecocktaildb.com/images/ingredients/Grand%20Marnier-small.png", "measure": "3 parts"}, {"name": "Coffee", "image": "https://www.thecocktaildb.com/images/ingredients/Coffee-small.png", "measure": "1 part"}]'::jsonb),
  ('14888', 'Zinger', 'Soft Drink', true, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/iixv4l1485620014.jpg', NULL, 'Get a shot glass and pour in three shots of the schnapps. Do the same with the Surge Cola. Then down it like Scheetz would.', 'Consigue un vaso de chupito y vierte tres tragos de aguardiente. Haz lo mismo con Surge Cola. Luego bájelo como lo haría Scheetz.', '[{"name": "Peachtree schnapps", "image": "https://www.thecocktaildb.com/images/ingredients/Peachtree%20schnapps-small.png", "measure": "4 shots"}, {"name": "Surge", "image": "https://www.thecocktaildb.com/images/ingredients/Surge-small.png", "measure": "4 shots"}]'::jsonb),
  ('14956', 'Jello shots', 'Shot', true, 'Shot glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/l0smzo1504884904.jpg', NULL, 'Boil 3 cups of water then add jello. Mix jello and water until jello is completely disolved. Add the two cups of vodka and mix together. Pour mixture into plastic shot glasses and chill until firm. Then, eat away...', 'Hervir 3 tazas de agua y luego agregar gelatina. Mezcla la gelatina y el agua hasta que la gelatina se disuelva por completo. Agrega las dos tazas de vodka y mezcla. Vierta la mezcla en vasos de plástico y enfríe hasta que esté firme. Luego, come...', '[{"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "2 cups"}, {"name": "Jello", "image": "https://www.thecocktaildb.com/images/ingredients/Jello-small.png", "measure": "3 packages"}, {"name": "Water", "image": "https://www.thecocktaildb.com/images/ingredients/Water-small.png", "measure": "3 cups"}]'::jsonb),
  ('14978', 'Rum Punch', 'Punch / Party Drink', true, 'Punch bowl', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/wyrsxu1441554538.jpg', NULL, 'Mix all ingredients in a punch bowl and serve.', 'Mezclar todos los ingredientes en una ponchera y servir.', '[{"name": "Rum", "image": "https://www.thecocktaildb.com/images/ingredients/Rum-small.png", "measure": "mikey bottle"}, {"name": "Ginger ale", "image": "https://www.thecocktaildb.com/images/ingredients/Ginger%20ale-small.png", "measure": "large bottle"}, {"name": "Fruit punch", "image": "https://www.thecocktaildb.com/images/ingredients/Fruit%20punch-small.png", "measure": "355 ml frozen"}, {"name": "Orange juice", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20juice-small.png", "measure": "355 ml frozen"}, {"name": "Ice", "image": "https://www.thecocktaildb.com/images/ingredients/Ice-small.png", "measure": "crushed"}]'::jsonb),
  ('15006', 'Turkeyball', 'Shot', true, 'Shot glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/rxurpr1441554292.jpg', NULL, 'Shake with ice and strain into a shot glass.', 'Agitar con hielo y colar en un vaso de chupito.', '[{"name": "Wild Turkey", "image": "https://www.thecocktaildb.com/images/ingredients/Wild%20Turkey-small.png", "measure": "1 oz"}, {"name": "Amaretto", "image": "https://www.thecocktaildb.com/images/ingredients/Amaretto-small.png", "measure": "3/4 oz"}, {"name": "Pineapple juice", "image": "https://www.thecocktaildb.com/images/ingredients/Pineapple%20juice-small.png", "measure": "1 splash"}]'::jsonb),
  ('15026', 'Kiss me Quick', 'Ordinary Drink', true, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/m7iaxu1504885119.jpg', NULL, 'mix in the glass', 'mezclar en el vaso', '[{"name": "Cranberry vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Cranberry%20vodka-small.png", "measure": "4 cl"}, {"name": "Apfelkorn", "image": "https://www.thecocktaildb.com/images/ingredients/Apfelkorn-small.png", "measure": "2 cl"}, {"name": "Schweppes Russchian", "image": "https://www.thecocktaildb.com/images/ingredients/Schweppes%20Russchian-small.png", "measure": "7 cl"}, {"name": "Apple juice", "image": "https://www.thecocktaildb.com/images/ingredients/Apple%20juice-small.png", "measure": "8 cl"}, {"name": "Ice", "image": "https://www.thecocktaildb.com/images/ingredients/Ice-small.png", "measure": "cubes"}]'::jsonb),
  ('15082', 'Royal Flush', 'Shot', true, 'Old-fashioned glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/7rnm8u1504888527.jpg', NULL, 'Pour all the ingredients into tumbler over ice. Strain into glass.', 'Vierta todos los ingredientes en un vaso con hielo. Colar en un vaso.', '[{"name": "Crown Royal", "image": "https://www.thecocktaildb.com/images/ingredients/Crown%20Royal-small.png", "measure": "1 1/2 oz"}, {"name": "Peach schnapps", "image": "https://www.thecocktaildb.com/images/ingredients/Peach%20schnapps-small.png", "measure": "1 oz"}, {"name": "Chambord raspberry liqueur", "image": "https://www.thecocktaildb.com/images/ingredients/Chambord%20raspberry%20liqueur-small.png", "measure": "1/2 oz"}, {"name": "Cranberry juice", "image": "https://www.thecocktaildb.com/images/ingredients/Cranberry%20juice-small.png", "measure": "1 oz"}]'::jsonb),
  ('15086', 'Limona Corona', 'Beer', true, 'Beer Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/wwqrsw1441248662.jpg', NULL, 'Open the Corona. Fill the empty space in the neck in the bottle with the rum. The bottle should be filled to the top. Plug the bottle with your thumb or the palm of your hand. Turn the bottle upside-down so the rum and beer mix. Turn the bottle rightside-up, unplug, and drink.', 'Abre la Corona. Llena el espacio vacío en el cuello de la botella con ron. La botella debe llenarse hasta arriba. Tape la botella con el pulgar o la palma de la mano. Dale la vuelta a la botella para que el ron y la cerveza se mezclen. Gire la botella hacia arriba, desenchúfela y beba.', '[{"name": "Corona", "image": "https://www.thecocktaildb.com/images/ingredients/Corona-small.png", "measure": "1 bottle"}, {"name": "Bacardi Limon", "image": "https://www.thecocktaildb.com/images/ingredients/Bacardi%20Limon-small.png", "measure": "1 oz"}]'::jsonb),
  ('15092', 'Pysch Vitamin Light', 'Ordinary Drink', false, 'Collins Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/xsqsxw1441553580.jpg', NULL, 'Shake with ice.', 'Agitar con hielo.', '[{"name": "Orange juice", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20juice-small.png", "measure": "1 part"}, {"name": "Apple juice", "image": "https://www.thecocktaildb.com/images/ingredients/Apple%20juice-small.png", "measure": "1 part"}, {"name": "Pineapple juice", "image": "https://www.thecocktaildb.com/images/ingredients/Pineapple%20juice-small.png", "measure": "1 part"}, {"name": "Ice", "image": "https://www.thecocktaildb.com/images/ingredients/Ice-small.png", "measure": null}]'::jsonb),
  ('15106', 'Apello', 'Other / Unknown', false, 'Collins Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/uptxtv1468876415.jpg', NULL, 'Stirr. Grnish with maraschino cherry.', 'Revuelva. Grnish con cereza al marrasquino.', '[{"name": "Orange juice", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20juice-small.png", "measure": "4 cl"}, {"name": "Grapefruit juice", "image": "https://www.thecocktaildb.com/images/ingredients/Grapefruit%20juice-small.png", "measure": "3 cl"}, {"name": "Apple juice", "image": "https://www.thecocktaildb.com/images/ingredients/Apple%20juice-small.png", "measure": "1 cl"}, {"name": "Maraschino cherry", "image": "https://www.thecocktaildb.com/images/ingredients/Maraschino%20cherry-small.png", "measure": "1"}]'::jsonb),
  ('15178', 'Texas Rattlesnake', 'Shot', true, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/rtohqp1504889750.jpg', NULL, 'Mix all ingredients and Shake well. Sweet at first, with a BITE at the end...', 'Mezclar todos los ingredientes y agitar bien. Dulce al principio, con un MORDIDO al final...', '[{"name": "Yukon Jack", "image": "https://www.thecocktaildb.com/images/ingredients/Yukon%20Jack-small.png", "measure": "1 part"}, {"name": "Cherry brandy", "image": "https://www.thecocktaildb.com/images/ingredients/Cherry%20brandy-small.png", "measure": "1/2 part"}, {"name": "Southern Comfort", "image": "https://www.thecocktaildb.com/images/ingredients/Southern%20Comfort-small.png", "measure": "1 part"}, {"name": "Sweet and sour", "image": "https://www.thecocktaildb.com/images/ingredients/Sweet%20and%20sour-small.png", "measure": "1 splash"}]'::jsonb),
  ('15184', 'San Francisco', 'Ordinary Drink', true, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/szmj2d1504889961.jpg', NULL, 'Take a tall glass and put in a few ice cubes, fill the vodka over it and fill with juice then the "creme", to end fill in the grenadine but very carefully at the side of the glass so it will lay down in the bottom. garnish with orange and strawberry.', 'Coge un vaso alto y ponle unos cubitos de hielo, llena el vodka encima y rellena con jugo luego la "crema", para finalizar rellena con la granadina pero con mucho cuidado por los lados del vaso para que se quede en el fondo. decorar con naranja y fresa.', '[{"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "2 cl"}, {"name": "Creme de Banane", "image": "https://www.thecocktaildb.com/images/ingredients/Creme%20de%20Banane-small.png", "measure": "2 cl"}, {"name": "Grenadine", "image": "https://www.thecocktaildb.com/images/ingredients/Grenadine-small.png", "measure": null}, {"name": "Orange juice", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20juice-small.png", "measure": null}]'::jsonb),
  ('15226', 'Space Odyssey', 'Ordinary Drink', true, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/vxtjbx1504817842.jpg', NULL, 'Fill glass with ice and add shots of Bacardi and Malibu. Add splash of pineapple juice and top with orange juice. Add grenadine for color and garnish with cherries.', 'Llene el vaso con hielo y agregue tragos de Bacardi y Malibu. Agrega un chorrito de jugo de piña y cubre con jugo de naranja. Agregue granadina para darle color y decore con cerezas.', '[{"name": "151 proof rum", "image": "https://www.thecocktaildb.com/images/ingredients/151%20proof%20rum-small.png", "measure": "1 shot Bacardi"}, {"name": "Malibu rum", "image": "https://www.thecocktaildb.com/images/ingredients/Malibu%20rum-small.png", "measure": "1 shot"}, {"name": "Pineapple juice", "image": "https://www.thecocktaildb.com/images/ingredients/Pineapple%20juice-small.png", "measure": "1 shot"}, {"name": "Orange juice", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20juice-small.png", "measure": null}, {"name": "Grenadine", "image": "https://www.thecocktaildb.com/images/ingredients/Grenadine-small.png", "measure": null}, {"name": "Cherries", "image": "https://www.thecocktaildb.com/images/ingredients/Cherries-small.png", "measure": null}]'::jsonb),
  ('15254', 'Zenmeister', 'Ordinary Drink', true, 'Collins Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/qyuvsu1479209462.jpg', NULL, 'Mix together and enjoy', 'Mezclar y disfrutar', '[{"name": "Jägermeister", "image": "https://www.thecocktaildb.com/images/ingredients/J%C3%A4germeister-small.png", "measure": "1/2 oz"}, {"name": "Root beer", "image": "https://www.thecocktaildb.com/images/ingredients/Root%20beer-small.png", "measure": "1/2 oz"}]'::jsonb),
  ('15266', 'Avalon', 'Ordinary Drink', true, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/3k9qic1493068931.jpg', NULL, 'Fill a tall glass with ice. Layer the Finlandia Vodka, lemon and apple juices, Pisang Ambon, and top up with lemonade. Stir slightly and garnish with a spiralled cucumber skin and a red cherry. The cucumber provides zest and looks attractive. This drink, created by Timo Haimi, took first prize in the 1991 Finlandia Vodka Long Drink Competition.', 'Llene un vaso alto con hielo. Añadir el Finlandia Vodka, los zumos de limón y manzana, el Pisang Ambon y completar con limonada. Remover ligeramente y decorar con una piel de pepino en espiral y una cereza roja. El pepino aporta sabor y un aspecto atractivo. Esta bebida, creada por Timo Haimi, obtuvo el primer premio en el Concurso de Tragos Largos con Vodka Finlandia de 1991.', '[{"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "3 parts"}, {"name": "Pisang Ambon", "image": "https://www.thecocktaildb.com/images/ingredients/Pisang%20Ambon-small.png", "measure": "1 part"}, {"name": "Apple juice", "image": "https://www.thecocktaildb.com/images/ingredients/Apple%20juice-small.png", "measure": "6 parts"}, {"name": "Lemon juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20juice-small.png", "measure": "1 1/2 part"}, {"name": "Lemonade", "image": "https://www.thecocktaildb.com/images/ingredients/Lemonade-small.png", "measure": null}]'::jsonb),
  ('15288', '252', 'Shot', true, 'Shot glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/rtpxqw1468877562.jpg', NULL, 'Add both ingredients to shot glass, shoot, and get drunk quick', 'Agrega ambos ingredientes al vaso de chupito, dispara y emborrachate rápidamente.', '[{"name": "151 proof rum", "image": "https://www.thecocktaildb.com/images/ingredients/151%20proof%20rum-small.png", "measure": "1/2 shot Bacardi"}, {"name": "Wild Turkey", "image": "https://www.thecocktaildb.com/images/ingredients/Wild%20Turkey-small.png", "measure": "1/2 shot"}]'::jsonb),
  ('15300', '3-Mile Long Island Iced Tea', 'Ordinary Drink', true, 'Collins Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/rrtssw1472668972.jpg', NULL, 'Fill 14oz glass with ice and alcohol. Fill 2/3 glass with cola and remainder with sweet & sour. Top with dash of bitters and lemon wedge.', 'Llene un vaso de 14 onzas con hielo y alcohol. Llene 2/3 del vaso con cola y el resto con agridulce. Añadir un chorrito de amargo y una rodaja de limón.', '[{"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "1/2 oz"}, {"name": "Light rum", "image": "https://www.thecocktaildb.com/images/ingredients/Light%20rum-small.png", "measure": "1/2 oz"}, {"name": "Tequila", "image": "https://www.thecocktaildb.com/images/ingredients/Tequila-small.png", "measure": "1/2 oz"}, {"name": "Triple sec", "image": "https://www.thecocktaildb.com/images/ingredients/Triple%20sec-small.png", "measure": "1/2 oz"}, {"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "1/2 oz"}, {"name": "Coca-Cola", "image": "https://www.thecocktaildb.com/images/ingredients/Coca-Cola-small.png", "measure": "1/2 oz"}, {"name": "Sweet and sour", "image": "https://www.thecocktaildb.com/images/ingredients/Sweet%20and%20sour-small.png", "measure": "1-2 dash"}, {"name": "Bitters", "image": "https://www.thecocktaildb.com/images/ingredients/Bitters-small.png", "measure": "1 wedge"}, {"name": "Lemon", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon-small.png", "measure": "Garnish with"}]'::jsonb),
  ('15328', 'Zorro', 'Coffee / Tea', true, 'Coffee Mug', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/kvvd4z1485621283.jpg', NULL, 'add all and pour black coffee and add whipped cream on top.', 'agrega todo y vierte el café negro y agrega la crema batida encima.', '[{"name": "Sambuca", "image": "https://www.thecocktaildb.com/images/ingredients/Sambuca-small.png", "measure": "2 cl"}, {"name": "Baileys irish cream", "image": "https://www.thecocktaildb.com/images/ingredients/Baileys%20irish%20cream-small.png", "measure": "2 cl"}, {"name": "White Creme de Menthe", "image": "https://www.thecocktaildb.com/images/ingredients/White%20Creme%20de%20Menthe-small.png", "measure": "2 cl"}]'::jsonb),
  ('15330', 'Orange Crush', 'Shot', true, 'Shot glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/zvoics1504885926.jpg', NULL, 'Add all ingredients to tumbler-Pour as shot', 'Agregue todos los ingredientes al vaso. Vierta como trago.', '[{"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "1 oz"}, {"name": "Triple sec", "image": "https://www.thecocktaildb.com/images/ingredients/Triple%20sec-small.png", "measure": "1 oz"}, {"name": "Orange juice", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20juice-small.png", "measure": "1 oz"}]'::jsonb),
  ('15346', '155 Belmont', 'Cocktail', true, 'White wine glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/yqvvqs1475667388.jpg', NULL, 'Blend with ice. Serve in a wine glass. Garnish with carrot.', 'Mezclar con hielo. Sírvalo en una copa de vino. Decorar con zanahoria.', '[{"name": "Dark rum", "image": "https://www.thecocktaildb.com/images/ingredients/Dark%20rum-small.png", "measure": "1 shot"}, {"name": "Light rum", "image": "https://www.thecocktaildb.com/images/ingredients/Light%20rum-small.png", "measure": "2 shots"}, {"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "1 shot"}, {"name": "Orange juice", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20juice-small.png", "measure": "1 shot"}]'::jsonb),
  ('15403', 'Vodka Russian', 'Ordinary Drink', true, 'Collins Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/rpttur1454515129.jpg', NULL, 'Mix it as a ordinary drink .', 'Mézclalo como una bebida normal .', '[{"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "2 oz"}, {"name": "Schweppes Russchian", "image": "https://www.thecocktaildb.com/images/ingredients/Schweppes%20Russchian-small.png", "measure": null}]'::jsonb),
  ('15409', 'Danbooka', 'Coffee / Tea', true, 'Coffee Mug', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/vurrxr1441246074.jpg', NULL, 'pour it in and mix it.', 'viértalo y mézclelo.', '[{"name": "Coffee", "image": "https://www.thecocktaildb.com/images/ingredients/Coffee-small.png", "measure": "3 parts"}, {"name": "Everclear", "image": "https://www.thecocktaildb.com/images/ingredients/Everclear-small.png", "measure": "1 part"}]'::jsonb),
  ('15423', '110 in the shade', 'Beer', true, 'Beer Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/xxyywq1454511117.jpg', NULL, 'Drop shooter in glass. Fill with beer', 'Lanza el tirador en el vidrio. llenar con cerveza', '[{"name": "Lager", "image": "https://www.thecocktaildb.com/images/ingredients/Lager-small.png", "measure": "16 oz"}, {"name": "Tequila", "image": "https://www.thecocktaildb.com/images/ingredients/Tequila-small.png", "measure": "1.5 oz"}]'::jsonb),
  ('15427', 'Grand Blue', 'Ordinary Drink', true, 'Old-fashioned glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/vsrsqu1472761749.jpg', NULL, 'Serve in an old fashioned glass.', 'Servir en un vaso old fashioned.', '[{"name": "Malibu rum", "image": "https://www.thecocktaildb.com/images/ingredients/Malibu%20rum-small.png", "measure": "1 1/2 cl"}, {"name": "Peach schnapps", "image": "https://www.thecocktaildb.com/images/ingredients/Peach%20schnapps-small.png", "measure": "1 1/2 cl"}, {"name": "Blue Curacao", "image": "https://www.thecocktaildb.com/images/ingredients/Blue%20Curacao-small.png", "measure": "1 1/2 cl"}, {"name": "Sweet and sour", "image": "https://www.thecocktaildb.com/images/ingredients/Sweet%20and%20sour-small.png", "measure": "3 cl"}]'::jsonb),
  ('15515', 'Tennesee Mud', 'Coffee / Tea', true, 'Coffee Mug', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/txruqv1441245770.jpg', NULL, 'Mix Coffee, Jack Daniels and Amaretto. Add Cream on top.', 'Agitar, colar, levantar, copa de cóctel.', '[{"name": "Coffee", "image": "https://www.thecocktaildb.com/images/ingredients/Coffee-small.png", "measure": "8 oz"}, {"name": "Jack Daniels", "image": "https://www.thecocktaildb.com/images/ingredients/Jack%20Daniels-small.png", "measure": "4 oz"}, {"name": "Amaretto", "image": "https://www.thecocktaildb.com/images/ingredients/Amaretto-small.png", "measure": "4 oz"}, {"name": "Whipped cream", "image": "https://www.thecocktaildb.com/images/ingredients/Whipped%20cream-small.png", "measure": null}]'::jsonb),
  ('15639', 'Texas Sling', 'Shake', true, 'Wine Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/ypl13s1504890158.jpg', NULL, 'Blend with Ice until smooth. Serve in a tulip glass, top with whip cream.', 'Licue con hielo hasta que quede suave. Sirva en una copa tulipán y cubra con crema batida.', '[{"name": "Kahlua", "image": "https://www.thecocktaildb.com/images/ingredients/Kahlua-small.png", "measure": "1/2 oz"}, {"name": "Irish cream", "image": "https://www.thecocktaildb.com/images/ingredients/Irish%20cream-small.png", "measure": "1/2 oz"}, {"name": "Amaretto", "image": "https://www.thecocktaildb.com/images/ingredients/Amaretto-small.png", "measure": "1/2 oz"}, {"name": "151 proof rum", "image": "https://www.thecocktaildb.com/images/ingredients/151%20proof%20rum-small.png", "measure": "1/2 oz Bacardi"}, {"name": "Cream", "image": "https://www.thecocktaildb.com/images/ingredients/Cream-small.png", "measure": "1 oz"}]'::jsonb),
  ('15691', 'Zoksel', 'Soft Drink', true, 'Beer pilsner', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/ft8ed01485620930.jpg', NULL, 'No specific mixing instructions, just poor every ingredient in one glass. The lemon goes with it.', 'No hay instrucciones de mezcla específicas, simplemente mezcla cada ingrediente en un vaso. El limón va con él.', '[{"name": "Beer", "image": "https://www.thecocktaildb.com/images/ingredients/Beer-small.png", "measure": null}, {"name": "Root beer", "image": "https://www.thecocktaildb.com/images/ingredients/Root%20beer-small.png", "measure": null}, {"name": "Lemonade", "image": "https://www.thecocktaildb.com/images/ingredients/Lemonade-small.png", "measure": null}, {"name": "Coca-Cola", "image": "https://www.thecocktaildb.com/images/ingredients/Coca-Cola-small.png", "measure": "slice"}, {"name": "7-Up", "image": "https://www.thecocktaildb.com/images/ingredients/7-Up-small.png", "measure": null}, {"name": "Creme de Cassis", "image": "https://www.thecocktaildb.com/images/ingredients/Creme%20de%20Cassis-small.png", "measure": null}, {"name": "Lemon", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon-small.png", "measure": null}]'::jsonb),
  ('15743', 'Fuzzy Asshole', 'Coffee / Tea', true, 'Coffee mug', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/wrvpuu1472667898.jpg', NULL, 'fill coffe mug half full of coffee. Fill the other half full of Peach Schnapps. Stir and drink while hot.', 'llene la taza de café hasta la mitad con café. Llene la otra mitad con Peach Schnapps. Revuelva y beba mientras esté caliente.', '[{"name": "Coffee", "image": "https://www.thecocktaildb.com/images/ingredients/Coffee-small.png", "measure": "1/2"}, {"name": "Peach schnapps", "image": "https://www.thecocktaildb.com/images/ingredients/Peach%20schnapps-small.png", "measure": "1/2"}]'::jsonb),
  ('15761', 'Quick-sand', 'Ordinary Drink', true, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/vprxqv1478963533.jpg', NULL, 'Simply add the orange juice, quite a quick pour in order to mix the sambucca with the orange juice. The juice MUST have fruit pulp!', 'Basta con añadir el zumo de naranja, vertiendo bastante rápido para mezclar la sambucca con el zumo de naranja. ¡El zumo DEBE tener pulpa de fruta!', '[{"name": "Black Sambuca", "image": "https://www.thecocktaildb.com/images/ingredients/Black%20Sambuca-small.png", "measure": "25 ml"}, {"name": "Orange juice", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20juice-small.png", "measure": "Add 250 ml"}]'::jsonb),
  ('15801', 'Zimadori Zinger', 'Punch / Party Drink', true, 'Collins glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/bw8gzx1485619920.jpg', NULL, 'Pour Zima in a collins glass over ice and then pour the shot of Midori. Don''t stir. Garnish with a cherry.', 'Vierta Zima en un vaso Collins sobre hielo y, a continuación, vierta el chupito de Midori. No revuelva. Adorne con una cereza.', '[{"name": "Midori melon liqueur", "image": "https://www.thecocktaildb.com/images/ingredients/Midori%20melon%20liqueur-small.png", "measure": "1.5 oz"}, {"name": "Zima", "image": "https://www.thecocktaildb.com/images/ingredients/Zima-small.png", "measure": "12 oz"}]'::jsonb),
  ('15813', 'Herbal flame', 'Coffee / Tea', true, 'Mason jar', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/rrstxv1441246184.jpg', NULL, 'Pour Hot Damn 100 in bottom of a jar or regular glass. Fill the rest of the glass with sweet tea. Stir with spoon, straw, or better yet a cinnamon stick and leave it in.', 'Vierta Hot Damn 100 en el fondo de un frasco o vaso normal. Llena el resto del vaso con té dulce. Revuelva con una cuchara, una pajita o, mejor aún, una rama de canela y déjela reposar.', '[{"name": "Hot Damn", "image": "https://www.thecocktaildb.com/images/ingredients/Hot%20Damn-small.png", "measure": "5 shots"}, {"name": "Tea", "image": "https://www.thecocktaildb.com/images/ingredients/Tea-small.png", "measure": "very sweet"}]'::jsonb),
  ('15825', 'Jamaican Coffee', 'Coffee / Tea', true, 'Champagne flute', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/xqptps1441247257.jpg', NULL, 'Stir the rum, coffee and water together. Top with the whipped cream. Sprinkle with a pinch of well ground coffee and drink with a straw.', 'Mezcle el ron, el café y el agua. Cubra con la crema batida. Espolvorea con una pizca de café bien molido y bebe con una pajita.', '[{"name": "Rum", "image": "https://www.thecocktaildb.com/images/ingredients/Rum-small.png", "measure": "1/6 glass"}, {"name": "Coffee", "image": "https://www.thecocktaildb.com/images/ingredients/Coffee-small.png", "measure": "1/6 glass strong black"}, {"name": "Water", "image": "https://www.thecocktaildb.com/images/ingredients/Water-small.png", "measure": "1/2 glass cold"}, {"name": "Whipped cream", "image": "https://www.thecocktaildb.com/images/ingredients/Whipped%20cream-small.png", "measure": null}]'::jsonb),
  ('15841', 'Mojito Extra', 'Cocktail', true, 'Collins glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/vwxrsw1478251483.jpg', NULL, 'Put mint with lemon juice in a glas, mash the mint with a spoon, ice, rum & fill up with club soda. Top it with Angostura.', 'Ponga menta con zumo de limón en un vaso, machaque la menta con una cuchara, hielo, ron y rellene con club soda. Añada Angostura.', '[{"name": "Mint", "image": "https://www.thecocktaildb.com/images/ingredients/Mint-small.png", "measure": "1/2 handful"}, {"name": "Lemon juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20juice-small.png", "measure": "3 cl"}, {"name": "Dark rum", "image": "https://www.thecocktaildb.com/images/ingredients/Dark%20rum-small.png", "measure": "1/8 L Jamaican"}, {"name": "Club soda", "image": "https://www.thecocktaildb.com/images/ingredients/Club%20soda-small.png", "measure": "1/8 L"}, {"name": "Angostura bitters", "image": "https://www.thecocktaildb.com/images/ingredients/Angostura%20bitters-small.png", "measure": "8 drops"}]'::jsonb),
  ('15853', 'B-52', 'Shot', true, 'Shot glass', 'New Era Drinks', '{IBA,NewEra}'::text[], 'https://www.thecocktaildb.com/images/media/drink/5a3vg61504372070.jpg', NULL, 'Layer ingredients into a shot glass. Serve with a stirrer.', 'Coloque los ingredientes en capas en un vaso de chupito. Servir con una batidora.', '[{"name": "Baileys irish cream", "image": "https://www.thecocktaildb.com/images/ingredients/Baileys%20irish%20cream-small.png", "measure": "1/3"}, {"name": "Grand Marnier", "image": "https://www.thecocktaildb.com/images/ingredients/Grand%20Marnier-small.png", "measure": "1/3"}, {"name": "Kahlua", "image": "https://www.thecocktaildb.com/images/ingredients/Kahlua-small.png", "measure": "1/4"}]'::jsonb),
  ('15933', 'Zambeer', 'Soft Drink', true, 'Collins Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/bje5401485619578.jpg', NULL, 'Mix sambuca with rootbeer and stir. Add ice', 'Mezcle la sambuca con cerveza de raíz y revuelva. agregar hielo', '[{"name": "Sambuca", "image": "https://www.thecocktaildb.com/images/ingredients/Sambuca-small.png", "measure": "1 1/2 oz"}, {"name": "Root beer", "image": "https://www.thecocktaildb.com/images/ingredients/Root%20beer-small.png", "measure": "Add 10 oz"}, {"name": "Ice", "image": "https://www.thecocktaildb.com/images/ingredients/Ice-small.png", "measure": "cubes"}]'::jsonb),
  ('15941', 'Americano', 'Ordinary Drink', true, 'Collins glass', 'Unforgettables', '{IBA,Classic}'::text[], 'https://www.thecocktaildb.com/images/media/drink/709s6m1613655124.jpg', 'https://www.youtube.com/watch?v=TmeUJ2g3ogM', 'Pour the Campari and vermouth over ice into glass, add a splash of soda water and garnish with half orange slice.', 'Vierta el Campari y el vermut sobre hielo en un vaso, añada un chorrito de soda y decore con media rodaja de naranja.', '[{"name": "Campari", "image": "https://www.thecocktaildb.com/images/ingredients/Campari-small.png", "measure": "1 oz"}, {"name": "Sweet Vermouth", "image": "https://www.thecocktaildb.com/images/ingredients/Sweet%20Vermouth-small.png", "measure": "1 oz red"}, {"name": "Lemon peel", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20peel-small.png", "measure": "Twist of"}, {"name": "Orange peel", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20peel-small.png", "measure": "Twist of"}]'::jsonb),
  ('15997', 'GG', 'Ordinary Drink', true, 'Collins Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/vyxwut1468875960.jpg', NULL, 'Pour the Galliano liqueur over ice. Fill the remainder of the glass with ginger ale and thats all there is to it. You now have a your very own GG.', 'Vierta el licor Galliano sobre hielo. Llene el resto del vaso con ginger ale y ya está. Ya tienes tu propio GG.', '[{"name": "Galliano", "image": "https://www.thecocktaildb.com/images/ingredients/Galliano-small.png", "measure": "2 1/2 shots"}, {"name": "Ginger ale", "image": "https://www.thecocktaildb.com/images/ingredients/Ginger%20ale-small.png", "measure": null}, {"name": "Ice", "image": "https://www.thecocktaildb.com/images/ingredients/Ice-small.png", "measure": null}]'::jsonb),
  ('16031', 'Radler', 'Ordinary Drink', true, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/xz8igv1504888995.jpg', NULL, 'Pour beer into large mug, slowly add the 7-up (or Sprite).', 'Vierte la cerveza en una jarra grande y añade lentamente la 7-up (o Sprite).', '[{"name": "Beer", "image": "https://www.thecocktaildb.com/images/ingredients/Beer-small.png", "measure": "12 oz"}, {"name": "7-Up", "image": "https://www.thecocktaildb.com/images/ingredients/7-Up-small.png", "measure": "12 oz"}]'::jsonb),
  ('16041', 'Mudslinger', 'Punch / Party Drink', true, 'Punch bowl', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/hepk6h1504885554.jpg', NULL, 'Add all contents to a large jug or punch bowl. Stir well!', 'Añada todo el contenido a una jarra grande o ponchera. Remuévalo bien.', '[{"name": "Southern Comfort", "image": "https://www.thecocktaildb.com/images/ingredients/Southern%20Comfort-small.png", "measure": "750 ml"}, {"name": "Orange juice", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20juice-small.png", "measure": "1 L"}, {"name": "Pepsi Cola", "image": "https://www.thecocktaildb.com/images/ingredients/Pepsi%20Cola-small.png", "measure": "750 ml"}]'::jsonb),
  ('16047', 'Campari Beer', 'Beer', true, 'Beer mug', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/xsqrup1441249130.jpg', NULL, 'Use a 15 oz glass. Add Campari first. Fill with beer.', 'Utilice un vaso de 15 oz. Agrega Campari primero. Llénelo con cerveza.', '[{"name": "Lager", "image": "https://www.thecocktaildb.com/images/ingredients/Lager-small.png", "measure": "1 bottle"}, {"name": "Campari", "image": "https://www.thecocktaildb.com/images/ingredients/Campari-small.png", "measure": "1 1/2 cl"}]'::jsonb),
  ('16108', '9 1/2 Weeks', 'Cocktail', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/xvwusr1472669302.jpg', NULL, 'Combine all ingredients in glass mixer. Chill and strain into Cocktail glass. Garnish with sliced strawberry.', 'Mezclar todos los ingredientes en una batidora de vaso. Enfríe y cuele en una copa de cóctel. Decorar con rodajas de fresa.', '[{"name": "Absolut Citron", "image": "https://www.thecocktaildb.com/images/ingredients/Absolut%20Citron-small.png", "measure": "2 oz"}, {"name": "Orange Curacao", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20Curacao-small.png", "measure": "1/2 oz"}, {"name": "Strawberry liqueur", "image": "https://www.thecocktaildb.com/images/ingredients/Strawberry%20liqueur-small.png", "measure": "1 splash"}, {"name": "Orange juice", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20juice-small.png", "measure": "1 oz"}]'::jsonb),
  ('16158', 'Whitecap Margarita', 'Other / Unknown', true, 'Margarita/Coupette glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/srpxxp1441209622.jpg', NULL, 'Place all ingredients in a blender and blend until smooth. This makes one drink.', 'Coloque todos los ingredientes en una licuadora y mezcle hasta que quede suave. Esto hace que uno beba.', '[{"name": "Ice", "image": "https://www.thecocktaildb.com/images/ingredients/Ice-small.png", "measure": "1 cup"}, {"name": "Tequila", "image": "https://www.thecocktaildb.com/images/ingredients/Tequila-small.png", "measure": "2 oz"}, {"name": "Cream of coconut", "image": "https://www.thecocktaildb.com/images/ingredients/Cream%20of%20coconut-small.png", "measure": "1/4 cup"}, {"name": "Lime juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lime%20juice-small.png", "measure": "3 tblsp fresh"}]'::jsonb),
  ('16178', 'Jitterbug', 'Cocktail', true, 'Cocktail Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/wwqvrq1441245318.jpg', NULL, 'Wet glass, dip rim in sugar. Then add Ice. Then add everything else. It''s that simple!', 'Moje el vaso, sumerja el borde en azúcar. A continuación, añada hielo. Luego añada todo lo demás. Así de sencillo.', '[{"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "2 jiggers"}, {"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "1 jigger"}, {"name": "Grenadine", "image": "https://www.thecocktaildb.com/images/ingredients/Grenadine-small.png", "measure": "3 dashes"}, {"name": "Lime juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lime%20juice-small.png", "measure": "1 shot"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "Around rim put 1 pinch"}, {"name": "Sugar syrup", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar%20syrup-small.png", "measure": "3 dashes"}, {"name": "Soda water", "image": "https://www.thecocktaildb.com/images/ingredients/Soda%20water-small.png", "measure": "Fill to top with"}]'::jsonb),
  ('16196', 'Moranguito', 'Shot', true, 'Shot glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/urpsyq1475667335.jpg', NULL, 'first you put rhe absinthe, then put tequila, then put the Granadine syrup.', 'Primero se pone ajenjo, luego se pone tequila, luego se pone el almíbar de granadina.', '[{"name": "Absinthe", "image": "https://www.thecocktaildb.com/images/ingredients/Absinthe-small.png", "measure": "2/5"}, {"name": "Tequila", "image": "https://www.thecocktaildb.com/images/ingredients/Tequila-small.png", "measure": "2/5"}, {"name": "Grenadine", "image": "https://www.thecocktaildb.com/images/ingredients/Grenadine-small.png", "measure": "1/5"}]'::jsonb),
  ('16250', 'Rum Runner', 'Punch / Party Drink', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/vqws6t1504888857.jpg', NULL, 'Mix all ingredients in glass & add ice.', 'Mezcle todos los ingredientes en un vaso y añada hielo.', '[{"name": "Malibu rum", "image": "https://www.thecocktaildb.com/images/ingredients/Malibu%20rum-small.png", "measure": "1 1/2 oz"}, {"name": "Blackberry brandy", "image": "https://www.thecocktaildb.com/images/ingredients/Blackberry%20brandy-small.png", "measure": "1 oz"}, {"name": "Orange juice", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20juice-small.png", "measure": "3-4 oz"}, {"name": "Pineapple juice", "image": "https://www.thecocktaildb.com/images/ingredients/Pineapple%20juice-small.png", "measure": "3-4 oz"}, {"name": "Cranberry juice", "image": "https://www.thecocktaildb.com/images/ingredients/Cranberry%20juice-small.png", "measure": "3-4 oz"}]'::jsonb),
  ('16262', 'H.D.', 'Coffee / Tea', true, 'Beer mug', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/upusyu1472667977.jpg', NULL, 'Mix the whisky and Baileys Cream in a beer-glass (at least 50 cl). Fill the rest of the glass with coffee.', 'Mezclar el whisky y la crema Baileys en un vaso de cerveza (al menos 50 cl). Llena el resto del vaso con café.', '[{"name": "Whisky", "image": "https://www.thecocktaildb.com/images/ingredients/Whisky-small.png", "measure": "4 cl"}, {"name": "Baileys irish cream", "image": "https://www.thecocktaildb.com/images/ingredients/Baileys%20irish%20cream-small.png", "measure": "8 cl"}, {"name": "Coffee", "image": "https://www.thecocktaildb.com/images/ingredients/Coffee-small.png", "measure": null}]'::jsonb),
  ('16273', 'Shark Attack', 'Cocktail', true, 'Pitcher', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/uv96zr1504793256.jpg', NULL, 'Mix lemonade and water according to instructions on back of can. If the instructions say to add 4 1/3 cans of water do so. Mix into pitcher. Add 1 1/2 cup of Vodka (Absolut). Mix well. Pour into glass of crushed ice. Excellent!', 'Mezcle limonada y agua según las instrucciones que se encuentran en la parte posterior de la lata. Si las instrucciones dicen que agregue 4 1/3 latas de agua, hágalo. Mezclar en la jarra. Agrega 1 1/2 taza de Vodka (Absolut). Mezclar bien. Vierta en un vaso de hielo picado. ¡Excelente!', '[{"name": "Lemonade", "image": "https://www.thecocktaildb.com/images/ingredients/Lemonade-small.png", "measure": "1 can"}, {"name": "Water", "image": "https://www.thecocktaildb.com/images/ingredients/Water-small.png", "measure": "3 cans"}, {"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "1 1/2 cup"}]'::jsonb),
  ('16275', 'Jack''s Vanilla Coke', 'Other / Unknown', true, 'Old-fashioned glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/kjnt7z1504793319.jpg', NULL, 'After pouring in your ingredients, and adding 3-5 ice cubes, according to taste. Stir the drink with a stirrer to get the Vanilla off the bottom.', 'Después de verter los ingredientes y añadir de 3 a 5 cubitos de hielo, según el gusto. Remueve la bebida con un agitador para que la vainilla se despegue del fondo.', '[{"name": "Ice", "image": "https://www.thecocktaildb.com/images/ingredients/Ice-small.png", "measure": "4-5"}, {"name": "Tennessee whiskey", "image": "https://www.thecocktaildb.com/images/ingredients/Tennessee%20whiskey-small.png", "measure": "2 oz"}, {"name": "Vanilla extract", "image": "https://www.thecocktaildb.com/images/ingredients/Vanilla%20extract-small.png", "measure": "1 tsp"}, {"name": "Coca-Cola", "image": "https://www.thecocktaildb.com/images/ingredients/Coca-Cola-small.png", "measure": "10-12 oz"}]'::jsonb),
  ('16419', 'Avalanche', 'Shake', true, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/uppqty1472720165.jpg', NULL, 'Mix in highball glass over ice, shake well.', 'Mezclar en un vaso highball con hielo y agitar bien.', '[{"name": "Crown Royal", "image": "https://www.thecocktaildb.com/images/ingredients/Crown%20Royal-small.png", "measure": "1 shot"}, {"name": "Kahlua", "image": "https://www.thecocktaildb.com/images/ingredients/Kahlua-small.png", "measure": "1 shot"}, {"name": "Cream", "image": "https://www.thecocktaildb.com/images/ingredients/Cream-small.png", "measure": "Fill with"}]'::jsonb),
  ('16485', 'Flaming Lamborghini', 'Cocktail', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/yywpss1461866587.jpg', NULL, 'Pour the Sambuca and Kahlua into the Cocktail Glass and give the drinker a straw. Pour the Baileys and Blue Curacao into two sepsrate shot glasses either side of the cocktail glass. Set light the concotion in the cocktail glass and start to drink through the straw (this drink should be drunk in one) , as the bottom of the glass is reached put out the fire by pouring the Baileys and Blue Curacao into the cocktail glass and keep drinking till it''s all gone!!', 'Verter la Sambuca y el Kahlua en la copa de cóctel y dar al bebedor una pajita. Vierta el Baileys y el Blue Curacao en dos vasos de chupito de sepsrate a cada lado de la copa de cóctel. Encienda la cocción en la copa de cóctel y empiece a beber con la pajita (esta bebida debe beberse de un trago), cuando llegue al fondo de la copa apague el fuego vertiendo el Baileys y el Blue Curacao en la copa de cóctel y siga bebiendo hasta que se acabe.', '[{"name": "Kahlua", "image": "https://www.thecocktaildb.com/images/ingredients/Kahlua-small.png", "measure": "1 oz"}, {"name": "Sambuca", "image": "https://www.thecocktaildb.com/images/ingredients/Sambuca-small.png", "measure": "1 oz"}, {"name": "Blue Curacao", "image": "https://www.thecocktaildb.com/images/ingredients/Blue%20Curacao-small.png", "measure": "1 oz"}, {"name": "Baileys irish cream", "image": "https://www.thecocktaildb.com/images/ingredients/Baileys%20irish%20cream-small.png", "measure": "1 oz"}]'::jsonb),
  ('16942', 'Zipperhead', 'Shot', true, 'Whiskey sour glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/r2qzhu1485620235.jpg', NULL, 'Fill glass with rocks, add straw before putting in liquor. Then add the ingredients in order, trying to keep layered as much as possible (i.e. Chambord on bottom, then Vodka, Then soda on top).', 'Llene el vaso con piedras, agregue pajita antes de poner el licor. Luego agregue los ingredientes en orden, tratando de mantenerlos en capas tanto como sea posible (es decir, Chambord abajo, luego vodka y luego refresco arriba).', '[{"name": "Chambord raspberry liqueur", "image": "https://www.thecocktaildb.com/images/ingredients/Chambord%20raspberry%20liqueur-small.png", "measure": "1 shot"}, {"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "1 shot"}, {"name": "Soda water", "image": "https://www.thecocktaildb.com/images/ingredients/Soda%20water-small.png", "measure": "Fill with"}]'::jsonb),
  ('16951', 'Kioki Coffee', 'Coffee / Tea', true, 'Coffee mug', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/uppqty1441247374.jpg', NULL, 'Stir. Add whipped cream to the top.', 'Remover. Agrega crema batida por encima.', '[{"name": "Kahlua", "image": "https://www.thecocktaildb.com/images/ingredients/Kahlua-small.png", "measure": "1 oz"}, {"name": "Brandy", "image": "https://www.thecocktaildb.com/images/ingredients/Brandy-small.png", "measure": "1/2 oz"}, {"name": "Coffee", "image": "https://www.thecocktaildb.com/images/ingredients/Coffee-small.png", "measure": null}]'::jsonb),
  ('16963', 'Zorbatini', 'Cocktail', true, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/wtkqgb1485621155.jpg', NULL, 'Prepare like a Martini. Garnish with a green olive.', 'Prepárate como un Martini. Adorne con una aceituna verde.', '[{"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "1 1/4 oz Stoli"}, {"name": "Ouzo", "image": "https://www.thecocktaildb.com/images/ingredients/Ouzo-small.png", "measure": "1/4 oz"}]'::jsonb),
  ('16967', 'Vodka Fizz', 'Other / Unknown', true, 'White wine glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/xwxyux1441254243.jpg', NULL, 'Blend all ingredients, save nutmeg. Pour into large white wine glass and sprinkle nutmeg on top.', 'Licue todos los ingredientes, guarde la nuez moscada. Vierta en una copa grande de vino blanco y espolvoree nuez moscada por encima.', '[{"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "2 oz"}, {"name": "Half-and-half", "image": "https://www.thecocktaildb.com/images/ingredients/Half-and-half-small.png", "measure": "2 oz"}, {"name": "Limeade", "image": "https://www.thecocktaildb.com/images/ingredients/Limeade-small.png", "measure": "2 oz"}, {"name": "Ice", "image": "https://www.thecocktaildb.com/images/ingredients/Ice-small.png", "measure": null}, {"name": "Nutmeg", "image": "https://www.thecocktaildb.com/images/ingredients/Nutmeg-small.png", "measure": null}]'::jsonb),
  ('16984', 'Radioactive Long Island Iced Tea', 'Ordinary Drink', true, 'Collins Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/rdvqmh1503563512.jpg', NULL, 'Pour all ingredients over ice in a very tall glass. Sip cautiously.', 'Vierta todos los ingredientes sobre hielo en un vaso muy alto. Beber con precaución.', '[{"name": "Rum", "image": "https://www.thecocktaildb.com/images/ingredients/Rum-small.png", "measure": "1 oz"}, {"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "1 oz"}, {"name": "Tequila", "image": "https://www.thecocktaildb.com/images/ingredients/Tequila-small.png", "measure": "1 oz"}, {"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "1 oz"}, {"name": "Triple sec", "image": "https://www.thecocktaildb.com/images/ingredients/Triple%20sec-small.png", "measure": "1 oz"}, {"name": "Chambord raspberry liqueur", "image": "https://www.thecocktaildb.com/images/ingredients/Chambord%20raspberry%20liqueur-small.png", "measure": "1 oz"}, {"name": "Midori melon liqueur", "image": "https://www.thecocktaildb.com/images/ingredients/Midori%20melon%20liqueur-small.png", "measure": "1 oz"}, {"name": "Malibu rum", "image": "https://www.thecocktaildb.com/images/ingredients/Malibu%20rum-small.png", "measure": "1 oz"}]'::jsonb),
  ('16985', 'Shot-gun', 'Shot', true, 'Shot glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/2j1m881503563583.jpg', NULL, 'Pour one part Jack Daneils and one part Jim Beam into shot glass then float Wild Turkey on top.', 'Vierta una parte de Jack Daneils y una parte de Jim Beam en un vaso de chupito y luego coloque Wild Turkey encima.', '[{"name": "Jim Beam", "image": "https://www.thecocktaildb.com/images/ingredients/Jim%20Beam-small.png", "measure": "1 part"}, {"name": "Jack Daniels", "image": "https://www.thecocktaildb.com/images/ingredients/Jack%20Daniels-small.png", "measure": "1 part"}, {"name": "Wild Turkey", "image": "https://www.thecocktaildb.com/images/ingredients/Wild%20Turkey-small.png", "measure": "1 oz"}]'::jsonb),
  ('16986', 'Bible Belt', 'Other / Unknown', true, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/6bec6v1503563675.jpg', NULL, 'Mix all ingredients, and pour over ice.', 'Mezcle todos los ingredientes y viértalos sobre hielo.', '[{"name": "Southern Comfort", "image": "https://www.thecocktaildb.com/images/ingredients/Southern%20Comfort-small.png", "measure": "2 oz"}, {"name": "Triple sec", "image": "https://www.thecocktaildb.com/images/ingredients/Triple%20sec-small.png", "measure": "1/2 oz"}, {"name": "Lime", "image": "https://www.thecocktaildb.com/images/ingredients/Lime-small.png", "measure": "2 wedges"}, {"name": "Sour mix", "image": "https://www.thecocktaildb.com/images/ingredients/Sour%20mix-small.png", "measure": "2 oz"}]'::jsonb),
  ('16987', 'Irish Curdling Cow', 'Cocktail', true, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/yrhutv1503563730.jpg', NULL, 'Pour Irish Cream, Vodka, and Bourbon in a glass. Add some ice and mix in the orange juice.', 'Vierta la crema irlandesa, el vodka y el bourbon en un vaso. Añade un poco de hielo y mezcla con el zumo de naranja.', '[{"name": "Baileys irish cream", "image": "https://www.thecocktaildb.com/images/ingredients/Baileys%20irish%20cream-small.png", "measure": "3/4 oz"}, {"name": "Bourbon", "image": "https://www.thecocktaildb.com/images/ingredients/Bourbon-small.png", "measure": "3/4 oz"}, {"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "3/4 oz"}, {"name": "Orange juice", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20juice-small.png", "measure": "2-3 oz"}]'::jsonb),
  ('16990', 'Sweet Tooth', 'Shake', true, 'Highball Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/j6rq6h1503563821.jpg', NULL, 'Put 2 shots Godiva Liquour into a glass, add as much or as little milk as you would like.', 'Ponga 2 tragos de Licor Godiva en un vaso, agregue tanta o tan poca leche como desee.', '[{"name": "Godiva liqueur", "image": "https://www.thecocktaildb.com/images/ingredients/Godiva%20liqueur-small.png", "measure": "2 shots"}, {"name": "Milk", "image": "https://www.thecocktaildb.com/images/ingredients/Milk-small.png", "measure": null}]'::jsonb),
  ('16991', 'Downshift', 'Punch / Party Drink', true, 'Hurricane glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/y36z8c1503563911.jpg', NULL, 'Start with the Sprite. Next comes the tequila. After that, add the Minute Maid Fruit Punch, then float the 151. Rocks optional.', 'Empieza con el Sprite. A continuación, el tequila. A continuación, añada Minute Maid Fruit Punch y deje flotar la 151. Rocas opcionales.', '[{"name": "Fruit punch", "image": "https://www.thecocktaildb.com/images/ingredients/Fruit%20punch-small.png", "measure": "2 part"}, {"name": "Sprite", "image": "https://www.thecocktaildb.com/images/ingredients/Sprite-small.png", "measure": "1 part"}, {"name": "Tequila", "image": "https://www.thecocktaildb.com/images/ingredients/Tequila-small.png", "measure": "2 shots"}, {"name": "151 proof rum", "image": "https://www.thecocktaildb.com/images/ingredients/151%20proof%20rum-small.png", "measure": "Float Bacardi"}]'::jsonb),
  ('16992', 'Pink Penocha', 'Punch / Party Drink', true, 'Punch bowl', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/6vigjx1503564007.jpg', NULL, 'mix all ingredients into bowl keep iced stir frequently', 'mezclar todos los ingredientes en un bol mantener en hielo remover con frecuencia', '[{"name": "Everclear", "image": "https://www.thecocktaildb.com/images/ingredients/Everclear-small.png", "measure": "750 ml"}, {"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "1750 ml"}, {"name": "Peach schnapps", "image": "https://www.thecocktaildb.com/images/ingredients/Peach%20schnapps-small.png", "measure": "1750 ml"}, {"name": "Orange juice", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20juice-small.png", "measure": "1 gal"}, {"name": "Cranberry juice", "image": "https://www.thecocktaildb.com/images/ingredients/Cranberry%20juice-small.png", "measure": "1 gal"}]'::jsonb),
  ('16995', 'Orange Whip', 'Other / Unknown', true, 'Collins Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/ttyrxr1454514759.jpg', NULL, 'Pour ingredients over ice and stir.', 'Vierta los ingredientes sobre el hielo y remueva.', '[{"name": "Orange juice", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20juice-small.png", "measure": "4 oz"}, {"name": "Rum", "image": "https://www.thecocktaildb.com/images/ingredients/Rum-small.png", "measure": "1 oz"}, {"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "1 oz"}, {"name": "Cream", "image": "https://www.thecocktaildb.com/images/ingredients/Cream-small.png", "measure": "1 package"}, {"name": "Ice", "image": "https://www.thecocktaildb.com/images/ingredients/Ice-small.png", "measure": "Over"}]'::jsonb),
  ('17006', 'Kool First Aid', 'Shot', true, 'Shot glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/hfp6sv1503564824.jpg', NULL, 'Add Kool Aid to a double shot glass, and top with rum. Slam and shoot.', 'Agregue Kool Aid a un vaso doble y cubra con ron. Golpea y dispara.', '[{"name": "151 proof rum", "image": "https://www.thecocktaildb.com/images/ingredients/151%20proof%20rum-small.png", "measure": "2 oz light"}, {"name": "Kool-Aid", "image": "https://www.thecocktaildb.com/images/ingredients/Kool-Aid-small.png", "measure": "1/2 tsp Tropical"}]'::jsonb),
  ('17015', 'Irish Russian', 'Beer', true, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/swqurw1454512730.jpg', NULL, 'Add the ingredients in the order listed in the recipe. Care must be taken when adding the Guinness to prevent an excess of foam. Do Not add ice.', 'Añadir los ingredientes en el orden indicado en la receta. Hay que tener cuidado al añadir la Guinness para evitar un exceso de espuma. No añada hielo.', '[{"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "1 shot"}, {"name": "Kahlua", "image": "https://www.thecocktaildb.com/images/ingredients/Kahlua-small.png", "measure": "1 shot"}, {"name": "Coca-Cola", "image": "https://www.thecocktaildb.com/images/ingredients/Coca-Cola-small.png", "measure": "1 dash"}, {"name": "Guinness stout", "image": "https://www.thecocktaildb.com/images/ingredients/Guinness%20stout-small.png", "measure": "Fill with"}]'::jsonb),
  ('17027', 'Zima Blaster', 'Ordinary Drink', true, 'Hurricane glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/1wifuv1485619797.jpg', NULL, 'Fill glass with ice. Pour in Chambord, then fill with Zima. Mix and enjoy.', 'Llene el vaso con hielo. Vierta Chambord y luego rellénelo con Zima. Mezclar y disfrutar.', '[{"name": "Zima", "image": "https://www.thecocktaildb.com/images/ingredients/Zima-small.png", "measure": "12 oz"}, {"name": "Chambord raspberry liqueur", "image": "https://www.thecocktaildb.com/images/ingredients/Chambord%20raspberry%20liqueur-small.png", "measure": "3 oz"}]'::jsonb),
  ('17035', 'Buccaneer', 'Beer', true, 'Beer pilsner', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/upvtyt1441249023.jpg', NULL, 'Pour the corona into an 18oz beer glass pour the bacardi limon into the beer stir very gently', 'Vierta la corona en un vaso de cerveza de 18 oz, vierta el limón bacardí en la cerveza y revuelva muy suavemente.', '[{"name": "Corona", "image": "https://www.thecocktaildb.com/images/ingredients/Corona-small.png", "measure": "1"}, {"name": "Bacardi Limon", "image": "https://www.thecocktaildb.com/images/ingredients/Bacardi%20Limon-small.png", "measure": "1 shot"}]'::jsonb),
  ('17044', 'Homemade Kahlua', 'Homemade Liqueur', true, 'Collins Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/uwtsst1441254025.jpg', NULL, 'Dissolve sugar in 2 cups of boiling water and add corn syrup. Dissolve the instant coffee in the remaining water. Pour syrup and coffee in a gallon jug. Let it cool. Add vodka and vanilla when cold. For the best result, let the mixture "mature" for 4-5 weeks.', 'Disolver el azúcar en 2 tazas de agua hirviendo y añadir el jarabe de maíz. Disuelva el café instantáneo en el agua restante. Vierta el jarabe y el café en una jarra de un galón. Dejar enfriar. Añada el vodka y la vainilla cuando esté frío. Para obtener el mejor resultado, deja que la mezcla "madure" durante 4-5 semanas.', '[{"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "2 1/2 cups"}, {"name": "Corn syrup", "image": "https://www.thecocktaildb.com/images/ingredients/Corn%20syrup-small.png", "measure": "1 cup"}, {"name": "Coffee", "image": "https://www.thecocktaildb.com/images/ingredients/Coffee-small.png", "measure": "1 1/2 oz instant"}, {"name": "Vanilla extract", "image": "https://www.thecocktaildb.com/images/ingredients/Vanilla%20extract-small.png", "measure": "2 oz"}, {"name": "Water", "image": "https://www.thecocktaildb.com/images/ingredients/Water-small.png", "measure": "3 cups boiling"}, {"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "1 fifth"}]'::jsonb),
  ('17060', '24k nightmare', 'Shot', true, 'Shot glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/yyrwty1468877498.jpg', NULL, 'Add over ice,shake and pour.', 'Agregue sobre hielo, agite y vierta.', '[{"name": "Goldschlager", "image": "https://www.thecocktaildb.com/images/ingredients/Goldschlager-small.png", "measure": "1/2 oz"}, {"name": "Jägermeister", "image": "https://www.thecocktaildb.com/images/ingredients/J%C3%A4germeister-small.png", "measure": "1/2 oz"}, {"name": "Rumple Minze", "image": "https://www.thecocktaildb.com/images/ingredients/Rumple%20Minze-small.png", "measure": "1/2 oz"}, {"name": "151 proof rum", "image": "https://www.thecocktaildb.com/images/ingredients/151%20proof%20rum-small.png", "measure": "1/2 oz Bacardi"}]'::jsonb),
  ('17105', '501 Blue', 'Ordinary Drink', true, 'Collins Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/ywxwqs1461867097.jpg', NULL, 'Mix equal amounts into a glass with ice.', 'Mezcle cantidades iguales en un vaso con hielo.', '[{"name": "Blue Curacao", "image": "https://www.thecocktaildb.com/images/ingredients/Blue%20Curacao-small.png", "measure": null}, {"name": "Blueberry schnapps", "image": "https://www.thecocktaildb.com/images/ingredients/Blueberry%20schnapps-small.png", "measure": null}, {"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": null}, {"name": "Sour mix", "image": "https://www.thecocktaildb.com/images/ingredients/Sour%20mix-small.png", "measure": null}, {"name": "7-Up", "image": "https://www.thecocktaildb.com/images/ingredients/7-Up-small.png", "measure": null}]'::jsonb),
  ('17108', 'Coke and Drops', 'Soft Drink', false, 'Cocktail glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/yrtxxp1472719367.jpg', NULL, 'Take a glass, pour the Coke in the glass, then you take 7 drops of lemon juice. Granish with a lemon slice on the rim of the glass.', 'Coge un vaso, vierte la Coca-Cola en el vaso, luego echa 7 gotas de zumo de limón. Adorne con una rodaja de limón en el borde del vaso.', '[{"name": "Coca-Cola", "image": "https://www.thecocktaildb.com/images/ingredients/Coca-Cola-small.png", "measure": "1 dl"}, {"name": "Lemon juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20juice-small.png", "measure": "7 drops"}]'::jsonb),
  ('17114', 'Ruby Tuesday', 'Cocktail', true, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/qsyqqq1441553437.jpg', NULL, 'Pour gin and cranberry into a highball filled with ice cubes. Add grenadine and stir.', 'Vierta ginebra y arándanos en un vaso alto lleno de cubitos de hielo. Agregue granadina y revuelva.', '[{"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "2 oz"}, {"name": "Cranberry juice", "image": "https://www.thecocktaildb.com/images/ingredients/Cranberry%20juice-small.png", "measure": "5 oz"}, {"name": "Grenadine", "image": "https://www.thecocktaildb.com/images/ingredients/Grenadine-small.png", "measure": "2 splashes"}]'::jsonb),
  ('17120', 'Brain Fart', 'Punch / Party Drink', true, 'Punch bowl', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/rz5aun1504389701.jpg', NULL, 'Mix all ingredients together. Slowly and gently. Works best if ice is added to punch bowl and soda''s are very cold.', 'Mezclar todos los ingredientes. Lenta y suavemente. Funciona mejor si se añade hielo a la ponchera y los refrescos están muy fríos.', '[{"name": "Everclear", "image": "https://www.thecocktaildb.com/images/ingredients/Everclear-small.png", "measure": "1 fifth"}, {"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "1 fifth Smirnoff red label"}, {"name": "Mountain Dew", "image": "https://www.thecocktaildb.com/images/ingredients/Mountain%20Dew-small.png", "measure": "2 L"}, {"name": "Surge", "image": "https://www.thecocktaildb.com/images/ingredients/Surge-small.png", "measure": "2 L"}, {"name": "Lemon juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20juice-small.png", "measure": "1 small bottle"}, {"name": "Rum", "image": "https://www.thecocktaildb.com/images/ingredients/Rum-small.png", "measure": "1 pint"}]'::jsonb),
  ('17122', 'Royal Bitch', 'Shot', true, 'Shot glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/qupuyr1441210090.jpg', NULL, 'Into a shot glass layer the Crown Royal on top of the Frangelico.', 'En un vaso de chupito, coloque la Crown Royal encima del Frangelico.', '[{"name": "Frangelico", "image": "https://www.thecocktaildb.com/images/ingredients/Frangelico-small.png", "measure": "1 part"}, {"name": "Crown Royal", "image": "https://www.thecocktaildb.com/images/ingredients/Crown%20Royal-small.png", "measure": "1 part"}]'::jsonb),
  ('17135', 'Citrus Coke', 'Soft Drink', true, 'Highball Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/uyrvut1479473214.jpg', NULL, 'Pour half of coke in a glass. Then add Bacardi and top it off with the remaining coke. Stir and drink up!', 'Vierte la mitad de la coca-cola en un vaso. Añade Bacardi y completa con el resto de la Coca-Cola. Remueve y ¡a beber!', '[{"name": "Bacardi Limon", "image": "https://www.thecocktaildb.com/images/ingredients/Bacardi%20Limon-small.png", "measure": "1 part"}, {"name": "Coca-Cola", "image": "https://www.thecocktaildb.com/images/ingredients/Coca-Cola-small.png", "measure": "2 parts"}]'::jsonb),
  ('17141', 'Smut', 'Punch / Party Drink', true, 'Beer mug', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/rx8k8e1504365812.jpg', NULL, 'Throw it all together and serve real cold.', 'Mézclalo todo y sírvelo bien frío.', '[{"name": "Red wine", "image": "https://www.thecocktaildb.com/images/ingredients/Red%20wine-small.png", "measure": "1/3 part"}, {"name": "Peach schnapps", "image": "https://www.thecocktaildb.com/images/ingredients/Peach%20schnapps-small.png", "measure": "1 shot"}, {"name": "Pepsi Cola", "image": "https://www.thecocktaildb.com/images/ingredients/Pepsi%20Cola-small.png", "measure": "1/3 part"}, {"name": "Orange juice", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20juice-small.png", "measure": "1/3 part"}]'::jsonb),
  ('17167', 'Raspberry Cooler', 'Other / Unknown', true, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/suqyyx1441254346.jpg', NULL, 'Pour the raspberry vodka and soda into a highball glass almost filled with ice cubes. Stir well.', 'Vierta el vodka de frambuesa y la soda en un vaso highball casi lleno de cubitos de hielo. Remuévalo bien.', '[{"name": "Raspberry vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Raspberry%20vodka-small.png", "measure": "2 oz"}, {"name": "Lemon-lime soda", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon-lime%20soda-small.png", "measure": "4 oz"}, {"name": "Ice", "image": "https://www.thecocktaildb.com/images/ingredients/Ice-small.png", "measure": null}]'::jsonb),
  ('17176', 'Ipamena', 'Ordinary Drink', false, 'Wine Glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/yswuwp1469090992.jpg', NULL, 'Cut half a lime into pieces, place in a shaker, add the sugar and crush. Measure the passion fruit juice, add it to the shaker and fill up with ice cubes. Close the shaker and shake vigorously. Pour the liquid into a glass, top up with ginger ale, stir with a teaspoon and then garnish the rim of the glass with a slice of lime', 'Cortar media lima en trozos, colocar en una coctelera, añadir el azúcar y triturar. Mide el jugo de maracuyá, agrégalo a la coctelera y rellena con cubitos de hielo. Cierra la coctelera y agita vigorosamente. Vierta el líquido en un vaso, rellénelo con ginger ale, revuelva con una cucharadita y luego decore el borde del vaso con una rodaja de lima.', '[{"name": "Lime", "image": "https://www.thecocktaildb.com/images/ingredients/Lime-small.png", "measure": "½"}, {"name": "Brown sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Brown%20sugar-small.png", "measure": "2 tsp"}, {"name": "Passion fruit juice", "image": "https://www.thecocktaildb.com/images/ingredients/Passion%20fruit%20juice-small.png", "measure": "4 cl"}, {"name": "Ginger ale", "image": "https://www.thecocktaildb.com/images/ingredients/Ginger%20ale-small.png", "measure": "top up with"}, {"name": "Ice", "image": "https://www.thecocktaildb.com/images/ingredients/Ice-small.png", "measure": "fill"}]'::jsonb),
  ('17177', 'Dark Caipirinha', 'Cocktail', true, 'Highball glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/uwstrx1472406058.jpg', NULL, 'Muddle the sugar into the lime wedges in an old-fashioned glass.
Fill the glass with ice cubes.
Pour the cachaca into the glass.
Stir well.', 'Mezcle el azúcar con los gajos de lima en un vaso old-fashioned.
Llene el vaso con cubitos de hielo.
Vierta la cachaca en el vaso.
Remuévalo bien.', '[{"name": "demerara Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/demerara%20Sugar-small.png", "measure": "2 tsp"}, {"name": "Lime", "image": "https://www.thecocktaildb.com/images/ingredients/Lime-small.png", "measure": "1"}, {"name": "Cachaca", "image": "https://www.thecocktaildb.com/images/ingredients/Cachaca-small.png", "measure": "2 1/2 oz"}]'::jsonb),
  ('17178', 'Jam Donut', 'Shot', true, 'Shot glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/uuytrp1474039804.jpg', NULL, 'Coat the rim of a shot glass with sugar using sugar syrup to stick. Add the Chambord raspberry liqueur to the shot glass, and carefully layer the Baileys Irish Cream on top. Serve.', 'Cubra el borde de un vaso de chupito con azúcar usando jarabe de azúcar para que se pegue. Agregue el licor de frambuesa Chambord al vaso de chupito y con cuidado coloque una capa de crema irlandesa Baileys encima. Atender.', '[{"name": "Baileys irish cream", "image": "https://www.thecocktaildb.com/images/ingredients/Baileys%20irish%20cream-small.png", "measure": "2/3 oz"}, {"name": "Chambord raspberry liqueur", "image": "https://www.thecocktaildb.com/images/ingredients/Chambord%20raspberry%20liqueur-small.png", "measure": "1/3 oz"}, {"name": "Sugar syrup", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar%20syrup-small.png", "measure": "1 tsp"}, {"name": "Sugar", "image": "https://www.thecocktaildb.com/images/ingredients/Sugar-small.png", "measure": "2 pinches"}]'::jsonb),
  ('17180', 'Aviation', 'Cocktail', true, 'Cocktail glass', 'Unforgettables', '{IBA,Classic}'::text[], 'https://www.thecocktaildb.com/images/media/drink/trbplb1606855233.jpg', 'https://www.youtube.com/watch?v=oOHH0GGglyM', 'Add all ingredients into cocktail shaker filled with ice. Shake well and strain into cocktail glass. Garnish with a cherry.', 'Añada todos los ingredientes en una coctelera llena de hielo. Agitar bien y colar en una copa de cóctel. Decorar con una cereza.', '[{"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "4.5 cl"}, {"name": "lemon juice", "image": "https://www.thecocktaildb.com/images/ingredients/lemon%20juice-small.png", "measure": "1.5 cl"}, {"name": "maraschino liqueur", "image": "https://www.thecocktaildb.com/images/ingredients/maraschino%20liqueur-small.png", "measure": "1.5 cl"}]'::jsonb),
  ('17181', 'Dirty Martini', 'Cocktail', true, 'Cocktail glass', 'New Era Drinks', '{IBA,NewEra}'::text[], 'https://www.thecocktaildb.com/images/media/drink/vcyvpq1485083300.jpg', NULL, 'Pour the vodka, dry vermouth and olive brine into a cocktail shaker with a handful of ice and shake well.
Rub the rim of a martini glass with the wedge of lemon.
Strain the contents of the cocktail shaker into the glass and add the olive.
A dirty Martini contains a splash of olive brine or olive juice and is typically garnished with an olive.', 'Vierta el vodka, el vermut seco y la salmuera de aceitunas en una coctelera con un puñado de hielo y agite bien.
Frotar el borde de una copa de martini con la rodaja de limón.
Cuele el contenido de la coctelera en la copa y añada la aceituna.
Un martini sucio contiene un chorrito de salmuera de aceituna o zumo de aceituna y suele adornarse con una aceituna.', '[{"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "70ml/2fl oz"}, {"name": "Dry Vermouth", "image": "https://www.thecocktaildb.com/images/ingredients/Dry%20Vermouth-small.png", "measure": "1 tbsp"}, {"name": "Olive Brine", "image": "https://www.thecocktaildb.com/images/ingredients/Olive%20Brine-small.png", "measure": "2 tbsp"}, {"name": "Lemon", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon-small.png", "measure": "1 wedge"}, {"name": "Olive", "image": "https://www.thecocktaildb.com/images/ingredients/Olive-small.png", "measure": "1"}]'::jsonb),
  ('17182', 'Duchamp''s Punch', 'Cocktail', true, 'Old-fashioned glass', NULL, '{}'::text[], 'https://www.thecocktaildb.com/images/media/drink/g51naw1485084685.jpg', NULL, 'Shake all ingredients.
Double strain in a chilled double old fashioned glass with abig ice cube.
Garnish with a couple of lavender sprigs', 'Agitar todos los ingredientes.
Cuele dos veces en un vaso old fashioned doble con un cubito de hielo grande.
Decorar con un par de ramitas de lavanda.', '[{"name": "Pisco", "image": "https://www.thecocktaildb.com/images/ingredients/Pisco-small.png", "measure": "5 cl"}, {"name": "Lime Juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lime%20Juice-small.png", "measure": "2.5 cl"}, {"name": "Pineapple Syrup", "image": "https://www.thecocktaildb.com/images/ingredients/Pineapple%20Syrup-small.png", "measure": "2.5 cl"}, {"name": "St. Germain", "image": "https://www.thecocktaildb.com/images/ingredients/St.%20Germain-small.png", "measure": "1.5 cl"}, {"name": "Angostura Bitters", "image": "https://www.thecocktaildb.com/images/ingredients/Angostura%20Bitters-small.png", "measure": "2 Dashes"}, {"name": "Pepper", "image": "https://www.thecocktaildb.com/images/ingredients/Pepper-small.png", "measure": "Pinch"}, {"name": "Lavender", "image": "https://www.thecocktaildb.com/images/ingredients/Lavender-small.png", "measure": "2 sprigs"}]'::jsonb),
  ('17185', 'Casino', 'Ordinary Drink', true, 'Cocktail glass', 'Unforgettables', '{IBA}'::text[], 'https://www.thecocktaildb.com/images/media/drink/1mvjxg1504348579.jpg', 'https://www.youtube.com/watch?v=C6v8NsaDNj8', 'Pour all ingredients into shaker with ice cubes. Shake well. Strain into chilled cocktail glass. Garnish with a lemon twist and a maraschino cherry. Serve without a straw.', 'Vierta todos los ingredientes en una coctelera con cubitos de hielo. Agitar bien. Colar en una copa de cóctel fría. Decorar con un twist de limón y una cereza al marrasquino. Servir sin pajita.', '[{"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "2 oz"}, {"name": "Maraschino liqueur", "image": "https://www.thecocktaildb.com/images/ingredients/Maraschino%20liqueur-small.png", "measure": "1/4 tsp"}, {"name": "Lemon juice", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20juice-small.png", "measure": "1/4 tsp"}, {"name": "Orange bitters", "image": "https://www.thecocktaildb.com/images/ingredients/Orange%20bitters-small.png", "measure": "2 dashes"}, {"name": "Cherry", "image": "https://www.thecocktaildb.com/images/ingredients/Cherry-small.png", "measure": "1"}]'::jsonb),
