  ('17203', 'Kir', 'Ordinary Drink', true, 'Wine Glass', NULL, '{IBA,ContemporaryClassic}'::text[], 'https://www.thecocktaildb.com/images/media/drink/apneom1504370294.jpg', NULL, 'Add the crème de cassis to the bottom of the glass, then top up with wine.', 'Agregue la crema de cassis al fondo del vaso y luego complete con vino.', '[{"name": "Creme de Cassis", "image": "https://www.thecocktaildb.com/images/ingredients/Creme%20de%20Cassis-small.png", "measure": "1 part"}, {"name": "Champagne", "image": "https://www.thecocktaildb.com/images/ingredients/Champagne-small.png", "measure": "5 parts"}]'::jsonb),
  ('17204', 'Long Island Iced Tea', 'Ordinary Drink', true, 'Highball glass', 'Contemporary Classics', '{IBA,ContemporaryClassic}'::text[], 'https://www.thecocktaildb.com/images/media/drink/wx7hsg1504370510.jpg', NULL, 'Mix all contents in a highball glass and sitr gently. Add dash of Coca-Cola for the coloring and garnish with lemon or lime twist.', 'Mezcle todo el contenido en un vaso highball y siéntelo suavemente. Añada un chorrito de Coca-Cola para dar color y decore con un twist de limón o lima.', '[{"name": "Vodka", "image": "https://www.thecocktaildb.com/images/ingredients/Vodka-small.png", "measure": "1/2 oz"}, {"name": "Tequila", "image": "https://www.thecocktaildb.com/images/ingredients/Tequila-small.png", "measure": "1/2 oz"}, {"name": "Light rum", "image": "https://www.thecocktaildb.com/images/ingredients/Light%20rum-small.png", "measure": "1/2 oz"}, {"name": "Gin", "image": "https://www.thecocktaildb.com/images/ingredients/Gin-small.png", "measure": "1/2 oz"}, {"name": "Coca-Cola", "image": "https://www.thecocktaildb.com/images/ingredients/Coca-Cola-small.png", "measure": "1 dash"}, {"name": "Lemon peel", "image": "https://www.thecocktaildb.com/images/ingredients/Lemon%20peel-small.png", "measure": "Twist of"}]'::jsonb),
